\subsection{The Max-Plus Semiring}\label{subsec:maxPlusSemiring}
In this paper, we use the max-plus semiring whose base set consists of real numbers. This choice is inessential and our results apply to other base sets such as $\mathbb{Z} \cup \set{-\infty}$ and $\mathbb{Q} \cup \set{-\infty}$. The notation $\rmax$ is standard in the community; see e.g.~\cite{akian2009linear}. 
Refer to~\cite{droste2009handbook} for the general theory of semirings and semimodules.
\begin{mydefinition}[the max-plus semiring $\rmax$]
    \emph{The max-plus semiring} $\rmax$ is a semiring defined as follows.
    \begin{itemize}
        \item The base set is $\real \cup \set{-\infty}$, where $-\infty$ is  a symbol denoting the negative infinity.
        \item (Addition $\oplus_{\rmax}$) $a\oplus_{\rmax} b$ is $\max_\real (a, b)$ if $a,b\in \real$; it is $a$ if $b=-\infty$; and it is $b$ if $a=-\infty$.
\begin{auxproof}
 The addition $\oplus_{\rmax}$ is defined by
        \begin{align}
            a\oplus_{\rmax} b = 
            \begin{cases}
                \max_\real (a, b) &; a, b \in \real\\
                a &; a\in \real, b=-\infty\\
                b &; b\in \real, a=-\infty\\
                -\infty &; a=b=-\infty
            \end{cases}.
        \end{align}
\end{auxproof}        
\item (Multiplication $\otimes_{\rmax}$) $a\otimes_{\rmax} b = a +_\real b$ if $a,b\in \real$; $a\otimes_{\rmax} b = -\infty$ otherwise.
% \begin{auxproof}
%   The multiplication $\otimes_{\rmax}$ is defined by
%         \begin{align}
%             a\oplus_{\rmax} b =
%             \begin{cases}
%                 a +_\real b &; a, b\in \real\\
%                 -\infty &; \text{otherwise}
%             \end{cases}.
%         \end{align}
%     \end{auxproof}
\item (Units) $0_{\rmax}=-\infty$, and  $1_{\rmax}=0_\real$.
    \end{itemize}
The subscripts $\bullet_{\rmax}$ may be omitted when they are clear from the context.
Obviously, $\rmax$ is commutative.
\defend
\end{mydefinition}

Over the max-plus semiring, 
a particular form of a system of linear equations can be solved efficiently~\cite{thebook}. The procedure consists of computing a solution candidate---it is called a \emph{principal solution}, following the convention in the community~\cite{thebook}, but we emphasize that a principal solution \emph{may not be a solution}---and checking whether the candidate is indeed a solution or not. This procedure is known to be complete: if the principal solution turns out to be not a solution, then the linear equation has no solution.

\begin{mydefinition}[principal solution]
    \label{def:principal_solution}
Consider a system of linear equations $xA=b$, where $A\in \rmax^{n\times m}$ is a coefficient matrix, $b\in \rmax^m$ is a row vector and $x\in \rmax^n$ is an indeterminate row vector. Its \emph{principal solution} is defined by
    \begin{displaymath}\label{eq:principalSol}
    \footnotesize
\begin{array}{c}
         x(i) = 
        \begin{cases}
            \min_{j\in [1,m]} ({b(j) - A(i,j)}) &\text{if } A(i,:)\neq(-\infty,\dots,-\infty)\\
            -\infty &\text{if } A(i,:)=(-\infty,\dots,-\infty)
        \end{cases}
\end{array}    \quad\text{for $i=1,\dots,n$}.
\end{displaymath}

%     For a matrix $A\in \rmax^{n\times m}$, $b\in \rmax^m$ and indeterminate $x\in \rmax^n$, the \emph{principal solution} of a system of linear equations $xA=b$ is \footnote{The usual definition (e.g.\ in~\cite{thebook}) assumes that no row is $(-\infty, \dots, -\infty)$.  We do not do so; instead we add the second case in~(\ref{eq:principalSol}) as a workaround.
%  % we add the workaround to evaluate $x_i$ as $-\infty$ in the solution.
% } 
%     \begin{align}\label{eq:principalSol}
%         x_i &= 
%         \begin{cases}
%             \min_{j\in [1,m]} ({b_j - a_{ij}}) &\text{if } a_i\neq(-\infty,\dots,-\infty)\\
%             -\infty &\text{if } a_i=(-\infty,\dots,-\infty)
%         \end{cases}
%     \end{align}
%     for $i=1,\dots,n$.
    \defend
\end{mydefinition}
Although the usual definition (e.g.\ in~\cite{thebook}) assumes that no row of $A$ is $(-\infty, \dots, -\infty)$, we do not do so; instead, we add the second clause as a workaround. Notice that this second clause resolves the apparent problem in $\min$ in the first clause: if $A(i,j)=-\infty$ then $b(j) - A(i,j)$ should be $+\infty$ that does not belong to $\rmax$; but the condition $A(i,:)\neq(-\infty,\dots,-\infty)$ ensures that there is some $j$ for which $b(j) - A(i,j)$ is well-defined.

% The $\min$ expression in~(\ref{eq:principalSol}) seems problematic when $a_{ij}=-\infty$, in which case $b_{j}-a_{ij}$ should be $+\infty$ that is not an element of the semiring. This is not a real problem since it is assumed that $a_i\neq(-\infty,\dots,-\infty)$---there is some $j$ such that $a_{ij}\neq-\infty$ and this $a_{ij}$ will be used for the minimum.




% The value $b_j-a_{ij}$ is evaluated to $+\infty$ temporarily, but by taking the minimum of $\set{b_j-a_{ij}\mid j=1,\dots,m}$, the value $x_i$ is finally in $\rmax$.
% The principal solution may or may not be the solution of the system of linear equations, but if it is not, then the system is unsolvable.
% Hence, the algorithm to solve a system of linear equations on the max-plus semiring is to: (1) calculate the principal solution, and (2) check if the principal solution is a solution.
We note that multiple solutions may exist for $xA=b$. It is known that, if the principal solution is a solution and there is no row filled with $-\infty$ in $A$, then it is the maximum among the solutions in the pointwise order. It is also obvious that a system of the form $XA=B$ can be solved, where  $X, A, B$ are matrices, by solving $X(k,:)\cdot A=B(k,:)$ for each $k$~\cite{Cuninghame-Green}.


% Remark that multiple solutions may exist in general.
% If the principal solution is a solution, then it is maximum among the solutions in the pointwise partial order.
% We can also solve a system of form $XA=B$ for matrices $X, A, B$, by solving $x_iA=b_i$ repeatedly~\cite{Cuninghame-Green}.

 There are several definitions known for linear independence in the max-plus semiring (they are not mutually equivalent). We find the following one suited for our purpose.
\begin{mydefinition}[weak linear (in)dependence~\cite{Cuninghame-Green}]\label{def:weakLinINdep}
 Let $M$ be  a semimodule over a commutative semiring $\semiring$, and  $X\subseteq M$ be a subset. $X$ is \emph{weakly linearly dependent} if there exists an element $x\in X$ such that $x$ can be expressed as a linear combination $\bigoplus_{\lambda}c_{\lambda}\otimes x_{\lambda}$
% \mw{If we have space, you should explicitly write the definition because this is not the standard linear combination but its semiring generalization} 
of  elements $x_{\lambda}\in X\setminus\set{x}$.  If $X$ is not weakly linearly dependent, it is said to be \emph{weakly linearly independent}.
    \defend
\end{mydefinition}


\begin{auxproof}
 It is known that, for each finitely generated semimodule,  the number of any weakly linearly independent generators is the same. This determines the \emph{weak dimension}~\cite{akian2009linear}.
 \begin{mydefinition}[weak dimension]
    For a finitely generated semimodule $M\subseteq \rmax^n$, the unique cardinality of its weakly linearly independent generators is referred to as the \emph{weak dimension}, and written as $\dimw(M)$.
    \defend
 \end{mydefinition}
\end{auxproof}


\subsection{Weighted Automata} 
\begin{mydefinition}[WFA]
    A \emph{weighted finite automaton (WFA)} over a semiring $\semiring$ is a tuple $(\Sigma, \alpha, \beta, (A_\sigma)_{\sigma \in \Sigma})$, where
    $\Sigma$ is a finite set  (\emph{alphabet}), $\alpha$ is a row vector in $\semiring^d$  (\emph{initial vector}), $\beta$ is a column vector in $\semiring^d$  (\emph{final vector}),
    and $A_\sigma$ is a matrix of size $d\times d$ called \emph{transition matrix} of $\sigma\in\Sigma$.
The size $d$ of the vectors and matrices is called \emph{the number of states} and denoted by $|A|$.
    \defend
\end{mydefinition}
% \mw{Perhaps you want to call $d$ as the dimension of the WFA instead of the number of states}

% The usual notion of language is a set of words, and it  is 
% %As deterministic finite automata induce a language, which is
%  equivalent to a function $\Sigma^*\to\set{0, 1}$. WFAs weighted in $\semiring$ induce \emph{weighted languages} $\Sigma^{*}\to\semiring$.
% , which is a function from $\Sigma^*$ to $\semiring$ as follows:
\begin{mydefinition}[configuration, weighted language induced from WFA]
    \\For a WFA $A=(\Sigma, \alpha, \beta, (A_\sigma)_{\sigma \in \Sigma})$, \emph{the configuration} of $A$ is a function $\delta_A\colon \Sigma^*\to \semiring^d$ defined by
    \begin{displaymath}
        \delta_A(w_1\dots w_n) = \alpha A_{w_1} \dots A_{w_n}.
    \end{displaymath}
    \\A WFA $A=(\Sigma, \alpha, \beta, (A_\sigma)_{\sigma \in \Sigma})$ induces a function $f_A\colon \Sigma^*\to \semiring$ defined by \\$f_A(w_1\dots w_n) = \alpha A_{w_1} \dots A_{w_n} \beta$.
    % \begin{displaymath}
    %     f_A(w_1\dots w_n) = \alpha A_{w_1} \dots A_{w_n} \beta.
    % \end{displaymath}
   This $f_{A}$ is called the \emph{weighted language} induced by $A$.

A weighted language that is induced by some WFA is said to be  \emph{rational}.
For a WFA $A$, if there is no WFA that has the same weighted language and has a smaller number of states than $A$, then  $A$ is said to be \emph{minimal}.
    \defend
\end{mydefinition}

% Weighted languages that are induced from WFAs are called \emph{rational}.
% For a WFA $A$, if there exists no WFA that has an induced weighted language equivalent to $A$ and a smaller number of states than $A$, then the WFA $A$ is said to be \emph{minimal}.
% For a WFA $A$, if there exists no WFAs of smaller number of states and of equivalent induced weighted language to $f_A$, the WFA $A$ is called \emph{minimal}.

 We use matrices whose rows and columns are  indexed  by words.
For label sets $P, S\subseteq \Sigma^*$ and a matrix $A\in \semiring^{P\times S}$, $A(p, s)\in \semiring$ is the entry at the  $p$-th row and the $s$-th column. 


The \emph{Hankel matrix} of a language $L$ is a mathematical construct that is behind  \lstar-style automata learning. Its $p$-th row, for $p\in \Sigma^*$, is the left-derivative of $L$ by $p$. 
% In the automata theory, the Brzozowski derivative of languages plays an important role.
% The following \emph{Hankel matrix} lists the counterpart of the Brzozowski derivative for weighted languages, and plays an important role in the analysis of the weighted language.
\begin{mydefinition}[Hankel matrix]
    Let $\Sigma$ be an alphabet and $\semiring$ be a semiring.
    \emph{A Hankel matrix} $H$ is a matrix $\semiring^{\Sigma^*\times\Sigma^*}$ such that $H(r\sigma, s) = H(r, \sigma s)$ for any $r,s\in\Sigma^*$ and $\sigma \in \Sigma$.
A weighted language $f\colon \Sigma^*\to \semiring$ induces a Hankel matrix, denoted by $H_f\in\semiring^{\Sigma^*\times \Sigma^*}$, by $H_f(p, s) = f(p\cdot s)$ for words $p, s\in \Sigma^*$.
    \defend
\end{mydefinition}
\begin{auxproof}
 Hankel matrices are defined for usual languages (subsets of $\Sigma^*$) in the same manner, and the entries are $0$ or $1$ indicating if the word is accepted or rejected by the language.
\end{auxproof}
Hankel matrices are of infinite size, so algorithms use the following finite restrictions. In particular, Hankel subblocks correspond to the tables in \lstar-style algorithms (Fig.~\ref{fig:lstar}). 
% Since Hankel matrices are conceptual, in a sense that it contains infinite data, we consider its finite approximation by looking at the finite part.
\begin{mydefinition}[Hankel mask, Hankel subblock]
    \label{def:hankelmask}
    For an alphabet $\Sigma$, a \emph{Hankel mask} $(P, S)$ is a pair of subsets of $\Sigma^*$.
  The \emph{Hankel subblock} of a Hankel matrix $H$ masked by $(P, S)$, denoted by $H_{(P, S)}$, is the matrix $\semiring^{P\times S}$ such that $H_{(P, S)}(p, s) = H(p, s)$ for any $p \in P, s\in S$.
    \defend
\end{mydefinition}
Remark that the indexing of a Hankel subblock and the mask of the subblock does necessarily coincide.
For example, though the mask of $H_{(P\sigma, S)}$ is $(P\sigma, S)$, where $\sigma\in \Sigma$, $H_{(P\sigma, S)}$ is usually indexed by $P\times S$, which means, $H_{(P\sigma, S)}(p, s) = H(p\sigma, s)$.




\section{WFA Learning for General Semirings}\label{sec:columnClosedness}
Here we introduce our algorithm, in which our new notion of column-closedness  replaces consistency (see \S{}\ref{sec:intro}). We present the algorithm for a general semiring $\semiring$, and prove its ``correctness'' (we say \emph{faithfulness}), i.e.\ that the learned WFA respects the weights given by the membership oracle. Later in~\S{}\ref{subsec:HeerdtEtAlDoesNotWork} we show the problem with the existing algorithm from~\cite{DBLP:conf/fossacs/HeerdtKR020} how it is resolved.



