\subsection{Row-Closedness and Column-Closedness}
\label{subsec:theory}
% The keys of our max-plus \lstar\ are how to check if the data in the Hankel subblock are enough to construct a WFA (Step 4), and how to construct the WFA (Step 5).
% We start with the definitions to describe the condition for the check and construction.
\begin{mydefinition}[row-closedness, column-closedness]\label{def:rowClmClosed}
Let $H\in\semiring^{\Sigma^*\times\Sigma^*}$ be a Hankel matrix, $P\subseteq \Sigma^*$ be prefix-closed,  and $S\subseteq \Sigma^*$ be suffix-closed.
% \begin{itemize}
%  \item    
  The Hankel subblock $H_{(P, S)}$ is \emph{row-closed} if the system of linear equations $X_\sigma H_{(P, S)}=H_{(P\sigma, S)}$ has a solution for any $\sigma\in \Sigma$.
   Here $X_\sigma\in \semiring^{P\times P}$ is the indeterminate matrix.
%  \item 
 Dually, $H_{(P, S)}$ is \emph{column-closed} if the system of linear equations $H_{(P, S)}Y_\sigma=H_{(P, \sigma S)}$ has a solution for any $\sigma\in \Sigma$.
   Here $Y_\sigma\in \semiring^{S\times S}$ is the indeterminate matrix.
    \defend
% \end{itemize}
\end{mydefinition}
These $X_\sigma$ and $Y_\sigma$ are used in whole this section.

 Row-closedness means that each row of $H_{(P\sigma, S)}$ is a linear combination of the rows of $H_{(P, S)}$; this is the usual condition of \emph{closedness} used in WFA learning~\cite{DBLP:conf/cai/BalleM15,DBLP:conf/fossacs/HeerdtKR020}. Our notion of column-closedness is its dual,  meaning that each column of $H_{(P, \sigma S)}$  is a linear combination of the columns of $H_{(P, S)}$. Note that, in column-closedness, the column-index set $S$ is extended \emph{backward} to $\sigma S$.

\begin{mylemma}
    \label{lem:exchange}
    Let $H_{(P, S)}$ be row-closed and column-closed, and $X_{\sigma}$ and $Y_{\sigma}$ be solutions of the equations in Def.~\ref{def:rowClmClosed}.
Then we have $X_\sigma H_{(P, S)} = H_{(P, S)}Y_\sigma$. 
\end{mylemma}
\begin{myproof}
    $X_\sigma H_{(P, S)} = H_{(P\sigma, S)} = H_{(P, \sigma S)} =  H_{(P, S)}Y_\sigma$.
\end{myproof}
Remark that $H_{(P\sigma, S)}$ and $H_{(P, \sigma S)}$ are indexed by $P\times S$.  See the remark of Definition~\ref{def:hankelmask}.
\begin{auxproof}
