\begin{mylemma}[shifting]%
 \label{lem:shifting}
 Let $P\subseteq \Sigma^*$ be prefix-closed, $S\subseteq \Sigma^*$ be  suffix-closed,
 and  $s,w\in\Sigma^*$ be such that $sw\in S$. If the Hankel subblock $H_{(P, S)}$ is row-closed, then we have $(X_{s_1}\dots X_{s_n} H_{(P, S)})(:, w) = H_{(P, S)}(:, sw)$, where $s=s_1s_2\dots s_n$. 
 Dually, 
 let $w, p\in \Sigma^{*}$ be such that $wp\in P$. If  $H_{(P, S)}$ is column-closed, then  we have $(H_{(P, S)} Y_{p_1}\dots Y_{p_n})(w, :) = H_{(P, S)}(wp, :)$.
 \defend
\end{mylemma}
\begin{myproof}
    We prove the first half of Lem.~\ref{lem:shifting} by induction on the length of $s$.  If $s$ is empty, it is obvious.
 If $s$ is nonempty,
 because $S$ is suffix-closed, $s_2\dots s_n w\in S$ holds, and thus, we have $(X_{s_2}\dots X_{s_n} H_{(P,S)})(:, w) = H_{(P, S)}(:, s_2\dots s_n w)$ by the induction hypothesis.
 By definition, 
 $X_{s_1}H_{(P, S)}(:, s_2\dots s_n w) = H_{(Ps_1, S)}(:, s_2\dots s_n w)$ holds, and we have
 $X_{s_1}H_{(P, S)}(:, s_2\dots s_n w) = H_{(Ps_1, S)}(:, s_2\dots s_n w) = H_{(P, s_1 S)}(:, s_2\dots s_n w) = H_{(P, S)}(:, sw)$.
 The proof for the second half of Lem.~\ref{lem:shifting} is similar.
\end{myproof}




