% %  After all, we believe that these issues (non-termination and non-minimality) are due to the nature of  underlying semirings, instead of  the choice of an algorithm. For the max-plus semiring, we discuss potential countermeasures in \S{}\ref{sec:furtherOnMaxPlus}. 

We conclude with the following correctness theorem.
\begin{mydefinition}[faithfulness]\label{def:faithful}
 Let $m\colon \Sigma^*\to \semiring$ be a membership oracle, and \\$w^{(1)}, \dotsc, w^{(K)}$ be words (intuitively, these are the membership queries that have been issued). We say that a WFA $A$ is \emph{faithful} to $m$ on $w^{(1)}, \dotsc, w^{(K)}$ if $f_{A}(w^{(k)})=m(w^{(k)})$ for each $k\in [1,K]$.
\end{mydefinition}

\begin{mytheorem}\label{thm:ourAlgoFaithful}
 % The WFA $A_{\mathrm{ext}}$ returned by Algorithm~\ref{alg:ours} is faithful to the oracle $m$, on the words $w^{(1)}, \dotsc, w^{(K)}$ that were queried to $m$ during the algorithm's execution. \defend
 In an execution of  Algorithm~\ref{alg:ours}, each hypothesis WFA $A_{\mathrm{ext}}$ produced in Line~\ref{algline:hypothesis}  is faithful to the oracle $m$, on the words $w^{(1)}, \dotsc, w^{(K)}$ that were queried to $m$ previously during the algorithm's execution. \defend
\end{mytheorem}
\begin{myproof}
    Note first that each $w^{(k)}$ can be written as $p\cdot s$ using elements
    $p\in P$ and $s\in S$ (Line~\ref{algline:subblockrt}). We have
    \begin{math}
     f_{A}(ps) = \textsc{Subblock}(P,S)(p,s)
    \end{math}
    by Thm.~\ref{thm:main} (this uses column-closedness; see also Line~\ref{algline:constructWFA}).  The latter is equal to $m(p\cdot s)$ by Line~\ref{algline:subblockrt}. 
   \end{myproof}



