\end{figure}

\graphdist*

The proof of the theorem adopts the following strategy. Geodesic distances through the manifold $\man$ can be bounded as a function of geodesic distances through the tubular neighborhood $\tub_{\tau}\man$ using \Cref{lem: ratio}. We can then pull from \citet{bernsteingeodesic}, which relates graph geodesics to manifold geodesics, to bound graph distances through $G'$ as a function of manifold distances $\man$. The theorem can be concisely stated as showing that in the limit of vanishing noise, graph distances in $G'$ between endpoints of (formerly) shortcut edges are necessarily very long.  

\textit{Proof of Theorem \ref{thm: graph distance}.} Again suppose $\{\mathcal{X}_i\}_{i=1}^{\infty}$ is a sequence of point clouds of size $n$ sampled from $\rho$ defined in \cref{eq: pdf} with parameters $\sigma_i$ and $\tau_i$ with $\sigma_i \rightarrow 0^+$ and $\tau_i \rightarrow 0^+$ as $i \rightarrow \infty$. Also suppose $G_i = (V_i, E_i)$ is the nearest neighbor graph built with parameter $\epsilon$ from the point cloud $\mathcal{X}_i$. Consider the $i$-th pointcloud and nearest neighbor graph in this sequence, and let $x_i$ and $y_i$ be any two points connected by a shortcut edge (if they exist). Since $(x_i,y_i)$ is a shortcut edge in $G_i$ we have, 
\[d_{\man}\bigl(\proj_{\man}x_i, \proj_{\man}y_i\bigr) > (\pi+1) r_0(\man). \]

From \Cref{lem: ratio}, we know this implies
\begin{align} \label{eq: tub bound}
    d_{\tub}(x_i,y_i) &\geq \frac{r_0(\man) - \tau_i}{r_0(\man)}(\pi+1) r_0(\man) \\
    &= (r_0(\man) - \tau_i)(\pi+1).
\end{align}
Now consider the ORC thresholded graph $G'_i = (V_i, E'_i)$, with edges
\[E'_i = \biggl\{(v, v') \in E_i \, \bigg | \, \kappa(v,v') > -1 \biggr\}.\]

We can apply \Cref{thm: shortcut orc} to say that with high probability $G'_i$ has no shortcut edges. With that in mind, select a length minimizing path $a_0^i, a_1^i, \cdots, a_p^i$ connecting $x_i$ to $y_i$ through the graph $G'_i$. With high probability we have,
\[d_{\man}(\proj_{\man}a_i^i, \proj_{\man}a^i_{i+1}) \leq (\pi+1) r_0(\man).\]
It follows that $d_{\tub}(a_i^i, a_{i+1}^i) \leq (\pi+1) r_0(\man) + 2\tau_i$, as $\man \subset \tub_{\tau_i}\man$; if this wasn't true, the shortest path through the tubular neighborhood would instead take the path traversed by $\man$ through $\proj_{\man}a_i^i,\proj_{\man}a_{i+1}^i$. Now we can say,
\[d_{\tub}(a_i^i, a^i_{i+1}) \leq (\pi+1) r_0(\man) + 2\tau_i. \]
Consider the $p'$ of the $p-1$ hops along this path where 
\[d_{\tub}(a^i_i, a^i_{i+1}) \leq \pi(r_0(\man) - \tau_i).\]
Note that from \Cref{prop: rad of curv} we know that the minimum radius of curvature of geodesics in the tubular neighborhood is $r_0(\man) - \tau_i$. Now we can invoke the first-order weakening of Lemma 3 from \citet{bernsteingeodesic} with $r_0 = r_0(\man) - \tau_i$ to say
\begin{align*}
    \frac{2}{\pi}d_{\tub}(a_i^i, a_{i+1}^i) &\leq \|a^i_i - a^i_{i+1}\|_2 \\
    &\leq \frac{2}{\pi}(r_0(\man)-\tau_i)\sqrt{24\lambda}
\end{align*}
where the second line follows from assumption \ref{assumption: ep bound}. Solving for $\lambda$ we get
\[\lambda \geq \frac{1}{24} \biggl(\frac{d_{\tub}(a_i^i, a_{i+1}^i)}{r_0(\man) - \tau_i}\biggr)^2\]
and therefore 
\[1 - \lambda \leq 1 - \frac{1}{24} \biggl(\frac{d_{\tub}(a^i_i, a^i_{i+1})}{r_0(\man) - \tau_i}\biggr)^2.\]
Finally we can apply the weakened form of the same Lemma from \citet{bernsteingeodesic} to say
\begin{align*}
    (1 - \lambda)d_{\tub}(a^i_i, a^i_{i+1}) &\leq \Biggl(1 - \frac{1}{24} \biggl(\frac{d_{\tub}(a^i_i, a^i_{i+1})}{r_0(\man) - \tau_i}\biggr)^2\Biggr)d_{\tub}(a^i_i, a^i_{i+1}) \\
    & \leq \|a^i_i - a^i_{i+1}\|_2.
\end{align*}
Now consider the other $(p-1) - p'$ hops, where we know 
\[d_{\tub}(a^i_i, a^i_{i+1}) > \pi(r_0(\man) - \tau_i).\]
We can apply the definition of minimum branch separation to say that $\|a^i_i - a^i_{i+1}\|_2 \geq s_0(\tub_{\tau_i}\man)$. In general deriving an expression for the right-hand side in terms of $r_0(\man)$ and $s_0(\man)$ is impossible without more information about the embedding of $\man$. Thus, we will proceed without breaking down $s_0(\tub_{\tau_i}\man)$. We have,
\begin{align}
    \|a^i_i - a^i_{i+1}\|_2 &\geq s_0(\tub_{\tau_i}\man) \\
    & \geq \frac{s_0(\tub_{\tau_i}\man)}{(\pi+1) r_0(\man) + 2\tau_i}d_{\tub_i}(a^i_i, a^i_{i+1}). 
\end{align}
Now we can combine the bounds on $\|a^i_i - a^i_{i+1}\|_2$ to say 
\begin{align}
    d_{G'_i}(x_i, y_i) &>  (1-\lambda)\sum_S d_{\tub}(a^i_i, a^i_{i+1}) + \sum_L \frac{s_0(\tub_{\tau_i}\man)}{(\pi+1) r_0(\man) + 2\tau_i}d_{\tub_i}(a^i_i, a^i_{i+1}) \\
    & > (1-\lambda)\sum_S d_{\tub}(a^i_i, a^i_{i+1})
\end{align}
where $S$ is the set of all hops with tubular distance at most $\pi(r_0(\man) - \tau_i)$, and $L$ is the set of all remaining hops. Defining
\begin{equation}\label{eq: beta expression}
\beta = \frac{\sum_S d_{\tub}(a^i_i, a^i_{i+1})}{d_{\tub}(x_i,y_i)}
\end{equation}
allows us to say
\begin{align*}
    d_{G'_i}(x_i, y_i) &>  \beta(1-\lambda)d_{\tub}(x_i,y_i) \\
    &\geq \beta(1-\lambda)(r_0(\man) - \tau_i)(\pi+1)
\end{align*}
and seeing as we have stipulated that $\epsilon < \frac{2}{\pi}(r_0(\man)-\tau)\sqrt{24\lambda}$ in assumption \ref{assumption: ep bound}, we can say
\begin{align}
    d_{G'_i}(x_i, y_i) &> \beta\frac{\pi(\pi+1)(1-\lambda)}{2\sqrt{24\lambda}}\epsilon \label{eq: graph dist bound}
\end{align}
with high probability.
\qed{}

\subsubsection{Lemmata}

In this section, we will prove the lemmas used by Theorems \ref{thm: shortcut orc}, \ref{thm: good orc} and \ref{thm: graph distance}. Lemmas \ref{lem: k(x,y) bound} and \ref{lem: k(x,y) bound intersection} simply bound (from above and below, respectively) the ORC of an edge based on the locations of each endpoints neighbors. Lemma \ref{lem: k(x,y) bound} considers the scenario where some subset of the neighborhoods of $x$ and $y$ are positioned in the sets $U_x$ and $U_y$, respectively (where $U_x$ and $U_y$ are defined according to Figure \ref{fig: safe region}). The large distance between $U_x$ and $y$ (and vice versa) allows one to lower bound the Wasserstein distance between $\mu_x$ and $\mu_y$, and thus upper bound the ORC of $(x,y)$.  

\begin{lemma} 
    \label{lem: k(x,y) bound}
    Let $(x,y)$ be an edge in a nearest neighbor graph built from potentially noisy samples of $\man$, suppose $U_x$ and $U_y$ are defined as in \ref{fig: safe region}. Define $S_x  = \{a \,| \, a \in \mathcal{N}(x) \cap U_x\}$ and $S_y  = \{b \,| \, b \in \mathcal{N}(y) \cap U_y\}$, and suppose that 
    \[\delta_x = \frac{|S_x|}{|\mathcal{N}(x) \setminus \{y\}|}, \hspace{5mm} \delta_y = \frac{|S_y|}{|\mathcal{N}(y) \setminus \{x\}|}.\]
    Then,
    \[\kappa(x,y) \leq -1 + 2\Bigl(2 - (\delta_x + \delta_y)\Bigr).\]
\end{lemma}

\textit{Proof.} We are interested in bounding the ORC of the edge $(x,y)$ from above. Recall that we have defined ORC to use the $\epsilon$-\textit{weighted} graph metric in \Cref{sec: orc definition}. To bound the ORC we need to bound the Wasserstein distance between $\mu_x$ and $\mu_y$, where $\mu_x$ is a uniform measure on the set $\mathcal{N}(x) \setminus \{y\} = \{v \in V \, \big| \, d_G(x,v) \leq \epsilon, v \neq y, v\neq x\}$ and $\mu_y$ is a uniform measure on the set $\mathcal{N}(y) \setminus \{x\} = \{v \in V \, \big| \, d_G(y,v) \leq \epsilon, v \neq x, v \neq y\}$. 

Let's define $\hat{\mu}_x$ and $\hat{\mu}_y$ as uniform probability measures over $S_x$ and $S_y$ respectively. We can bound the Wasserstein distance between $\mu_x$ and $\mu_y$ as
\[W(\mu_x, \mu_y) \geq W(\hat{\mu}_x, \hat{\mu}_y) - W(\hat{\mu}_x, \mu_x) - W(\hat{\mu}_y, \mu_y).\]

Since $\|a-b\|_2 > \epsilon$ for all $a \in S_x$ and for all $b \in S_y$, we know that $d_G(a,b) \geq 2\epsilon$ for all $a \in S_x$ and for all $b \in S_y$. Thus, a lower bound on the first term follows, 
\[W(\hat{\mu}_x, \hat{\mu}_y) \geq 2\epsilon.\]

Now we would like to bound $W(\hat{\mu}_x, \mu_x)$ from above. There is $1/|\mathcal{N}(x) \setminus \{y\}|$ mass on each node $a \in \supp(\mu_x)$, while there is $1/\delta_x|\mathcal{N}(x) \setminus \{y\}|$ mass on each $a' \in \supp(\hat{\mu}_x)$. We can define a feasible transport plan that transports all excess mass on $a' \in \supp(\hat{\mu}_x)$ to the nodes $\supp(\mu_x) \setminus \supp(\hat{\mu}_x)$. Since the Wasserstein distance minimizes over all possible transport plans, the Wasserstein cost for this transport plan will upper bound the true distance.

The excess mass on any $a' \in \supp(\hat{\mu}_x)$ is exactly 
\[\frac{1}{\delta_x|\mathcal{N}(x) \setminus \{y\}|} - \frac{1}{|\mathcal{N}(x) \setminus \{y\}|}\]

which means the total mass that needs to be transported is 
\[\delta_x|\mathcal{N}(x) \setminus \{y\}|\Biggl(\frac{1}{\delta_x|\mathcal{N}(x) \setminus \{y\}|} - \frac{1}{|\mathcal{N}(x) \setminus \{y\}|}\Biggr) = 1 - \delta_x\]

We also know that from any $a' \in \supp(\hat{\mu}_x)$ to any $a \in \supp(\mu_x)$ there exists a length $2\epsilon$ path through the node $x$. Therefore, $d_G(a, a') \leq 2\epsilon$. We can then conclude 
\[W(\hat{\mu}_x, \mu_x) \leq 2\epsilon\bigl(1-\delta_x\bigr).\]

With the same argument, the following bound can also be derived, 
\[W(\hat{\mu}_y, \mu_y) \leq 2\epsilon\bigl(1-\delta_y\bigr).\]

Putting it all together,
\[W(\mu_x, \mu_y) \geq 2\epsilon - 2\epsilon\big(2 - (\delta_x + \delta_y)\big).\]

Solving for the ORC, 
\begin{align*}
    \kappa(x,y) &\leq 1 - \frac{2\epsilon - 2\epsilon\big(2 - (\delta_x + \delta_y)\big)}{\epsilon} \\
    &= -1 + 2\Bigl(2 - (\delta_x + \delta_y)\Bigr).
\end{align*}

\qed{}

Now we can adopt a similar argument to tackle Lemma \ref{lem: k(x,y) bound intersection}. Now we are interested in \textit{lower} bounding the ORC based on the neighborhood structure. In this scenario, we replace the sets $U_x$ and $U_y$ with a $\eball(x) \, \cap \, \eball(y)$. Each neighbor of an endpoint ($x$) that is positioned in this set is necessarily a neighbor of the other ($y$). Therefore if many nodes are present in this set, then many of the neighbors of $x$ and $y$ are shared. An upper bound on the Wasserstein distance between $\mu_x$ and $\mu_y$ follows, which implies a lower bound on the ORC of the edge $(x,y)$.

\begin{lemma}\label{lem: k(x,y) bound intersection}
     Let $(x,y)$ be an edge in a nearest neighbor graph built from potentially noisy samples of $\man$, and define $S_{x,y}  = \{a \,| \, a \in \mathcal{N}(x) \, \cap \, \mathcal{N}(x) \}$. Suppose that 
     \[\delta_x = \frac{|S_{x,y}|}{|\mathcal{N}(x) \setminus \{y\}|}, \hspace{5mm} \delta_y = \frac{|S_{x,y}|}{|
     \mathcal{N}(y) \setminus \{x\}|}.\]
     Then,
     \[\kappa(x,y) \geq 1 - 2\Bigl(2 - (\delta_x + \delta_y)\Bigr).\]
\end{lemma}

\textit{Proof.} We will adopt a very similar argument as that of the proof for Lemma \ref{lem: k(x,y) bound}. We are interested in bounding the ORC of the edge $(x,y)$ from below. Doing so involves bounding the Wasserstein distance between $\mu_x$ and $\mu_y$, where $\mu_x$ is a uniform measure on the set $\mathcal{N}(x) \setminus \{y\} = \{v \in V \, \big| \, d_G(x,v) \leq \epsilon, v \neq y, v \neq x\}$ and $\mu_y$ is a uniform measure on the set $\mathcal{N}(y) \setminus \{x\} = \{v \in V \, \big| \, d_G(y,v) \leq \epsilon, v \neq x, v \neq y\}$. Again recall that we have defined ORC to use the $\epsilon$-\textit{weighted} graph metric in \Cref{sec: orc definition}.

Define $\hat{\mu}_{x,y}$ to be the uniform probability measure over $S_{x,y}$. We can bound the Wasserstein distance between $\mu_x$ and $\mu_y$ as
\[W(\mu_x, \mu_y) \leq W(\mu_x, \hat{\mu}_{x,y}) + W(\hat{\mu}_{x,y}, \mu_y).\]

Now we would like to bound $W(\mu_x, \hat{\mu}_{x,y})$ from above. There is $1/|\mathcal{N}(x) \setminus \{y\}|$ mass on each node $a \in \supp(\mu_x)$, while there is $1/\delta_x|\mathcal{N}(x) \setminus \{y\}|$ mass on each $a' \in \supp(\hat{\mu}_{x,y})$. We can define a feasible transport plan that transports all excess mass on $a' \in \supp(\hat{\mu}_{x,y})$ to the nodes $\supp(\mu_x) \setminus \supp(\hat{\mu}_{x,y})$. Since the Wasserstein distance minimizes over all possible transport plans, the Wasserstein cost for this transport plan will upper bound $W(\mu_x, \hat{\mu}_{x,y})$.

The excess mass on any $a' \in \supp(\hat{\mu}_x)$ is exactly 
\[\frac{1}{\delta_x|\mathcal{N}(x) \setminus \{y\}|} - \frac{1}{|\mathcal{N}(x) \setminus \{y\}|}\]

which means the total mass that needs to be transported is 
\[\delta_x|\mathcal{N}(x) \setminus \{y\}|\Biggl(\frac{1}{\delta_x|\mathcal{N}(x) \setminus \{y\}|} - \frac{1}{|\mathcal{N}(x) \setminus \{y\}|}\Biggr) = 1 - \delta_x\]

We also know that from any $a' \in \supp(\hat{\mu}_{x,y})$ to any $a \in \supp(\mu_x)$ there exists a length $2\epsilon$ path through the node $x$. Therefore, $d_G(a,b) \leq 2\epsilon$. We can then conclude 
\[W(\mu_x, \hat{\mu}_{x,y}) \leq 2\epsilon\bigl(1-\delta_x\bigr).\]

With the same argument, the following bound can also be derived, 
\[W(\hat{\mu}_{x,y}, \mu_y) \leq 2\epsilon\bigl(1-\delta_y\bigr).\]

Putting it all together,
\[W(\mu_x, \mu_y) \leq 2\epsilon\big(2 - (\delta_x + \delta_y)\big).\]

Solving for the ORC, 
\begin{align*}
    \kappa(x,y) &\geq 1 - \frac{2\epsilon\big(2 - (\delta_x + \delta_y)\big)}{\epsilon} \\
    &= 1 - 2\Bigl(2 - (\delta_x + \delta_y)\Bigr).
\end{align*}

\qed{}

Moving on, \Cref{lem: phi} and \Cref{lem: probability of safe region} constitute a majority of the theoretical work of this paper. Together, they show that most of the measure in the $\epsilon$-ball of a point $x$ connected by a shortcut edge to $y$ tends to concentrate far from $y$. For context, \Cref{thm: shortcut orc} uses this fact in conjunction with Lemma \ref{lem: k(x,y) bound} to show that the ORC of shortcut edges is necessarily very negative. 

To set the stage, \Cref{lem: phi} establishes two things. First, and most importantly, it shows that a shortcut edge is necessarily oriented close to a normal direction $v$ to the manifold at its endpoints. This concept is rather intuitive; if shortcut edges were closer to tangential directions instead, then these edges would intersect with the manifold prematurely, no longer bridging distant neighborhoods and contradicting their status as shortcuts. The second property the lemma establishes is the fact that the residual of the projection (onto $\man$) of an endpoint $x$ of a shortcut edge must be within $\pi/2$ radians of the aforementioned normal direction $v$. Put simply, this means that the endpoints of a shortcut edge are necessarily displaced off the manifold in the direction of or orthogonal to the normal direction that the edge itself spans. This simply arises from the assumptions about the size of $\epsilon$ relative to the manifold embedding parameters $r_0(\man)$ and $s_0(\man)$. We show this second property holds as it simplifies some of the downstream calculations.

\begin{lemma}\label{lem: phi}
    If an edge $(x,y)$ in a nearest neighbor graph built from potentially noisy samples of $\man$ is a shortcut edge then \begin{enumerate}
        \item there exists a unit vector $v \in N_{\proj_{\man}x}\man$ (the normal space of $\man$ at $\proj_{\man}x$) such that the angle $\phi$ between $v$ and $(y-x)$ is smaller than 
        \begin{equation}\label{eq: phi bound in lemma}
        \arccos\biggl(\frac{(r_0(\man) - \tau)(s_0(\man) - \tau) -1.27 r_0(\man) \tau}{r_0(\man)\sqrt{(s_0(\man)-\tau)^2-\tau^2}}\biggr)
        < \pi/2.
        \end{equation}
        \item the angle $\theta$ between $v$ and $(x - \proj_{\man}x)$ is at most $\pi/2$.
    \end{enumerate}
\end{lemma}

\textit{Proof.} Observe that the vector $(y-x)$ can be written as $\alpha v_T + \beta v$, where $v_T$ is a unit vector $\in T_{\proj_{\man}x}\man$, while $v$ is a unit vector $\in N_{\proj_{x}\man}\man$. This vector $v$ is in fact the unit vector in $N_{\proj_{x}\man}\man$ that minimizes the angle $\phi$ to $(y-x)$. Motivated by this, Figure \ref{fig: x-y} visualizes the 3 dimensional subspace spanned by the vectors $v_T, v$ and $(x - \proj_{\man}x)$. This visualization lays the conceptual foundation that the rest of the proof rests on.


First, we will show (2) holds, as it is helpful in showing (1). To do so, we will show that the geometry of shortcutting edges implies a bound on $\|x-y\|_2$ as a function of $\theta$. We will then show that this bound violates the assumptions on the size of $\epsilon$ for $\theta \geq \pi/2$. 


Since $(x,y)$ is a shortcut edge, $d_{\man}(\proj_{\man}x, \proj_{\man}y) > (\pi+1) r_0(\man) > \pi r_0(\man)$. By the definition of minimum branch separation, we know then $\|\proj_{\man}x - \proj_{\man}y\|_2 \geq s_0(\man)$. Now consider the triangle defined by the endpoints $\proj_{\man}x, \proj_{\man}y$ and $y$. We can apply the triangle inequality to say 
\begin{align*}
    \|\proj_{\man}x - y\|_2 &\geq \|\proj_{\man}x - \proj_{\man}y\|_2 - \|\proj_{\man}y - y\|_2 \\
    & \geq s_0(\man) - \tau
\end{align*}
since $\tau \geq \|\proj_{\man}y - y\|_2$. Now consider the triangle defined by the endpoints $y$, $\proj_{\man}x$ and $y'$, where $y'$ is the orthogonal projection of $y$ onto the subspace spanned by $v$ and $(y-x)$ centered at $\proj_{\man}x$ (shown in Figure \ref{fig: x-y}). Note that

\begin{align*}
    \|y' - \proj_{\man}x\|_2 &\geq \sqrt{\|\proj_{\man}x - y\|_2^2 - \|x - \proj_{\man}x\|_2^2\sin^2(\theta)} \\
    &\geq \sqrt{(s_0(\man)-\tau)^2 - \|x - \proj_{\man}x\|_2^2\sin^2(\theta).}
\end{align*}

\begin{figure}
    \centering
    \includegraphics[width=0.4\textwidth]{figures/diagrams/lemmas/x_y.pdf}
    \caption{A visualization of the plane spanned by the vectors $(y-x)$ and $v$, and related quantities. }
    \label{fig: x-y}
\end{figure}

Finally, consider the triangle defined by the endpoints $\proj_{\man}x$, $y'$ and $x'$, where $x'$ is the orthogonal projection of $x$ onto $v$. Observe that $\|x' - \proj_{\man}x\|_2 = \|x - \proj_{\man}x\|_2\cos(\theta)$ and $\|x' - y'\|_2 = \|x - y\|_2$. The second equivalence stems from the fact that the vectors $v$ and $v_T$ were chosen specifically so that they can be linearly combined to get $(y-x)$; it follows that $x' - y'$ is the same as $x-y$. With that in mind, we can apply the triangle inequality again to say
\begin{equation}\label{eq: x-y bound}
    \|x-y\|_2 \geq \sqrt{(s_0(\man)-\tau)^2 - \|x - \proj_{\man}x\|_2^2\sin^2(\theta)} - \|x - \proj_{\man}x\|_2\cos(\theta).
\end{equation}
Property (2) follows from the prescribed upper bound, $\|x-y\|_2 \leq \sqrt{(s_0(\man) - \tau)^2-\tau^2}$ from assumption \ref{assumption: ep bound}. Thus,  
\[\sqrt{(s_0(\man) - \tau)^2-\tau^2} \geq \sqrt{(s_0(\man)-\tau)^2 - \|x - \proj_{\man}x\|_2^2\sin^2(\theta)} - \|x - \proj_{\man}x\|_2\cos(\theta).\]

Solving for $\theta$,
\begin{align*}
    \begin{split}
        (s_0(\man) - \tau)^2-\tau^2 + 2\|x - \proj_{\man}x\|_2&\cos(\theta)\sqrt{(s_0(\man) - \tau)^2-\tau^2} + \|x - \proj_{\man}x\|_2^2\cos^2(\theta) \\ {}&\geq (s_0(\man) - \tau)^2 - \|x - \proj_{\man}x\|_2^2\sin^2(\theta)
    \end{split}\\
    \begin{split}
        (s_0(\man) - \tau)^2-\tau^2 + 2\|x - \proj_{\man}x\|_2&\cos(\theta)\sqrt{(s_0(\man) - \tau)^2-\tau^2} \\ {}&\geq (s_0(\man) - \tau)^2 - \|x - \proj_{\man}x\|_2^2.
    \end{split}
\end{align*}
Rearranging a little more, 
\begin{align*}
    2\|x - \proj_{\man}x\|_2&\cos(\theta)\sqrt{(s_0(\man) - \tau)^2-\tau^2} \geq \tau^2 - \|x - \proj_{\man}x\|_2^2 \\
    \cos(\theta) &\geq \frac{\tau^2 - \|x - \proj_{\man}x\|_2^2}{2\|x - \proj_{\man}x\|_2\sqrt{(s_0(\man) - \tau)^2-\tau^2}}\\
\end{align*}
thus,
\begin{align*}
    \theta &\leq \arccos\biggl(\frac{\tau^2 - \|x - \proj_{\man}x\|_2^2}{2\|x - \proj_{\man}x\|_2\sqrt{(s_0(\man) - \tau)^2-\tau^2}}\biggr) \\
    &\leq \arccos(0) \\
    &= \pi/2
\end{align*}
Since $\|x - \proj_{\man}x\|_2 \leq \tau$. This concludes the proof of (2). 

Now we will show (1). At a high level, we will show that if the angle $\phi$ is \textit{not} smaller than the listed threshold, $y$ must have a small Euclidean distance to a small neighborhood around $x$; for points in this neighborhood, the manifold distance to the projection of $y$ is large. This leads to a contradiction stemming from a violation of the minimum branch separation of $\man$.

We will first show that $\phi < \pi/2$ with a simple instantiation of the argument above. We will then proceed to refine the result to establish that $\phi$ is actually upper bounded by \ref{eq: phi bound in lemma}, a complicated function of manifold parameters.

\textbf{Regime 1:} $\phi \in [\pi/2, \pi]$. First we will show that for any $\phi$ in this range, we have a violation of minimum branch separation due to proximity between $y$ and $\proj_{\man}x$. First we will derive $\|\proj_{\man}x -y''\|_2$ (where $y''$ is the projection of $y$ onto the plane spanned by $v$ and $x - \proj_{\man}x$, shown in Figure \ref{fig: gamma}). Consider the triangle with endpoints $\proj_{\man}x, y''$ and the projection of $y''$ onto the $v$, $v_T$ plane. We can use the triangle inequality to get
\begin{align*}
    \|\proj_{\man}&x -y''\|_2\\
    &= \sqrt{\Bigl(\|x - \proj_{\man}x\|_2 \cos(\theta) + \|x-y\|_2\cos(\phi)\Bigr)^2 + \|x - \proj_{\man}x\|_2^2 \sin^2(\theta)} \\
    &= \sqrt{\|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2\cos^2(\phi)}.
\end{align*}

Now we can solve for $\|\proj_{\man}x -y\|_2$ by looking at the triangle with endpoints $\proj_{\man}x, y$ and $y''$ as follows,
\begin{align*}
    \|\proj_{\man}&x -y\|_2\\
    &= \sqrt{\|\proj_{\man}x -y''\|_2^2 + \|x - y\|_2^2 \sin^2(\phi)} \\
    &= \sqrt{\|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2}.
\end{align*}
Note that 
$\|\proj_{\man}x -y\|_2$ is decreasing in $\phi$ for $\phi \in (0, \pi)$. Rearranging and solving for $\phi$ yields,
\begin{align*}
    \phi = \arccos\Biggl(\frac{\|\proj_{\man}x -y\|_2^2 - \|x - \proj_{\man}x\|_2^2 - \|x-y\|_2^2}{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}\Biggr).
\end{align*}
Now let 
\begin{equation*}
    f(L) = \arccos\Biggl(\frac{L^2 - \|x - \proj_{\man}x\|_2^2 - \|x-y\|_2^2}{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}\Biggr).
\end{equation*}
We will evaluate $f(L)$ for $L = s_0(\man) - \tau$. We will then show shortly that if $L$ is less than $s_0(\man) - \tau$, we have a contradiction. Since $\|\proj_{\man}x -y\|_2$ is decreasing in $\phi$, we know that for all $\phi > f(L)$,  $\|\proj_{\man}x -y\|_2 < s_0(\man) - \tau$. Evaluating $f$ at $s_0(\man) - \tau$,
\[f(s_0(\man) - \tau) = \arccos\Biggl(\frac{(s_0(\man)-\tau)^2 - \|x - \proj_{\man}x\|_2^2 - \|x-y\|_2^2}{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}\Biggr).\]
Now let's upper bound $f(s_0(\man) - \tau)$ as a means to simplify. Since $\arccos$ is decreasing on $(-1, 1)$
\begin{align*}
    f(s_0(\man) - \tau) &= \arccos\Biggl(\frac{(s_0(\man)-\tau)^2 - \|x - \proj_{\man}x\|_2^2 - \|x-y\|_2^2}{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}\Biggr) \\
    &< \arccos\Biggl(\frac{(s_0(\man)-\tau)^2 - \tau^2 - \Bigl(\sqrt{(s_0(\man) - \tau)^2 - \tau^2}\Bigr)^2}{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}\Biggr) && \text{Assumption \ref{assumption: ep bound}} \\
    &= \arccos\Biggl(\frac{(s_0(\man)-\tau)^2 - \tau^2 - (s_0(\man) - \tau)^2 + \tau^2}{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}\Biggr) \\
    &= \arccos(0) \\
    &= \pi/2.
\end{align*}
Since $f(s_0(\man) - \tau) < \pi/2$, we can say that for all $\phi \geq \pi/2 > f(s_0(\man) - \tau)$, $\|\proj_{\man}x -y\|_2 < s_0(\man) - \tau$. Observe that, since $(x,y)$ is a shortcut edge $d_{\man}(\proj_{\man}x, \proj_{\man}y) > (\pi+1) r_0(\man) > \pi r_0(\man)$. From the definition of minimum branch separation, we know that this implies $\|\proj_{\man}x - \proj_{\man}y\|_2 \geq s_0(\man)$. Now let's apply the triangle inequality,
\begin{align*}
    \|\proj_{\man}x -y\|_2 &\geq \|\proj_{\man}x - \proj_{\man}y\|_2 - \|\proj_{\man}y - y\|_2 \\
    &\geq s_0(\man) - \tau.
\end{align*}
Thus, for $\phi \geq \pi/2$ we have a contradiction stemming from a violation of minimum branch separation. We therefore know that $\phi$ cannot exist in the interval $[\pi/2, \pi]$.

\textbf{Regime 2:} $\phi \in [0, \pi/2)$. While the previous result gives us a bound on $\phi$, we can sharpen it further. Since we are dealing with manifolds without boundary, we can use the exponential map $\exp_{\proj_{\man}x}$ to send the tangent vector $v_T$ to a geodesic arc of $\man$ denoted $\gamma$. Again we will show that if $\phi$ is sufficiently large, then the distance from $y$ to $\gamma$ violates the minimum branch separation in the same manner as we saw in Regime 1. 

Consider the particular scenario where $\gamma$ curls away from $y$ maximally. We will approximate $\gamma$ near $\proj_{\man}x$ with its osculating circle $C$: a circle contained in the plane spanned by $v_T$ and $(y - \proj_{\man}x)$ with the smallest possible radius of curvature, $r_0(\man)$. This particular instantiation is shown in Figure \ref{fig: gamma}. Note that $C$ approximates a geodesic arc passing through $\proj_{\man}x$ with initial velocity $v_T$ and curls away from $y$ maximally. Thus the distance between all possible geodesic arcs passing through $\proj_{\man}x$ with velocity vector $v_T$ is approximately bounded by the distance between $C$ and $y$. 

\begin{figure}
    \centering
    \includegraphics[width=0.7\textwidth]{figures/diagrams/lemmas/gamma.pdf}
    \caption{A visualization of the plane spanned by the vectors $(y-x)$ and $v$, and related quantities.}
    \label{fig: gamma}
\end{figure}

Now we want to derive an expression for the distance between $C$ and $y$; this distance will be denoted $d$. We will start by deriving $\|\proj_{\man}x -y''\|_2$ (where $y''$ is the projection of $y$ onto the plane spanned by $v$ and $x - \proj_{\man}x$, shown in Figure \ref{fig: gamma}). Consider the triangle defined by $\proj_{\man}x, y''$ and the projection of $y''$ onto the $v$, $v_T$ plane and apply the Pythagorean theorem to say 
\begin{align}
    \|\proj_{\man}&x -y''\|_2\\
    &= \sqrt{\Bigl(\|x - \proj_{\man}x\|_2 \cos(\theta) + \|x-y\|_2\cos(\phi)\Bigr)^2 + \|x - \proj_{\man}x\|_2^2 \sin^2(\theta)} \\
    &= \sqrt{\|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2\cos^2(\phi)}. \label{eq: ||px-y''||}
\end{align}
Now consider the triangle defined by the center of the osculating circle $C$, $y''$ and $y$. We can solve for $d + r_0(\man)$ as,
\[d + r_0(\man) = \sqrt{\Bigl(\|\proj_{\man}x - y''\|_2 + r_0(\man)\Bigr)^2 + \|x-y\|_2^2\sin^2(\phi)}.\]
Squaring both sides and plugging in \cref{eq: ||px-y''||} yields the following for the right hand side,
\begin{align}
   &\Bigl(\|\proj_{\man}x - y''\|_2 + r_0(\man)\Bigr)^2 + \|x-y\|_2^2\sin^2(\phi) \\
   &= \|\proj_{\man}x - y''\|_2^2 + 2r_0(\man)\|\proj_{\man}x - y''\|_2 + r_0(\man)^2 + \|x-y\|_2^2\sin^2(\phi) \\
   \begin{split}
       &{} = \|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2\cos^2(\phi) \\
       &\hspace{5mm}+ 2r_0(\man)\\
       &\hspace{8mm}\cdot\sqrt{\|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2\cos^2(\phi)}\\
       &\hspace{5mm}+ r_0(\man)^2 + \|x-y\|_2^2\cos^2(\phi)
   \end{split}\\
   \begin{split}
       &{} = \|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2 + r_0(\man)^2 \\
       &+ 2r_0(\man)\sqrt{\|x - \proj_{\man}x\|_2^2  + 2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\cos(\phi) + \|x-y\|_2^2\cos^2(\phi)}.
   \end{split}\label{eq: d + r0}
\end{align}
Observe that $\bigl(d + r_0(\man)\bigr)^2$ is decreasing in $\phi$ on the interval $\phi \in (0, \pi/2)$ since $\cos(\theta) \geq 0$, $\cos(\phi)$ is decreasing on $(0, \pi)$ and $\cos^2(\phi)$ is decreasing on $(0, \pi/2)$. To establish the contradiction we want to find the $\phi' \in (0, \pi/2)$ such that $d = s_0(\man) - \tau$; from that, we know that for any $\phi > \phi'$, $d < s_0(\man) - \tau$.  Rearranging \ref{eq: d + r0} slightly yields
\begin{align*}
    &\underbrace{\Bigl(d + r_0(\man)\Bigr)^2 - \|x-y\|_2^2 - r_0(\man)^2}_{c_1} \\
    \begin{split}
       &{} = \underbrace{\|x - \proj_{\man}x\|_2^2}_{c_2}  + \underbrace{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}_{c_3}\cos(\phi)\\
       &+ \underbrace{2r_0(\man)}_{c_4}\sqrtexplained{\underbrace{\|x - \proj_{\man}x\|_2^2}_{c_2} + \underbrace{2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)}_{c_3}\cos(\phi) + \underbrace{\|x-y\|_2^2}_{c_5}\cos^2(\phi)}.
    \end{split}
\end{align*}

Using these intermediate terms and defining $z = \cos(\phi)$, we see
\[c_1 = c_2 + c_3z + c_4\sqrt{c_2 + c_3z + c_5 z^2}.\]

Rearranging to get a quadratic polynomial gives
\begin{align*}
    \Bigl((c_1 - c_2) - c_3 z\Bigr)^2 &= c_4^2\Bigl(c_2 + c_3 z + c_5 z^2\Bigr) \\
    (c_1 - c_2)^2 - 2c_3(c_1 - c_2)z + c_3^2z^2 &= c_4^2c_2 + c_4^2c_3z + c_4^2c_5z^2\\
    -\Bigl((c_1 - c_2)^2 - c_4^2c_2\Bigr) + \Bigl(2c_3(c_1 - c_2) + c_4^2c_3\Bigr)z - \Bigl(c_3^2 - c_4^2 c_5\Bigr)z^2&= 0.
\end{align*}

Applying the quadratic formula,
\begin{align}
    z &= \ddfrac{-\Bigl(2c_3(c_1 - c_2) + c_4^2c_3\Bigr) \pm \sqrt{\Bigl(2c_3(c_1 - c_2) + c_4^2c_3\Bigr)^2 + 4\Bigl(c_4^2 c_5 - c_3^2\Bigr)\Bigl((c_1 - c_2)^2 - c_4^2c_2\Bigr)}}{2\Bigl(c_4^2 c_5 - c_3^2\Bigr)} \label{eq: quadratic formula}
\end{align}
Evaluating the denominator gives
\begin{align}
    2\Bigl(c_4^2 c_5 - c_3^2\Bigr) &= 2\Bigl(-4\|x - \proj_{\man}x\|_2^2\|x-y\|_2^2\cos^2(\theta) + 4r_0(\man)^2\|x-y\|_2^2\Bigr) \\
    &= 8\Bigl(-\|x - \proj_{\man}x\|_2^2\|x-y\|_2^2\cos^2(\theta) + r_0(\man)^2\|x-y\|_2^2\Bigr) \\
    &= 8\|x-y\|_2^2\Bigl(r_0(\man)^2 - \|x - \proj_{\man}x\|_2^2\cos^2(\theta)\Bigr). \label{eq: denominator}
\end{align}
Evaluating the first term of the numerator,
\begin{align*}
    &2c_3(c_1 - c_2) \\
    \begin{split}
        &= 4\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\\
        &\hspace{6mm}\cdot\Bigl(\bigl(d + r_0(\man)\bigr)^2 - \|x-y\|_2^2 - r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2\Bigr) 
    \end{split}\\
    &= 4\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr),
\end{align*}
evaluating the second term of the numerator,
\begin{align*}
    c_4^2c_3 = 8r_0(\man)^2\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)
\end{align*}
and combining,
\begin{multline}
    2c_3(c_1 - c_2) + c_4^2c_3 = 4\|x - \proj_{\man}x\|_2\|x-y\|_2\cos(\theta)\Bigl(d^2 + 2dr_0(\man) \\
    - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2+2r_0(\man)^2\Bigr) \label{eq: numerator term 1}
\end{multline}

Now we will evaluate terms inside of the square root in (\ref{eq: quadratic formula}). Note that the first term is (\ref{eq: numerator term 1}) squared, while the second term includes two times (\ref{eq: denominator}). The remaining part of the second term is
\begin{multline}
    (c_1 - c_2)^2 - c_4^2c_2 = \Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2 \\ - 4r_0(\man)^2\|x-\proj_{\man}x\|_2^2.
\end{multline}
Combining everything inside the square root yields,
\begin{align*}
    \begin{split}
        &16\|x - \proj_{\man}x\|_2^2 \|x-y\|_2^2 \cos^2(\theta)  \\
        &{}\hspace{3mm}\cdot \Bigl[\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) + 2r_0(\man)^2\Bigr]^2 \\
        &{}\hspace{6mm} - \Bigl[16\|x-y\|_2^2\|x-\proj_{\man}x\|^2 \cos^2(\theta) - 16\|x-y\|_2^2r_0(\man)^2\Bigr] \\
        &{}\hspace{9mm}\cdot \Bigl[\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2 - 4r_0(\man)^2\|x-\proj_{\man}x\|_2^2\Bigr]
    \end{split} \\
    \begin{split}
        &{} = 16\|x - \proj_{\man}x\|_2^2 \|x-y\|_2^2 \cos^2(\theta)\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2 \\
        &{} + 64\|x - \proj_{\man}x\|_2^2 \|x-y\|_2^2 \cos^2(\theta)r_0(\man)^2\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) \\
        &{}\hspace{6mm} + 64 r_0(\man)^4\|x - \proj_{\man}x\|_2^2 \|x-y\|_2^2 \cos^2(\theta)\\
        &{}\hspace{9mm} -16\|x - \proj_{\man}x\|_2^2 \|x-y\|_2^2 \cos^2(\theta)\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2 \\
        &{} \hspace{12mm} +64\|x-y\|_2^2\|x-\proj_{\man}x\|_2^4\cos^2(\theta)r_0(\man)^2 \\
        &{} \hspace{15mm} + 16\|x-y\|_2^2r_0(\man)^2\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2  \\
        &{} \hspace{18mm} - 64\|x-y\|_2^2r_0(\man)^4\|x-\proj_{\man}x\|_2^2.
    \end{split} \\
\end{align*}
Continuing to simplify yields
\begin{multline}
    16\|x-y\|_2^2r_0(\man)^2\biggl[ \Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2\\
    + 4\|x-\proj_{\man}x\|_2^2\cos^2(\theta)\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) \\
    +4r_0(\man)^2\|x-\proj_{\man}x\|_2^2\cos^2(\theta) \\
    -4r_0(\man)^2\|x-\proj_{\man}x\|_2^2 \\
    + 4\|x - \proj_{\man}x\|_2^4\cos^2(\theta) \biggr]. \label{eq: big bracket}
\end{multline}
Now we will complete the square in the large bracket of $\ref{eq: big bracket}$,
\begin{align}
    \begin{split}
        &{}\Bigl(d^2 + 2dr_0(\man)  - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)^2\\
        &{} \hspace{3mm} + 4\|x-\proj_{\man}x\|_2^2\cos^2(\theta)\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) \\
        &{} \hspace{6mm} + 4\cos^4(\theta)\|x-\proj_{\man}x\|_2^4 - 4\cos^4(\theta)\|x-\proj_{\man}x\|_2^4 \\
        &{} \hspace{9mm} + 4r_0(\man)^2\|x-\proj_{\man}x\|_2^2\cos^2(\theta) \\
        &{} \hspace{12mm} -4r_0(\man)^2\|x-\proj_{\man}x\|_2^2 \\
        &{} \hspace{15mm} + 4\|x - \proj_{\man}x\|_2^4\cos^2(\theta).
    \end{split}
\end{align}
Now the first three terms and last four terms can be factored,
\begin{align}
        \begin{split}
        &{} \biggl(\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2 \biggr)^2\\
        &{}\hspace{3mm} - 4\cos^4(\theta)\|x-\proj_{\man}x\|_2^4 \\
        &{} \hspace{6mm} + 4r_0(\man)^2\|x-\proj_{\man}x\|_2^2\cos^2(\theta) \\
        &{} \hspace{9mm} - 4r_0(\man)^2\|x-\proj_{\man}x\|_2^2 \\
        &{} \hspace{12mm} + 4\|x - \proj_{\man}x\|_2^4\cos^2(\theta).
    \end{split}
\end{align}
Further simplifying,
\begin{align}
    \begin{split}
        &{} \biggl(\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2 \biggr)^2\\
        &{} \hspace{3mm} - 4 \|x-\proj_{\man}x\|_2^2 \\
        &{} \hspace{6mm} \cdot\Bigl(\|x-\proj_{\man}x\|_2^2\cos^4(\theta) + r_0(\man)^2\sin^2(\theta) - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta) \Bigr)
    \end{split}\\
    \begin{split}
        &{} = \biggl(\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2 \biggr)^2\\
        &{} \hspace{3mm} - 4 \|x-\proj_{\man}x\|_2^2\Bigl(r_0(\man)^2\sin^2(\theta) - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta)\sin^2(\theta) \Bigr)
    \end{split}\\
    \begin{split}
        &{} = \underbrace{\biggl(\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2 \biggr)^2}_{ := \, a^2}\\
        &{} \hspace{3mm} - \underbrace{4 \|x-\proj_{\man}x\|_2^2\sin^2(\theta)\Bigl(r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta) \Bigr)}_{:= \, b^2}
    \end{split}\label{eq: completed the square}
\end{align}
where the two intermediate steps leverage the fact that $1 - \cos^2(\theta) = \sin^2(\theta).$ The equation \ref{eq: quadratic formula} has two roots, and one of the two will result in a term on the right-hand side of \ref{eq: quadratic formula} that is positive (since the denominator is necessarily positive); we will consider this root. Recall that $d$ is decreasing in $\phi$ on the interval $\phi \in (0, \pi/2)$. We want to find a $\phi'$ such that for all $\phi > \phi'$, $d < s_0(\man) - \tau$. It suffices then to find an upper bound for $\phi'$, which implies finding a lower bound on $\cos(\phi')$. 

Let's denote \ref{eq: completed the square} with $B$, and recall that it represents the expression in the large bracket of \ref{eq: big bracket}. Also recall that \ref{eq: big bracket} is a simplified version of the term in the radical of \ref{eq: quadratic formula}. We can express the square root of \ref{eq: big bracket} with $4\|x-y\|_2r_0(\man)\sqrt{B}$. Observe that $\sqrt{B}$ can be written as $\sqrt{a^2 - b^2}$ where $a, b > 0$. Since $\sqrt{a^2 - b^2} \geq a-b$ for $a \geq b > 0$, we can say
\begin{align}
    \begin{split}
        4\|x-y\|_2 &{} r_0(\man)\sqrt{B}  \\
        &{} \geq 4\|x-y\|_2r_0(\man)\biggl(\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) \\ 
        &{} \hspace{5mm} + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2\\
        &{} \hspace{10mm} - 2 \|x-\proj_{\man}x\|_2\sin(\theta)\sqrt{r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta)}\biggr). \label{eq: radical simplified}
    \end{split}
\end{align}
Note that the following steps will demonstrate $a-b \geq 0$, justifying the previous step when evaluating at $d = s_0(\man) - \tau$. Note that 
\begin{align}
    d^2 - &\|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2 = (s_0(\man) - \tau)^2  - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2 \\
    &\geq (s_0(\man) - \tau)^2 - (\sqrt{(s_0(\man) - \tau)^2 - \tau^2})^2 - \tau^2 \\
    &= 0. \label{eq: difference lower bound}
\end{align}
Thus,
\begin{align} 
    \begin{split}
        a - b {}&\geq 2(s_0(\man) - \tau)r_0(\man) + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2 \\
        &\hspace{10mm} - 2 \|x-\proj_{\man}x\|_2\sin(\theta)\sqrt{r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta)}\biggr)
    \end{split}\\
    &\geq 2(s_0(\man) - \tau)r_0(\man) -2\tau r_0(\man). \label{eq: numerator lower bound}
\end{align}
Note that the last term is necessarily positive since we have stipulated that $s_0(\man) > 3\tau$. In fact, $a \geq 2b$, a fact that we can use to sharpen the bound $\sqrt{a^2 - b^2} \geq a-b$. When $a \geq 2b$, $\sqrt{a^2 - b^2} \geq a - 0.27b$, which can be verified easily by plugging in and bounding. Thus,
\begin{align}
    \begin{split}
        4\|x-y\|_2 &{} r_0(\man)\sqrt{B}  \\
        &{} \geq 4\|x-y\|_2r_0(\man)\biggl(\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr) \\ 
        &{} \hspace{5mm} + 2\cos^2(\theta)\|x-\proj_{\man}x\|_2^2\\
        &{} \hspace{10mm} - 0.54 \|x-\proj_{\man}x\|_2\sin(\theta)\sqrt{r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta)}\biggr). \label{eq: radical simplified (2)}
    \end{split}
\end{align}
Now we will evaluate a bound on one of the roots of \ref{eq: quadratic formula} by combining \ref{eq: radical simplified (2)}, \ref{eq: numerator term 1} and \ref{eq: denominator},
\begin{multline} \label{eq: expression for z (1)}
        z \geq \frac{\Bigl(r_0(\man) - \|x-\proj_{\man}x\|_2\cos(\theta)\Bigr)\Bigl(d^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)}{2\|x-y\|_2\Bigl(r_0(\man)^2 - \|x - \proj_{\man}x\|_2^2\cos^2(\theta)\Bigr)} \\
        + \frac{-2 r_0(\man)\|x-\proj_{\man}x\|_2}{2\|x-y\|_2\Bigl(r_0(\man)^2 - \|x - \proj_{\man}x\|_2^2\cos^2(\theta)\Bigr)}\\
        \cdot \Bigl(r_0(\man)\cos(\theta) - \|x-\proj_{\man}x\|_2 \cos^2(\theta) + 0.27 \sin(\theta)\sqrt{r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta)}\Bigr).
\end{multline}
Bounding the numerator of the second term from below (since the denominator is nonnegative),
\begin{align}
    \begin{split}
        -2 r_0(\man)\|x-\proj_{\man}x\|_2&{} \Bigl(r_0(\man)\cos(\theta) - \|x-\proj_{\man}x\|_2 \cos^2(\theta)\\
        &\hspace{10mm}+ 0.27\sin(\theta)\sqrt{r_0(\man)^2 - \|x-\proj_{\man}x\|_2^2 \cos^2(\theta)}\Bigr) \\
        & \geq -2 r_0(\man)\tau\Bigl(r_0(\man) + 0.27r_0(\man)\Bigr)
    \end{split} \\
    & = -2.54 r_0(\man)^2 \tau.
\end{align}
Now we will bound the numerator of the first term from below. We can apply the lower bound from \ref{eq: difference lower bound} with $d$ evaluated at $s_0(\man) - \tau$ to get
\begin{align}
    \begin{split}
        &{}\Bigl(r_0(\man) - \|x-\proj_{\man}x\|_2\cos(\theta)\Bigr)\\
        &\hspace{30mm}\Bigl((s_0(\man) - \tau)^2 + 2dr_0(\man) - \|x-y\|_2^2 - \|x-\proj_{\man}x\|_2^2\Bigr)
    \end{split}\\
    &\hspace{20mm} \geq (r_0(\man) - \tau)(2(s_0(\man) - \tau)r_0(\man)) \\
    &\hspace{20mm} = 2(r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man).
\end{align}
Putting it all together, we get
\begin{align} \label{eq: expression for z (2)}
        z &\geq \frac{2(r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man) -2.54 r_0(\man)^2 \tau}{2\|x-y\|_2\Bigl(r_0(\man)^2 - \|x - \proj_{\man}x\|_2^2\cos^2(\theta)\Bigr)} \\
        &= \frac{(r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man) -1.27 r_0(\man)^2 \tau}{\|x-y\|_2\Bigl(r_0(\man)^2 - \|x - \proj_{\man}x\|_2^2\cos^2(\theta)\Bigr)}
\end{align}
Now we will show that the numerator is necessarily larger than zero, allowing us to further bound $z$ by upper bounding the denominator. Note that the numerator is greater than zero if and only if 
\begin{align*}
    (r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man)  &> 1.27 r_0(\man)^2 \tau \\
    \iff \frac{(r_0(\man) - \tau)(s_0(\man) - \tau)}{r_0(\man) \tau}  &> 1.27 
\end{align*}
Note that $(r_0(\man) - \tau)/r_0(\man) > 2/3$ since $r_0(\man) > 3\tau$, and $(s_0(\man) - \tau)/\tau > 2$ since $s_0(\man) > 3\tau$. Thus, the left-hand side of the equation above is larger than $4/3$ which is larger than $1.27$, rendering the statement true and the numerator positive. Now we can continue to bound $z$ by upper bounding the denominator,
\begin{align} \label{eq: expression for z (3)}
        z &\geq \frac{(r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man) -1.27 r_0(\man)^2 \tau}{\|x-y\|_2\Bigl(r_0(\man)^2 - \|x - \proj_{\man}x\|_2^2\cos^2(\theta)\Bigr)} \\
        &> \frac{(r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man) -1.27 r_0(\man)^2 \tau}{r_0(\man)^2\sqrt{(s_0(\man)-\tau)^2-\tau^2}} \\
        &= \frac{(r_0(\man) - \tau)(s_0(\man) - \tau) -1.27 r_0(\man) \tau}{r_0(\man)\sqrt{(s_0(\man)-\tau)^2-\tau^2}}.
\end{align}
Finally, we can derive a bound on $\phi'$ from \ref{eq: expression for z (3)} since $z = \arccos(\phi')$,

\begin{equation}\label{eq: phi bound}
    \phi' < \arccos\biggl(\frac{(r_0(\man) - \tau)(s_0(\man) - \tau)r_0(\man) -1.27 r_0(\man)^2 \tau}{r_0(\man)^2\sqrt{(s_0(\man)-\tau)^2-\tau^2}}\biggr).
\end{equation}
Note that the fact that the numerator and denominator are positive implies the right-hand side of \ref{eq: phi bound} is necessarily $< \pi/2$. For all $\phi > \phi'$ we have $d < s_0(\man) - \tau$. Thus it must also be true that for all $\phi$ larger than the right-hand side of \ref{eq: phi bound}, $d < s_0(\man) - \tau$. however, it remains to show that this is in fact a violation of branch separation. Since the nearest point to $y$ on $C$ might not be (and likely is not) $\proj_{\man}x$, we need to show that the manifold distance between $y$ and this point is large. For ease of notation, let $C(t_y)$ be the nearest point to $y$ on $C$.

First we need to bound the distance $d_{\man}(\proj_{\man}x, C(t_y))$. Since $C$ has radius of curvature $r_0(\man)$, $d_{\man}(\proj_{\man}x, C(t_y))$ can be expressed as 
\begin{equation}\label{eq: gamma displacement}
    d_{\man}(\proj_{\man}x, C(t_y)) = r_0(\man) \arctan\biggl(\frac{\|x-y\|_2\sin(\phi)}{\|\proj_{\man}x - y''\|_2 + r_0(\man)}\biggr).
\end{equation}
This follows from Figure \ref{fig: gamma}, as we are approximating the geodesic arc $\gamma$ with $C$. The distance along $C$ from $\proj_{\man}x$ to $C(t_y)$ can be written as the angle swept out times the radius of curvature. Note that $\arctan(x)$ is an increasing function of $x$, and $\arctan(x) \leq x$ for $x \geq 0$. Since $\phi \in [0, \pi/2)$ the argument of $\arctan$ in \ref{eq: gamma displacement} is necessarily non-negative, allowing us to bound it as follows
\begin{align}
    d_{\man}(\proj_{\man}x, C(t_y)) &=  r_0(\man) \arctan\biggl(\frac{\|x-y\|_2\sin(\phi)}{\|\proj_{\man}x - y''\|_2 +  r_0(\man)}\biggr) \\
    & \leq  r_0(\man) \arctan\biggl(\frac{\|x-y\|_2\sin(\phi)}{ r_0(\man)}\biggr)\\
    &\leq  r_0(\man) \cdot \frac{\|x-y\|_2\sin(\phi)}{ r_0(\man)}\\
    &= \|x-y\|_2\sin(\phi). \label{eq: gamma displacement bound}
\end{align}
Now we can apply assumptions on $\epsilon$ to bound \ref{eq: gamma displacement bound} as a function of manifold embedding parameters. 
\begin{align}
    \hspace{-27.5mm}d_{\man}(\proj_{\man}x, C(t_y)) &\leq \|x-y\|_2\sin(\phi) \\
    &\leq \epsilon \\
    &< r_0(\man). \label{eq: gamma displacement bound (2)}
\end{align}
Now we can apply the triangle inequality,
\begin{align}
    d_{\man}(C(t_y), \proj_{\man}y) &\geq d_{\man}(\proj_{\man}x, \proj_{\man}y) - d_{\man}(C(t_y), \proj_{\man}x) \\
    &> (\pi+1) r_0(\man) - r_0(\man) \\
    &= \pi r_0(\man). 
\end{align}
As before, we will apply the definition of \textit{minimum branch separation}, which states that if $d_{\man}(C(t_y), \proj_{\man}y)$ is larger than $\pi r_0(\man)$, then $d = \|C(t_y) - \proj_{\man}y\|_2 \geq s_0(\man).$ Applying the triangle inequality one more time leads to the conclusion that $\|C(t_y) - y\|_2 \geq s_0(\man) - \tau$. However, we see that when $\phi$ does not satisfy \ref{eq: phi bound}, $d < s_0(\man) - \tau$ and we have a contradiction. 

\qed{}

\Cref{lem: phi} formalizes and proves the fact that shortcut edges are necessarily oriented close to a normal direction to $\man$ from the perspective of each endpoint. To leverage this result, we then need to be able to say that this orientation implies a concentration of measure away from the midpoint of all shortcuts. \Cref{fig:proof visualization} provides a visualization of this phenomenon, establishing intuition for why this is true. 

Concretely, \Cref{lem: probability of safe region} derives the measure of the sets $U_x$ and $\eball(x)$ detailed in \Cref{fig: safe region} in the limit of vanishing noise. The expressions for the measures of these sets are obtained by integrating the probability density function $\rho$ (detailed in \cref{eq: pdf}) over each respective set. What results is an expression that is a function of $\phi$, the angle between the edge $(x,y)$ and the closest normal direction of $\man$ at $x$. 

Intuitively, the result matches what we would expect to see in the no noise ($\sigma = 0$) scenario. The $m$-dimensional Lebesgue measure of $U_x$ when the center of $\eball(x)$ is displaced at a distance $\|x-\proj_{\man}x\|_2$ from a $m$-dimensional manifold $\man$ would simply be (in the locally flat case) proportional to the volume of the intersection, which is a portion of a $m$ dimensional ball of radius $\sqrt{\smash[b]{\epsilon^2 - \|x-\proj_{\man}x\|_2^2}}$. The conditional probability of a point being in $U_x$ given $\eball(x)$ would therefore be the ratio of the volume of this portion of a $m$ dimensional ball to the full volume of the $m$ dimensional ball. \Cref{fig: vanishing noise} provides a visualization for a $2$-dimensional manifold embedded in $\mathbb{R}^3$.

\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\textwidth]{figures/diagrams/lemmas/vanishing_noise.pdf}
    \caption{A visualization of $v \in N_{\proj_{\man}x}$, $U_x$ and the edge $(x,y)$ for a 2-dimensional manifold embedded in $\mathbb{R}^3$. Observe that the measure of $\eball(x) \setminus U_x$ approaches the volume of the intersection of $\eball(x) \setminus U_x$ and $\man$ as $\sigma \rightarrow 0$. Similarly, the measure of $U_x$ approaches the volume of the intersection of $U_x$ and $\man$ as $\sigma \rightarrow 0$. Both of these regions are shown as the 2-dimensional dark grey and matte blue shaded regions respectively.}
    \label{fig: vanishing noise}
\end{figure}

\begin{lemma}\label{lem: probability of safe region}
    Suppose $(x,y)$ is an edge in a nearest neighbor graph built from data consisting of samples from the probability density function defined by \ref{eq: pdf}. Define $v$ to be the vector in the normal space of $\man$ at $\proj_{\man}x$ such that the angle $\phi$ between $v$ and $(y-x)$ is minimized. Also define
    \[f(\phi) = \cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr)\]
    and,
    \[R = \sqrt{\smash[b]{\epsilon^2 - \|x-\proj_{\man}x\|_2^2}}\]
    and finally,
    \begin{equation}
        r(z) = 
        \begin{cases}
            \sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 - z^2} & |z| \leq \sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2} \\
            0 & \text{otherwise}
        \end{cases}.
    \end{equation}
    Then
    \begin{align}
        \lim_{\sigma \rightarrow 0^+}\mathbb{P}[\, a \in U_x \, | \, a \in \eball(x) \, ] &\geq \frac{\bigintssss_{f(\phi)}^{\sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2}} \vol(B^{m-1}_{r(z)}(0)) dz}{\vol(B_R^m(0))}
    \end{align}
    where $m$ is the dimension of $\man$.
\end{lemma}

\textit{Proof.} Rewriting $\mathbb{P}[\, a \in U_x \, | \, a \in \eball(x) \, ]$, 
\begin{align}
    \mathbb{P}[\, a \in U_x \, | \, a \in \eball(x) \, ] &= \ddfrac{\mathbb{P}[\, a \in U_x  \, ]}{\mathbb{P}[ \, a \in \eball(x) \, ]} \\
    &= \frac{\mu\bigl(U_x\bigr)}{\mu\bigl(\eball(x)\bigr)} \label{eq: probability safe}
\end{align}

Since the probability density in $\eball(x)$ is nonuniform, we need to integrate $\rho$ over the regions we are interested in. To do so, we will integrate along $v \in N_{\proj_{\man}x}\man$ and use a locally flat approximation of $\man$. Observe that $(y-x)$ can be written as $\alpha v_{T} + \beta v$, where $v_{T} \in T_{\proj_{\man}x}$, and $v$ is the vector in $N_{\proj_{\man}x}\man$ that forms the smallest angle $\phi$ with the vector $(y-x)$. Also note that the vector $(x - \proj_{\man}x)$ is oriented normal to $\man$ at $\proj_{\man}x$ as well. It can therefore be written as $d_v v + d_x v_N$, where $v$ is the vector defined previously and $v_N$ is some other vector in the normal space. It follows that $d_v = \|x-\proj_{\man}x\|_2 \cos(\theta)$ and $d_x = \|x-\proj_{\man}x\|_2 \sin(\theta)$, where $\theta$ is the angular displacement between $(x-\proj_{\man}x)$ and $v$. A visualization of these quantities and vectors is provided in \Cref{fig: safe region quantities}. 

\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\textwidth]{figures/diagrams/lemmas/safe_region_quantities.pdf}
    \caption{A visualization of quantities defined and used for \Cref{lem: probability of safe region}. }
    \label{fig: safe region quantities}
\end{figure}

All coordinates mentioned from here onwards specify displacements from the point $\proj_{\man}x$. Note that $m$ orthogonal ambient directions are oriented tangent to $\man$ at $\proj_{\man}x$, while $D - m$ directions are oriented normal to $\man$ at $\proj_{\man}x$. Since the probability density is constant in tangential directions, we will begin by evaluating the measure of the subspace spanned by the normal directions directly; thereafter we will integrate along the tangent directions.

Let $u_1, u_2, u_{m+3}, \dots, u_D$ denote coordinates in an orthonormal basis of $N_{\proj_{\man}x}\man$, where $u_1$ corresponds with direction $v$ and $u_{2}$ corresponds with direction $v_N$. Now let $z_3, \dots, z_{m+2}$ denote coordinates in the $m$ tangential directions. We choose to define these coordinates with these indices as it reflects the order in which we will integrate. This choice will become clear deeper into the proof.

Observe that $x$'s only nonzero coordinates (as we have just defined them) are $u_1$ and $u_2$. Therefore the probability density $\rho$ is symmetric about $u_i = 0$ for $i \in \{m+3, \dots, D\}$. This arises from the fact that the $u$ coordinates are the only coordinates in which the probability density varies - $z$ coordinates have no effect (due to our locally flat approximation). Therefore, we will begin by evaluating the measure of the subspace of $\eball(x)$ (centered at fixed coordinates $u_1, u_2, z_3, \dots, z_{m+2}$) spanned by normal directions $u_{m+3}, \dots, u_D$. The probability density at any point in this subspace is simply a function of $u$ coordinates,
\begin{align*}
    \rho(u_1, u_2, z_3, \dots, z_{m+2}, u_{m+3}, \dots, u_D) &= \frac{1}{Z} \exp\biggl(-\frac{u_1^2 + u_2^2 + \sum_{i=d+3}^Du_i^2}{2\sigma^2}\biggr) \\
    &= \frac{1}{Z}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\exp\biggl(-\frac{\sum_{i=d+3}^Du_i^2}{2\sigma^2}\biggr).
\end{align*}
Observe that the point $(u_1, u_2, z_3, \dots, z_{m+2}, 0, \dots, 0)$ is at the same distance from the boundary of the tubular neighborhood in any direction spanned by $u_i$ for $i \in \{m+3, \dots, D\}$. While we do not yet have an exact expression for that distance, we can represent it as some function of $(u_1, u_2, z_3, \dots, z_{m+2})$, denoted $r(u_1, u_2, z_3, \dots, z_{m+2}) = r$. Put another way, if we consider the intersection of $\tub_{\tau}\man$, $\eball(x)$ and the subspace spanning $u_{m+3}, \dots, u_D$ centered at $(u_1, u_2, z_3, \dots, z_{m+2}, 0, \dots, 0)$, it looks like a $D - m-2$ dimensional ball of radius $r$.

Thus, we can evaluate the measure of this subspace of $\eball(x)$ centered at the point with coordinates $(u_1, u_2, z_3, \dots, z_{m+2}, 0, \dots, 0)$ spanned by normal directions $u_{m+3}, \dots, u_D$ as
\[ \frac{1}{Z}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) \bigintssss_{\mathbf{u}_{m+3:D} \, \in \, B_{r}(0)} \exp\biggl(-\frac{\sum_{i=d+3}^Du_i^2}{2\sigma^2}\biggr) dV.\]
Now we will manipulate the term in the integral so that it becomes equivalent to the CDF of a $\chi^2$ distribution with $D - m - 2$ degrees of freedom, 
\begin{align*}
    \begin{split}
        \frac{1}{Z}\exp&\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) \bigintssss_{\mathbf{u}_{m+3:D} \, \in \, B_{r}(0)} \exp\biggl(-\frac{\sum_{i=d+3}^Du_i^2}{2\sigma^2}\biggr) dV\\
        &= \frac{\bigl(2\pi\bigr)^{\frac{D - m - 2}{2}}}{Z}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) \bigintssss_{\mathbf{u}_{m+3:D} \, \in \, B_{r}(0)} \frac{1}{\bigl(2\pi\bigr)^{\frac{D - m - 2}{2}}}\exp\biggl(-\frac{\sum_{i=d+3}^Du_i^2}{2\sigma^2}\biggr) dV
    \end{split} \\
    \begin{split}
        {}&= \underbrace{\frac{\sigma^{D - m-2} \bigl(2\pi\bigr)^{\frac{D - m - 2}{2}}}{Z}}_{:=\, C}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) \\
        &\hspace{40mm}\cdot\underbrace{\bigintssss_{\mathbf{w}_{m+3:D} \, \in \, B_{r/\sigma}(0)} \frac{1}{\bigl(2\pi\bigr)^{\frac{D - m - 2}{2}}} \exp\biggl(-\frac{\sum_{i=d+3}^Dw_i^2}{2}\biggr) dV}_{F_{\chi^2}\bigl(\frac{r^2}{\sigma^2}\bigr)} 
    \end{split}\\
    &= C\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)F_{\chi^2}\Bigl(\frac{r^2}{\sigma^2}\Bigr)
\end{align*}
where the third to last line was obtained by applying the change of variables $w_i = u_i/\sigma$ for $i \in \{m+3, \dots, D\}$. Now we would like to integrate this expression over all remaining directions $z_{3}, \dots, z_{m+2}$ and $u_1, u_2$. To obtain appropriate limits of integration, its helpful to explicitly write out an expression for relevant parts of the sets $\eball(x)$ and the local region of $\tub_{\tau}\man$ in terms of the defined coordinates. The sets can be described as
\begin{multline}
    \eball(x) = \biggl\{(u_1, u_2, z_3, \dots, z_{m+2}, u_{m+3}, \dots, u_D) \, \Bigl| \, (u_1 - d_v)^2 + (u_2 - d_x)^2 \\
    + \sum_{i = 3}^{m+2}z_i^2 + \sum_{i = d+3}^D u_i^2 \leq \epsilon^2 \biggr\}
\end{multline}
and
\[S = \biggl\{(u_1, u_2, z_3, \dots, z_{m+2}, u_{m+3}, \dots, u_D) \, \Bigl| \, \sum_{i \in \{1, 2, d+3, \dots, D\}} u_i^2 \leq \tau^2 \biggr\}\]
respectively, where $S$ describes the local region of the tubular neighborhood (when $\man$ is approximated as flat). Naturally, we are interested in integrating over the intersection of these two regions. We will start with $z_{m+2}$. Observe that the limits for $z_{m+2}$ are necessarily symmetric - this follows from the fact that the point $(u_1, u_2, z_3, \dots, z_{m+1}, 0, \dots, 0)$ is equidistant along $z_{m+2}$ from the boundary of $\eball(x)$ in both the positive and negative directions. This distance is precisely 
\begin{equation}\label{eq: z_d+2 limit of int}
    \sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}.
\end{equation}
We do not concern ourselves with the boundary of $\tub_{\tau}\man$ in the tangential directions because we are employing a locally flat approximation. Now note that, for a point with coordinates $(u_1, u_2, z_3, \dots, z_{m+1}, z_{m+2}, 0, \dots, 0)$ the distance to the boundary of $\eball(x)$ in any direction spanned by $u_{m+3}, \dots, u_D$ is a slight modification to \ref{eq: z_d+2 limit of int}
\begin{equation}\label{eq: chi squared argument (1)}
    \sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2}.
\end{equation}
Observe that this gives us part of our expression for $r(u_1, u_2, z_3, \dots, z_{m+2})$. In the normal directions, however, we are \textit{also} concerned with the boundary of $\tub_{\tau}\man$, which is necessarily at a distance 
\begin{equation}\label{eq: chi squared argument (2)}
    \sqrt{\tau^2 - u_1^2 - u_2^2}
\end{equation}
in any direction spanned by $u_{m+3}, \dots, u_D$. Thus, the limits of integration for $z_{m+2}$ directions must range from $-1$ times \ref{eq: z_d+2 limit of int} to $+1$ times \ref{eq: z_d+2 limit of int}. The radius in the argument of $F_{\chi^2}$ must then be the minimum of \cref{eq: chi squared argument (1)} and \cref{eq: chi squared argument (2)}. Now integrating out $z_{m+2}$ yields
\begin{multline}
    \mu\Bigl[\eball(x) \cap S \, \Big|_{(u_1, u_2, z_3, \dots, z_{m+1})}\Bigr] = C\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) dz_{m+2}
\end{multline}
where $\eball(x) \cap S \, \Big|_{(u_1, u_2, z_3, \dots, z_{m+1})}$ denotes the subset of $\eball(x) \cap S$ when we fix all listed coordinates and allow the others to vary. Now we can apply the same argument to integrate out $z_{m+1}$. A point with coordinates $(u_1, u_2, z_3, \dots, z_{d}, 0, 0, \dots, 0)$ is at distance 
\begin{equation}\label{eq: z_d+1 limit of int}
    \sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}
\end{equation}
from the boundary of $\eball(x)$ in the $\pm \, z_{m+1}$ directions. Thus,
\begin{multline}
    \mu\Bigl[\eball(x) \cap S \, \Big|_{(u_1, u_2, z_3, \dots, z_{d})}\Bigr] = \\
    C\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) dz_{m+2}dz_{m+1}.
\end{multline}
Repeating this process for all remaining $z_i$'s yields
\begin{multline}
    \mu\Bigl[\eball(x) \cap S \, \Big|_{(u_1, u_2)}\Bigr] = C\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3.
\end{multline}
A point with coordinates $(u_1, 0, \dots, 0)$ is at distance
\begin{equation}
    \sqrt{\epsilon^2 - (u_1 - d_v)^2} - d_x
\end{equation}
from the boundary of $\eball(x)$ in the $- u_2$ direction, while it is at distance
\begin{equation}
    \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x
\end{equation}
in the $+ u_2$ direction. This can be verified by inspecting \Cref{fig: safe region quantities}. Since $u_2$ spans a normal direction, we must also consider the boundary of $\tub_{\tau}\man$. Namely, the point $(u_1, 0, \dots, 0)$ is at distance
\begin{equation}
    \sqrt{\tau^2 - u_1^2}
\end{equation}
from the boundary of $\tub_{\tau}\man$ in the $\pm \, u_2$ direction. Therefore,
\begin{multline}
    \mu\Bigl[\eball(x) \cap S \, \Big|_{(u_1)}\Bigr] = \\
    C\bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3du_2.
\end{multline}
And finally since $2\tau < \epsilon$ we have,
\begin{multline}
    \mu\Bigl[\eball(x) \cap S \, \Bigr] = \\
    C\bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3du_2du_1.
\end{multline}
To obtain an expression for $\mu[\eball(x)]$ we need one more component. Visual inspection of \Cref{fig:proof visualization} reveals that some of the measure of $\eball(x)$ can come from a region of the manifold that is at a far intrinsic distance, but small Euclidean distance. This is a phenomenon we have not yet accounted for. To do so, we will provide a large overestimate of the measure it contributes (which in the end, will not affect the conclusion of the proof). Since it is hard to quantify the volume of this region in the general case, we know its volume is necessarily bounded by $\vol(\eball(x))$. It follows that its measure is upper bounded by the maximum probability density in the region times $\vol(\eball(x))$.

To find the maximum probability density in this region, we need to reason about the minimum distance any point in this region can have to the manifold. Consider a point $p$ in this region, and its corresponding nearest point on $\man$, $\proj_{\man}p$. Since we have stipulated $r_0(\man) > \epsilon$, any manifold geodesic path through $\proj_{\man}x$ could not have left $\eball(x)$ and re-entered it without travelling more than $\pi r_0(\man)$ distance. Our locally flat approximation ensures that our expression for $\mu[\eball(x)]$ accounts for the volume traced out by all geodesic paths that pass through $\proj_{\man}x$ before they leave $\eball(x)$; thus the only measure we have not accounted for is associated with areas of $\man$ where a geodesic path through $\proj_{\man}x$ left $\eball(x)$ and later returned. 

Since we know the manifold distance from $\proj_{\man}x$ to $\proj_{\man}p$ exceeds $\pi r_0(\man)$, we know $\|\proj_{\man}x - \proj_{\man}p\|_2 \geq s_0(\man)$ from the definition of minimum branch separation. Using the triangle inequality and applying assumptions to bound $\epsilon$ and $\tau$ we can say
\begin{align*}
    \|p - \proj_{\man}p\|_2 &\geq \|\proj_{\man}x - \proj_{\man}p\|_2 - \|x - \proj_{\man}x\|_2 - \|x-p\|_2 \\
    & > s_0(\man) - \tau - \sqrt{(s_0(\man) - \tau)^2 - \tau^2} \\
    & := \delta \\
    &> 0.
\end{align*}
Thus, the measure of this distant region of $\eball(x)$ is necessarily bounded above by
\[\vol\Bigl(\eball(x)\Bigr) \frac{1}{Z}\exp\Bigl(-\frac{\delta^2}{2\sigma^2}\Bigr).\]
Thus, we can safely conclude that
\begin{multline}\label{eq: measure eball}
    \mu\Bigl[\eball(x)\Bigr] \leq \\
    C\bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3du_2du_1 + \vol\Bigl(\eball(x)\Bigr) \frac{1}{Z}\exp\Bigl(-\frac{\delta^2}{2\sigma^2}\Bigr).
\end{multline}
Computing $\mu[U_x]$ involves changing the lower limit of integration for $z_3$. In the $u_1$, $z_3$ plane the boundary of $U_x$ is simply a line with slope $\tan(\phi)$; the $u_1$ intercept can be obtained with simple geometry, and is $d_v - \sec(\phi)(\frac{\epsilon - \|x-y\|_2}{2})$. It follows that the expression for the boundary can be rearranged as,
\[z_3 = \cot(\phi)\biggl(u_1 - d_v + \sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr)\biggr).\]
To understand this step we encourage the reader to refer back to \Cref{fig: safe region} to recall the definition of $U_x$. Moving forward, for the sake of simplicity we can also discard the second term in \cref{eq: measure eball} to obtain a lower bound on $\mu[U_x]$. Therefore,
\begin{multline}\label{eq: measure U_x}
    \mu\Bigl[U_x\Bigr] \leq \\
    C\bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\bigintssss_{\cot(\phi)\bigl(u_1 - d_v + \sec(\phi)\bigl( \frac{\epsilon - \|x-y\|_2}{2}\bigr)\bigr)}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3du_2du_1.
\end{multline}
We are interested in evaluating the ratio of \ref{eq: measure U_x} and \ref{eq: measure eball}
in the limit of $\sigma \rightarrow 0^+$. Since \ref{eq: measure eball} is the measure of a finite volume subset of $\mathbb{R}^D$ with a nonempty intersection with the support of $\rho$, for all $\sigma > 0$ the quantity is nonzero. To make sure the limits converge to a nonzero value, we will multiply the top and bottom by $\frac{1}{2\pi\sigma^2C}$. As we will also show, the ensures that the limit of the denominator converges to a nonzero value. Thus we can pull the limit into the fraction to say,
\begin{equation} \label{eq: limit of ratio of measures}
 \lim_{\sigma \rightarrow 0^+}\frac{\frac{1}{2\pi\sigma^2C}\mu[U_x]}{\frac{1}{2\pi\sigma^2C}\mu[\eball(x)]} = \frac{\lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu[U_x]}{\lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu[\eball(x)]}.
\end{equation}
The denominator can be bounded with
\begin{multline}
    \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] \leq \\
    \bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\frac{1}{2\pi\sigma^2}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\Biggl[\bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3 \Biggr]du_2du_1 + \frac{1}{2\pi\sigma^2}\vol\Bigl(\eball(x)\Bigr) \frac{1}{CZ}\exp\Bigl(-\frac{\delta^2}{2\sigma^2}\Bigr).
\end{multline}
Defining everything in the bracket as $g(u_1, u_2)$ and taking the limit, we get
\begin{multline}\label{eq: eball measure bound (0)}
    \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] \\
    \leq  \lim_{\sigma \rightarrow 0^+}  \bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\frac{1}{2\pi\sigma^2}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) g(u_1, u_2) du_2 du_1 \\
    + \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2}\vol\Bigl(\eball(x)\Bigr) \frac{1}{CZ}\exp\Bigl(-\frac{\delta^2}{2\sigma^2}\Bigr).
\end{multline}
The second term can be rewritten as,
\begin{equation*}
    \lim_{\sigma \rightarrow 0^+} \frac{\vol\bigl(\eball(x)\bigr)}{(2\pi)^{(D - m+2)/2}\cdot\sigma^{D - m}}\exp\Bigl(-\frac{\delta^2}{2\sigma^2}\Bigr).
\end{equation*}
Since $\delta$ is a constant, one can use repeated applications of L'Hopital's rule to show that this term converges to $0$ in the limit. Now we can focus on the first term of \cref{eq: eball measure bound (0)},
\begin{multline}
    \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] \\
    \leq  \lim_{\sigma \rightarrow 0^+}  \bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}\frac{1}{2\pi\sigma^2}\exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) g(u_1, u_2) du_2 du_1.
\end{multline}
Define the limits of integration for $u_2$ as $L_{\text{low}}(u_1)$ and $L_{\text{up}}(u_1)$ respectively. Now we will rewrite the equation above, replacing the limits of integration with indicators
\begin{multline}\label{eq: limits of int redefine}
    \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] 
    \leq  \lim_{\sigma \rightarrow 0^+}  \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty} \frac{1}{2\pi\sigma^2} \exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)
    \\ \cdot \mathbbm{1}\Bigl[u_2 \in [L_{\text{low}}(u_1), L_{\text{up}}(u_1)], u_1 \in [-\tau, \tau]\Bigr] g(u_1, u_2) du_2 du_1.
\end{multline}
Applying the change of variables $w_1 = u_1/\sigma$ and $w_2 = u_2/\sigma$ yields,
\begin{multline}
    \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] 
    \leq  \lim_{\sigma \rightarrow 0^+}  \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr)
    \\ \cdot \mathbbm{1}\Biggl[w_2 \in \Bigl[\frac{L_{\text{low}}(\sigma w_1)}{\sigma}, \frac{L_{\text{up}}(\sigma w_1)}{\sigma}\Bigr], w_1 \in [-\tau/\sigma, \tau/\sigma]\Biggr] g(\sigma w_1, \sigma w_2) dw_2 dw_1.
\end{multline}
Observe that $g$ as defined is simply an integral of a function bounded by $1$ over a region bounded by $\eball(x)$. Therefore, $g$ must be no larger than $\vol(\eball(x))$. Clearly the function
\[\frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr)\vol(\eball(x)) \]
dominates the integrand of $g$; furthermore, this function is integrable as the double integral over $w_1$ and $w_2$ evaluates to $\vol(\eball(x))$. Therefore we can use it as our dominating function to invoke the dominated convergence theorem, allowing us to pull the limit into the integral,
\begin{multline}\label{eq: eball measure bound (1)}
    \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] 
    \leq   \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr)
    \\ \cdot \lim_{\sigma \rightarrow 0^+}\mathbbm{1}\Biggl[w_2 \in \Bigl[\frac{L_{\text{low}}(\sigma w_1)}{\sigma}, \frac{L_{\text{up}}(\sigma w_1)}{\sigma}\Bigr], w_1 \in [-\tau/\sigma, \tau/\sigma]\Biggr] \lim_{\sigma \rightarrow 0^+} g(\sigma w_1, \sigma w_2) dw_2 dw_1.
\end{multline}
Note that $L_{\text{low}}(0)$ is necessarily negative, as $\sqrt{\epsilon^2 - d_v^2} \geq \sqrt{\epsilon^2 - \tau^2} \geq \sqrt{4\tau^2 - \tau^2} = \tau\sqrt{3} > d_x$. Therefore, the indicator function in the integrand converges pointwise to $1$. Writing out the second term,
\begin{multline}
    \lim_{\sigma \rightarrow 0^+} g(\sigma w_1, \sigma w_2) = \lim_{\sigma \rightarrow 0^+}\bigintssss_{-\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2}}^{\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2}} \\
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \bigintssss_{-\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - \sigma w_1^2 - \sigma w_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots dz_3.
\end{multline}
We can pull all limits of integration into an indicator function, but for the sake of brevity we will not write it out. Note that this step is simply taken to illustrate the fact that we can invoke the dominated convergence theorem again. Observe then that for all $\sigma > 0$ such that the terms inside of the radicals are nonnegative, we are integrating a Chi-squared CDF (which is bounded above by $1$) over $\mathbb{R}^m$. However, the aforementioned indicator function is always bounded by an indicator over the set $B_{\epsilon}^m(0)$. Thus, we can choose $\mathbbm{1}[\mathbf{z}_{3:d+2} \in B_{\epsilon}^m(0)]$ as our integrable dominating function, allowing us to pull the limit into the integrals. 

We can evaluate the indicator function in the limit, and pull the indicators back into the limits of integration. Also observe that the integrand (the CDF of the Chi-squared distribution) converges to $1$ as its argment converges to $+\infty$. Thus,
\begin{align}
    \begin{split}
        \lim_{\sigma \rightarrow 0^+} g(\sigma w_1, \sigma w_2) &= \bigintssss_{-\sqrt{\epsilon^2 - d_v^2 - d_x^2}}^{\sqrt{\epsilon^2 - d_v^2 - d_x^2}} \cdots \bigintssss_{-\sqrt{\epsilon^2 - d_v^2 - d_x^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - d_v^2 - d_x^2 - \sum_{i = 3}^{m}z_i^2}}\\
        & \hspace{40mm} \bigintssss_{-\sqrt{\epsilon^2 -  d_v^2 - d_x^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - d_v^2 - d_x^2 - \sum_{i = 3}^{m+1}z_i^2}} dz_{m+2}dz_{m+1} \dots dz_3
    \end{split} \\
    &= \vol\Bigl(B_R^m(0)\Bigr)
\end{align}
where $R = \sqrt{\smash[b]{\epsilon^2 - \|x-\proj_{\man}x\|_2^2}}$ since $d_v^2 + d_x^2 = \|x-\proj_{\man}x\|_2^2$. Note $B_R^m(0)$ denotes an $m$-dimensional Euclidean ball of radius $R$. Plugging this into \cref{eq: eball measure bound (1)},
\begin{align}
    \lim_{\sigma \rightarrow 0^+} \frac{1}{2\pi\sigma^2C}\mu\Bigl[\eball(x)\Bigr] 
    &\leq \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr) \cdot \vol\Bigl(B_r^m(0)\Bigr) dw_2 dw_1 \\
    &= \vol\Bigl(B_r^m(0)\Bigr) \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr) dw_2 dw_1 \\
    &= \vol\Bigl(B_r^m(0)\Bigr). \label{eq: measure eball limit}
\end{align}
Now we want to evaluate $\frac{1}{2\pi\sigma^2C}\mu[U_x]$ in the limit. Recall,
\begin{multline}
    \frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}} \frac{1}{2\pi\sigma^2} \exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\\\bigintssss_{\cot(\phi)\bigl(u_1 - d_v + \sec(\phi)\bigl( \frac{\epsilon - \|x-y\|_2}{2}\bigr)\bigr)}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} \Biggl[
     \cdots \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m}z_i^2}}
    \\ \bigintssss_{-\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - u_1^2 - u_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}dz_{m+1} \dots \Biggr] dz_3du_2du_1.
\end{multline}
Define everything in the bracket to be $g'(u_1, u_2, z_3)$. Rewriting we have, 
\begin{multline}
    \frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}} \frac{1}{2\pi\sigma^2} \exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\\\bigintssss_{\cot(\phi)\bigl(u_1 - d_v + \sec(\phi)\bigl( \frac{\epsilon - \|x-y\|_2}{2}\bigr)\bigr)}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} g'(u_1, u_2, z_3) dz_3du_2du_1.
\end{multline}
Taking the limit on both sides,
\begin{multline}
    \lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \\
    \lim_{\sigma \rightarrow 0^+}\bigintssss_{-\tau}^{\tau} \bigintssss_{\max\bigl\{-\sqrt{\tau^2 - u_1^2}, -\sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}}^{\min\bigl\{\sqrt{\tau^2 - u_1^2}, \sqrt{\epsilon^2 - (u_1 - d_v)^2} + d_x\bigr\}} \frac{1}{2\pi\sigma^2} \exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr)\\\cdot\bigintssss_{\cot(\phi)\bigl(u_1 - d_v + \sec(\phi)\bigl( \frac{\epsilon - \|x-y\|_2}{2}\bigr)\bigr)}^{\sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}} g'(u_1, u_2, z_3) dz_3du_2du_1.
\end{multline}
We will use the same definitions for the limits of integration of $u_2$ from \ref{eq: limits of int redefine}, and further define 
\[L_{\text{low}, z_3}(u_1, \phi) = \cot(\phi)\biggl(u_1 - d_v + \sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr)\biggr)\]
and \[L_{\text{up}, z_3}(u_1, u_2) = \sqrt{\epsilon^2 - (u_1 - d_v)^2 - (u_2 - d_x)^2}.\] 
Converting the limits of integration to indicators,
\begin{multline}
    \lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \lim_{\sigma \rightarrow 0^+}\bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty}\bigintssss_{-\infty}^{\infty} \frac{1}{2\pi\sigma^2} \exp\biggl(-\frac{u_1^2 + u_2^2}{2\sigma^2}\biggr) g'(u_1, u_2, z_3)\\
    \mathbbm{1}\Biggl[z_3 \in \Bigl[L_{\text{low}, z_3}(u_1, \phi), L_{\text{up}, z_3}(u_1, u_2)\Bigr] , \\
    \hspace{50mm} u_2 \in \Bigl[L_{\text{low}}(u_1), L_{\text{up}}(u_1)\Bigr], u_1 \in \Bigl[-\tau, \tau\Bigr]\Biggr]\\
    dz_3du_2du_1.
\end{multline}
Now let's apply the same change of variables $w_1 = u_1/\sigma$ and $w_2 = u_2/\sigma$ to get
\begin{multline}
    \lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \lim_{\sigma \rightarrow 0^+}\bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty}\bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr) g'(\sigma w_1, \sigma w_2, z_3)\\
    \cdot \mathbbm{1}\Biggl[z_3 \in \Bigl[L_{\text{low}, z_3}(\sigma w_1, \phi), L_{\text{up}, z_3}(\sigma w_1, \sigma w_2)\Bigr] ,
    \\\hspace{50mm} w_2 \in \biggl[\frac{L_{\text{low}}(\sigma w_1)}{\sigma}, \frac{L_{\text{up}}(\sigma w_1)}{\sigma} \biggr], w_1 \in \Bigl[-\tau/\sigma, \tau/\sigma \Bigr]\Biggr]\\
    dz_3dw_2dw_1.
\end{multline}
Through a similar argument from \ref{eq: eball measure bound (1)}, we can choose the function
\[\frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr)\vol(\eball^{m-1}(0))\]
as our dominating function for the integrand. Now we can pull the limit inside the integrals,
\begin{multline}\label{eq: measure U_x partial}
    \lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty}\bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr) \lim_{\sigma \rightarrow 0^+} g'(\sigma w_1, \sigma w_2, z_3)\\
    \lim_{\sigma \rightarrow 0^+} \mathbbm{1}\Biggl[z_3 \in \Bigl[L_{\text{low}, z_3}(\sigma w_1, \phi), L_{\text{up}, z_3}(\sigma w_1, \sigma w_2)\Bigr] , \\
    \hspace{50mm} w_2 \in \biggl[\frac{L_{\text{low}}(\sigma w_1)}{\sigma}, \frac{L_{\text{up}}(\sigma w_1)}{\sigma} \biggr], w_1 \in \Bigl[-\tau/\sigma, \tau/\sigma \Bigr]\Biggr]\\
    dz_3dw_2dw_1.
\end{multline}
Observe that the indicator converges to
\[\mathbbm{1}\Biggl[z_3 \in \biggl[\cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr), \sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 }\biggr]\Biggr].\]
Now we want to evaluate $g'$ in the limit,
\begin{multline}
    \lim_{\sigma \rightarrow 0^+} g'(\sigma w_1, \sigma w_2, z_3) = \\
    \lim_{\sigma \rightarrow 0^+} \bigintssss_{-\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - z_3^2}}^{\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - z_3^2}} 
    \cdots \bigintssss_{-\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m+1}z_i^2}}
    \\ F_{\chi^2}\biggl(\frac{\min\{\epsilon^2 - (\sigma w_1 - d_v)^2 - (\sigma w_2 - d_x)^2 - \sum_{i = 3}^{m+2}z_i^2, \tau^2 - \sigma w_1^2 - \sigma w_2^2\}}{\sigma^2}\biggr) \\
    dz_{m+2}\dots dz_4.
\end{multline}
Again we can pull all limits of integration into an indicator function, but for the sake of brevity we will not write it out. Note that this step is simply taken to illustrate the fact that we can invoke the dominated convergence theorem again. Observe then that for all $\sigma > 0$ such that the terms inside of the radicals are nonnegative, we are integrating a Chi-squared CDF (which is bounded above by $1$) over $\mathbb{R}^{m-1}$. However, the aforementioned indicator function is always bounded by an indicator over the set $B_{\epsilon}^{m-1}(0)$. Thus, we can choose $\mathbbm{1}[\mathbf{z}_{3:d+2} \in B_{\epsilon}^{m-1}(0)]$ as our dominating function, which is clearly integrable. This allows us to apply the dominated convergence theorem to pull the limit into the integral.

We can evaluate the indicator function in the limit, and pull the indicators back into the limits of integration. Also observe that the integrand (the CDF of the Chi-squared distribution) converges to $1$ as its argment converges to $+\infty$. Thus,
\begin{align}
    \lim_{\sigma \rightarrow 0^+} g'(\sigma w_1, \sigma w_2, z_3) &= \bigintssss_{-\sqrt{\epsilon^2 -  d_v^2 - d_x^2 - z_3^2}}^{\sqrt{\epsilon^2 - d_v^2 - d_x^2 - z_3^2}} 
    \cdots \bigintssss_{-\sqrt{\epsilon^2 - d_v^2 - d_x^2 - \sum_{i = 3}^{m+1}z_i^2}}^{\sqrt{\epsilon^2 - d_v^2 - d_x^2 - \sum_{i = 3}^{m+1}z_i^2}} dz_{m+2}\dots dz_4 \\
    &= \vol\bigl(B_{r(z_3)}^{m-1}(0)\bigr)
\end{align}
where
\begin{equation}\label{eq: r(z_3)}
    r(z_3) = 
    \begin{cases}
        \sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 - z_3^2} & |z_3| \leq \sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2} \\
        0 & \text{otherwise}
    \end{cases}.
\end{equation}
Plugging into \ref{eq: measure U_x partial}, we have
\begin{multline}
    \lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] \geq \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty}\bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr) \vol\bigl(B_{r(z_3)}^{m-1}(0)\bigr)\\
    \mathbbm{1}\Biggl[z_3 \in \biggl[\cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr), \sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 }\biggr]\Biggr]\\
    dz_3dw_2dw_1.
\end{multline}
Pulling the indicator back into the limits of integration and rearranging, we get
\begin{align}
    \begin{split}
        \lim_{\sigma \rightarrow 0^+}\frac{1}{2\pi\sigma^2C}\mu\Bigl[U_x\Bigr] &\geq \bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty}\bigintssss_{\cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr)}^{\sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 }} \\ 
        &\hspace{30mm} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr) \vol\bigl(B_{r(z_3)}^{m-1}(0)\bigr) dz_3dw_2dw_1
    \end{split} \\
    \begin{split}
        &= \underbrace{\bigintssss_{-\infty}^{\infty} \bigintssss_{-\infty}^{\infty} \frac{1}{2\pi} \exp\biggl(-\frac{w_1^2 + w_2^2}{2}\biggr)dw_2dw_1}_{= 1} \\ 
        &\hspace{30mm} \cdot \bigintssss_{\cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr)}^{\sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 }} 
        \vol\bigl(B_{r(z_3)}^{m-1}(0)\bigr) dz_3
    \end{split}\\
    &= \bigintssss_{\cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr)}^{\sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2 }} 
    \vol\bigl(B_{r(z_3)}^{m-1}(0)\bigr) dz_3. \label{eq: measure U_x limit}
\end{align}
Let
\[f(\phi) = \cot(\phi)\Bigl(\sec(\phi)\Bigl( \frac{\epsilon - \|x-y\|_2}{2}\Bigr) - d_v\Bigr)\]
and redefine $z_3$ to $z$. Now we can combine \ref{eq: measure U_x limit} and \ref{eq: measure eball limit} to obtain the bound on \ref{eq: limit of ratio of measures}, and thus bound \ref{eq: probability safe}:
\begin{align}
    \lim_{\sigma \rightarrow 0^+}\mathbb{P}[\, a \in U_x \, | \, a \in \eball(x) \, ] &\geq \frac{\bigintssss_{f(\phi)}^{\sqrt{\epsilon^2 - \|x-\proj_{\man}x\|_2^2}} \vol(B^{m-1}_{r(z)}(0)) dz}{\vol(B_R^m(0))}.
\end{align}

where $R = \sqrt{\smash[b]{\epsilon^2 - \|x-\proj_{\man}x\|_2^2}}$ and $r(z) = \sqrt{\smash[b]{\epsilon^2 - \|x-\proj_{\man}x\|_2^2} - z^2}$. 
\qed{}

\subsubsection{Propositions}\label{sec: proof of propositions}

While the Lemmata represent a majority of the theoretical results of this work, the Theorems that stitch them together require one to show a few more properties. We will start by showing that the minimum radius of curvature of geodesic paths through the tubular neighborhood of a manifold $\man$ have a minimum radius of curvature $r_0(\man) - \tau$, where $r_0(\man)$ is the minimum radius of curvature of geodesics in $\man$.

\roc*
\textit{Proof.} Note that the ambient curvature $k$ of a path $\gamma$ through $\mathbb{R}^D$ can be written as $k^2 = k_g^2 + k_n^2$, where $k_g$ denotes the geodesic curvature and $k_n$ denotes the normal curvature. Paths that are geodesic in some submanifold $\man$ necessarily have $0$ geodesic curvature with respect to $\man$; thus $k = k_n$ for such curves.

Now consider a length-parameterized geodesic path $\gamma_{\tub}: [a,b] \rightarrow \tub_{\tau}\man$. Since $\gamma_{\tub}$ is a geodesic of $\tub_{\tau}\man$, we know that $k(t) = k_n(t)$ for all $t \in [a,b]$. Now let's consider two cases:
\begin{enumerate}
    \item $\gamma_{\tub}(t)$ is at distance less than $\tau$ from $\man$. In this case, the $\gamma_{\tub}(t)$ does not intersect with the boundary of $\tub_{\tau}\man$; it follows that no directions normal to $\tub_{\tau}\man$ exist at this point, and the normal acceleration $k_n(t)$ must be $0$. Therefore, $k(t) = 0$. This formalizes an intuitive concept - geodesics through $\tub_{\tau}\man$ are necessarily straight lines if they do not lie on the boundary of $\tub_{\tau}\man$.
    \item $\gamma_{\tub}(t)$ is at distance exactly equal to $\tau$ from $\man$. In this case, there exists a single normal direction to $\tub_{\tau}\man$ at $\gamma_{\tub}(t)$. It is simply the direction from $\gamma_{\tub}(t)$ to the nearest point on $\man$ (up to sign). Therefore, the only situation in which $\gamma_{\tub}$ has nonzero curvature is when it lies exactly on the boundary of $\tub_{\tau}\man$; the curvature is simply the norm of $\ddot{\gamma}_{\tub}(t)$, which is some vector necessarily normal to the boundary of $\tub_{\tau}\man$ at $\gamma_{\tub}(t)$.
\end{enumerate}
It follows that bounding the radius of curvature of geodesics through $\tub_{\tau}\man$ can be accomplished by considering geodesic paths restricted to the boundary of $\tub_{\tau}\man$, as all other geodesics through $\tub_{\tau}\man$ have no curvature (and thus infinite radius of curvature).

Now redefine $\gamma_{\tub}$ to be some geodesic segment that lies entirely on the surface of $\tub_{\tau}\man$ with nonzero curvature; suppose this segment starts at $\gamma_{\tub}(t_1)$ and ends at $\gamma_{\tub}(t_2)$. Choose $n$ intermediate and \textit{overlapping} time intervals $\{I_i\}_{i=1}^n$, $I_i = [a_i^1, a_i^2]$ where $a_i^1 < a_i^2$, $a_{i+1}^1 < a_i^2 < a_{i+1}^2$ and $a_0^1 = t_1$, $a_{n}^2 = t_2$. Observe that $\bigcup_{i=1}^n I_i = [t_1, t_2]$, so the set of interval spans $[t_1, t_2]$. Note that we choose for these intervals to be overlapping so we can avoid the case where curvature at the endpoints of sub-intervals is unaccounted for.

Now we will analyze a single sub-segment of $\gamma_{\tub}$ defined by the image of $I_j = [a_j^1, a_j^2]$ under the map $\gamma_{\tub}$. We encourage the reader to refer to \Cref{fig: r_0(m)} for the remainder of the proof. As previously established, $\ddot{\gamma}_{\tub}(t)$ is necessarily parallel to the vector from $\proj_{\man}\gamma_{\tub}(t)$ to $\gamma_{\tub}(t)$. Consider now the plane spanned by the vectors $\ddot{\gamma}_{\tub}(t)$ and $\dot{\gamma}_{\tub}(t)$. Now consider the osculating circle $O$ approximation of $\gamma_{\tub}$ near $\gamma_{\tub}(t)$ for some $t \in I_j$. Since $I_j$ can be made arbitrarily small, $O$ is an arbitrarily good approximation of $\gamma_{\tub}(t)$ for $t \in I_j$. Suppose $O$ has some radius $r$. 

\begin{figure}[H]
    \centering
    \includegraphics[width=0.5\textwidth]{figures/diagrams/lemmas/r_0_m.pdf}
    \caption{A diagram depicting $\gamma_{\tub}$, $\proj_{\man}\gamma_{\tub}$, $O$ and $O'$.}
    \label{fig: r_0(m)}
\end{figure}

Finally, consider the path in $\man$ defined by the image of $\gamma_{\tub}(t)$ for $t \in I_j$ under the map $\proj_{\man}\gamma_{\tub}(t)$; colloquially this path is the projection of the subsegment of $\gamma_{\tub}$ onto $\man$. Given that the osculating plane contains the vector $\ddot{\gamma}_{\tub}(t)$ locally (for $t \in I_j$), and we have already established that $\ddot{\gamma}_{\tub}(t)$ is parallel to the residual of the projection ($\proj_{\man}\gamma_{\tub}(t) - \gamma_{\tub}(t)$) then this projected path must also lie in the plane spanned by the vectors $\ddot{\gamma}_{\tub}(t)$ and $\dot{\gamma}_{\tub}(t)$ for $t \in I_j$. Since we are considering the case where $\gamma_{\tub}(t)$ is at distance exactly equal to $\tau$ from $\man$ for all $t$, this projected path is then approximated with its own osculating circle $O'$ lying in this plane with radius $r + \tau$, sharing the same center as $O$. 

Since the projected path is approximated by $O'$, its acceleration vector in a neighborhood near $t$ must be parallel to $\ddot{\gamma}_{\tub}(t)$; this implies that it is entirely orthogonal to $\man$, making the path geodesic in $\man$. Since it is geodesic in $\man$, the radius of $O'$ for all segments of all possible geodesics $\gamma_{\tub}$ is no smaller than $r_0(\man)$. Solving for the minimum possible radius of $O$ yields $r_0(\man) - \tau$.  

We will quickly show that there always exists a geodesic segment in the tubular neighborhood such that  $O'$ as defined above \textit{achieves} this minimum radius $r_0(\man)$. Pick some geodesic segment in $\man$ called $\gamma_{\man}$ with a constant nonzero acceleration $\|\ddot{\gamma}_{\man}\|_2 = 1/r_0(\man)$. Note that $\gamma_{\man}$ can be made infinitesimally small such that the constant acceleration assumption is arbitrarily accurate. Also note that $\ddot{\gamma}_{\man}$ is necessarily oriented \textit{normal} to $\man$, as $\gamma_{\man}$ is a geodesic of $\man$. Define another segment as follows,
\begin{equation}\label{eq: manifold to tub geodesic}
    \gamma_{\tub}(t) = \gamma_{\man}(t) + \tau \frac{\ddot{\gamma}_{\man}(t)}{\|\ddot{\gamma}_{\man}(t)\|_2}
\end{equation}
where the domain of $\gamma_{\tub}(t)$ is the domain of $\gamma_{\man}(t)$. Observe that this segment necessarily lies on the boundary of the tubular neighborhood as it was displaced exactly $\tau$ from $\man$ in the direction $\ddot{\gamma}_{\man}(t)$, which lies normal to $\man$. Also observe that we can approximate $\gamma_{\man}(t)$ with its osculating circle $O'$ arbitrarily well, where $O'$ has a radius $r_0(\man)$. Since $\ddot{\gamma}_{\man}(t)$ and $\gamma_{\man}(t)$ lie in the osculating plane, $\gamma_{\man}(t)$ must as well (as we have defined it to be a linear combination of these two vectors). In fact, $\gamma_{\tub}(t)$ is approximated arbitrarily well by $O$, its osculating circle centered at the center of $O'$. This very much mirrors the scenario that we posed earlier in the proof, visualized in \Cref{fig: r_0(m)}.

Since $O$ and $O'$ lie in the same plane centered about the same point, $\ddot{\gamma}_{\man}(t)$ and $\ddot{\gamma}_{\tub}(t)$ must be parallel. Since $\ddot{\gamma}_{\man}(t)$ lies normal to $\man$, $\ddot{\gamma}_{\tub}(t)$ must as well. By construction of $\gamma_{\tub}(t)$, $\ddot{\gamma}_{\man}(t)$ must be parallel to the residual of the projection of $\gamma_{\tub}(t)$ onto $\man$; this follows from the uniqueness of $\proj_{\man}$ stemming from the assumptions that $\tau < r_0(\man)$ and $2\tau <  s_0(\man)$ (detailed in assumptions \ref{assumption: ep bound} and \ref{assumption: tau bound}). This residual is the unique direction normal to the tubular neighborhood at $\gamma_{\tub}(t)$, and we have just established that $\ddot{\gamma}_{\man}(t)$ (and thus $\ddot{\gamma}_{\tub}(t)$) is parallel to it. It follows that $\gamma_{\tub}(t)$ is a geodesic segment of $\tub_{\tau}\man$, as its acceleration vector lies completely normal to $\tub_{\tau}\man$. Its radius of curvature, $r_0(\man) - \tau$, can be deduced from the difference in radii of $O$ and $O'$.

We can conclude that $r$, the radius of curvature of any geodesic path in the tubular neighborhood, always achieves a minimum at $r = r_0(\man) - \tau$. 

\qed{}

Now we will move on to showing that the ORC (as we have defined it in \Cref{sec: orc definition}) of any edge in an $\epsilon$-weighted graph is necessarily restricted to the finite interval $[-2, 1]$.
\uworc*
\textit{Proof.} Observe that, under the current construction, the $\epsilon$-weighted graph distance between a node $a \in \mathcal{N}(x)$ and 
$b \in \mathcal{N}(y)$ is bounded above and below,
\[0 \leq d_G(a,b) \leq 3\epsilon. \]

This implies the same bound on the Wasserstein distance between the measures $\mu_x$ and $\mu_y$. This is clear when we rewrite the $1$-Wasserstein distance as follows,
\[W(\mu_x, \mu_y) = \inf_{\gamma \in \Pi(\mu_x, \mu_y)}\mathbb{E}_{a,b \sim \gamma}[d_G(a,b)]\]
where $\Pi(\mu_x, \mu_y)$ denotes the set of all measures on $V \times V$ with marginals $\mu_x$ and $\mu_y$. Thus,
\[0 \leq W(\mu_x, \mu_y) \leq 3\epsilon\,, \]
and because $\kappa(x,y) = 1 - W(\mu_x, \mu_y)/\epsilon$, we have
\[-2 \leq \kappa(x,y) \leq 1. \]
\qed{}

Now we will prove a bound on geodesic distances through the tubular neighborhood as a function of manifold geodesic distances. This proposition is used in \Cref{thm: graph distance} to bound graph distances of shortcut edges in ORC thresholded graphs. 
\begin{prop}\label{lem: ratio}
    Let $d_{\tub}(x,y)$ be the geodesic distance induced by the Euclidean metric from $x \in \tub_{\tau}(\man)$ to $y \in \tub_{\tau}(\man)$. Then,
    \[\frac{d_{\tub}(x,y)}{d_{\man}\bigl(\proj_{\man}x, \proj_{\man}y\bigr)} \geq \frac{r_0(\man) - \tau}{r_0(\man)}.\]
\end{prop}
\textit{Proof.} Let $\gamma_{\tub}$ be the geodesic path through $\tub_{\tau}\man$ from $x$ to $y$. Select $P$ points $\{p_i\}_{i=1}^P$ (a method for which will be described soon) along $\gamma_{\tub}$ and join the projection of successive points $p_i$, $p_{i+1}$ onto $\man$ by a segment  $\gamma_{\proj}^{i, i+1}$ with curvature $r_0(\man)$. Let's denote the segment of $\gamma_{\tub}$ between $p_i$, $p_{i+1}$ as $\gamma_{\tub}^{i, i+1}$. Also suppose $P$ is large enough such that the geodesic segment through $\man$ connecting the projections of $p_i$ and $p_{i+1}$ can be arbitrarily well approximated by its osculating circle $O_{i, i+1}$. Observe that since $\man$ is smooth and we have required $\tau < s_0(\man)/2$ and $\tau < r_0(\man)$ in assumptions \ref{assumption: tau bound}, we have a unique projection. It follows that $\proj_{\man}(x)$ $\forall x \in \tub_{\tau}\man$ is continuous.
\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\textwidth]{figures/diagrams/lemmas/osculating_circle.pdf}
    \caption{A diagram depicting $p_i$, $p_{i+1}$ and various related quantities.}
    \label{fig: osculating circle}
\end{figure}
Note that
\[d_{\tub}(x,y) = L(\gamma_{\tub}) = \sum_{i = 1}^{P-1}L(\gamma_{\tub}^{i, i+1})\]
and 
\[d_{\man}(\proj_{\man}x, \proj_{\man}y) \leq  \sum_{i = 1}^{P-1}d_{\man}(\proj_{\man} p_i, \proj_{\man}p_{i+1}) \leq  \sum_{i = 1}^{P-1}L(\gamma_{\proj}^{i, i+1}).\]

The second inequality in the second statement requires explanation; observe that, since $\proj_{\man}(\cdot)$ is continuous one can choose a $T$ such that for all $\Delta t < T$

\[\|\proj_{\man}\gamma_{\tub}(t+\Delta t) - \proj_{\man}\gamma_{\tub}(t)\|_2 < s_0(\man)\]

for all $t \in \text{dom}(\gamma_{\tub})$. This gives us a principled way of choosing $\{p_i\}_{i=1}^P$, where $p_i = \gamma_{\tub}(t_i)$, $t_i = \sum_{j=1}^{i-1}(\Delta t)_j$. From the definition of minimum branch separation, we know that $\|\proj_{\man} p_{i+1} - \proj_{\man} p_i\|_2 < s_0(\man) \implies d_{\man}(\proj_{\man} p_i, \proj_{\man}p_{i+1}) \leq \pi r_0(\man)$. Now we will apply Lemma 3 from \citet{bernsteingeodesic} to say 
\begin{align}
    d_{\man}(\proj_{\man} p_i, \proj_{\man}p_{i+1}) &\leq 2r_0(\man)\arcsin\biggl(\frac{\|\proj_{\man} p_{i+1} - \proj_{\man}p_{i}\|_2}{2r_0(\man)}\biggr) \\
    &= L(\gamma_{\proj}^{i, i+1}).
\end{align}
The second equality follows from the way we have defined $L(\gamma_{\proj}^{i, i+1})$: an arc with a constant radius of curvature $r_0(\man)$ from $\proj_{\man} p_{i}$ to $\proj_{\man}p_{i+1}$. Application of some trigonometry yields the arc length.

Now consider a single segment defined by $p_i$ and $p_{i+1}$. Since we assume $\gamma_{\proj}^{i, i+1}$ has curvature $r_0(\man)$, it is approximated exactly by its osculating circle with radius $r_0(\man)$. Let $\gamma_{\min}^{i,i+1}$ be the straight-line path between the points at distance $r_0(\man) - \tau$ from the center of this osculating circle in the directions of $\proj_{\man}p_i$ and $\proj_{\man}p_{i+1}$ respectively. A diagram is shown in Figure \ref{fig: osculating circle} for clarity.

Observe that the length $l_{\min}^{i, i+1} = L(\gamma_{\min}^{i, i+1})$ must be no larger than the length of any straight-line path connecting any $a \in \tub_{\tau}\man$ and $b \in \tub_{\tau}\man$ such that they project to $\proj_{\man}p_i$ and $\proj_{\man}p_{i+1}$ respectively. In understanding this, it helps to note that the set of points $a$ could lie in is a $D-m$ (where $m$ is the dimension of $\man$) dimensional space created by intersecting the tubular neighborhood with the hyperplane that contains $p_i$ and the center of the osculating circle $O_{i, i+1}$ (defined earlier in the proof) and spans all manifold normal directions at $p_i$. The set of points $b$ could lie in has a similar form; just replace $p_i$ with $p_{i+1}$. The only directions from $p_i$ and $p_{i+1}$ (restricted to the described subspaces) that bring the points closer is the direction towards the center of the osculating circle $O_{i, i+1}$. Starting at $p_i$ and $p_{i+1}$ and travelling in these respective directions until you hit the boundary of the tubular neighborhood will minimize the distance. This minimum distance bounds $L(\gamma_{\tub}^{i, i+1})$, and we can compute it as follows,
\begin{align}
    L(\gamma_{\tub}^{i, i+1}) &\geq \|a - b\|_2 \\
    &= \frac{r-\tau}{r}\|\proj_{\man}p_i - \proj_{\man}p_{i+1}\|_2
\end{align}
where $r$ is the radius of $O_{i, i+1}$. Since $(x-a)/x$ is increasing for positive $x$ and $a$, we have
\begin{align}
    L(\gamma_{\tub}^{i, i+1}) &\geq \frac{r_0(\man)-\tau}{r_0(\man)}\|\proj_{\man}p_i - \proj_{\man}p_{i+1}\|_2 \\
    &= l_{\min}^{i, i+1}.
\end{align}
since $r \leq r_0(\man)$. Thus, we know that $L(\gamma_{\tub}^{i, i+1}) \geq l_{\min}^{i, i+1}$. Also note that $l_{\min}^{i, i+1}$ can be written as a function of $L(\gamma_{\proj}^{i, i+1})$ as follows: compute $\theta$, the angle swept out by $\gamma_{\proj}^{i, i+1}$, $\theta = L(\gamma_{\proj}^{i, i+1})/r_0(\man)$. Then observe that $l_{\min}^{i, i+1} = 2(r_0(\man) - \tau)\sin(\theta/2) = 2(r_0(\man) - \tau)\sin(L(\gamma_{\proj}^{i, i+1})/2r_0(\man))$. Finally, note that $\sin(x) \approx x$ for small $x$ which is a reasonable approximation for large $P$. Note that $P$ can be made arbitrarily large as segments can be divided in half without shattering the requirement that $\|\proj_{\man}p_{i+1} - \proj_{\man}p_{i}\|_2 < s_0(\man)$. Thus, $l_{\min}^{i, i+1} \approx 2(r_0(\man) - \tau)L(\gamma_{\proj}^{i, i+1})/2r_0(\man) = \frac{r_0(\man) - \tau}{r_0(\man)}L(\gamma_{\proj}^{i, i+1})$. Putting it all together, 
\begin{align*}
    d_{\tub}(x,y) &= \sum_{i = 1}^{P-1}L(\gamma_{\tub}^{i, i+1}) \\
    & \geq \sum_{i = 1}^{P-1}l_{\min}^{i, i+1} \\
    & \approx \frac{r_0(\man) - \tau}{r_0(\man)}\sum_{i = 1}^{P-1}L(\gamma_{\proj}^{i, i+1})\\
    & \geq \frac{r_0(\man) - \tau}{r_0(\man)}\sum_{i = 1}^{P-1}d_{\man}(\proj_{\man} p_i, \proj_{\man}p_{i+1}) \\
    & \geq \frac{r_0(\man) - \tau}{r_0(\man)}d_{\man}(\proj_{\man}x, \proj_{\man}y).
\end{align*}
\qed{}

Now we will bound the measure of an arbitrary $D$-dimensional ball centered at a point in the tubular neighborhood, a result which will be used in \Cref{thm: good orc}.
\begin{prop}\label{lem: delta ball}
    Suppose $\rho$ is the probability density function defined in \ref{eq: pdf} for a manifold $\man$ embedded in $\mathbb{R}^D$. Then for $r_0(\man) \gg \delta$
    \begin{equation} \label{eq: delta-ball prob}
        \mathbb{P}_{z \sim \rho}\Bigl[\|z-x\|_2 \leq \delta \Bigr] \geq \ddfrac{\delta^D\vol\bigl(B_1(0)\bigr)}{2Z} \cdot e^{-\frac{\tau^2}{2\sigma^2}}.
    \end{equation}
\end{prop}
\textit{Proof.} We can rewrite the left-hand side of \ref{eq: delta-ball prob} as
\begin{align*}
    \mathbb{P}_{z \sim \rho}\Bigl[\|z-x\|_2 \leq \delta \Bigr] &= \mu\Bigl[\bigl\{z \, \big| \, \|z-x\|_2 \leq \delta\bigr\}\Bigr] \\
    &\geq \frac{1}{2}\vol\bigl(B_{\delta}(0)\bigr) \cdot \min_{\|z-x\|_2 \leq \delta, \, z \in \tub_{\tau}\man}\rho(z)\\
    &= \frac{1}{2}\delta^D\vol\bigl(B_1(0)\bigr) \cdot \min_{\|z-x\|_2 \leq \delta, \, z \in \tub_{\tau}\man}\rho(z) \\
\end{align*}
The second line follows from the fact that a $\delta$-ball centered exactly on the surface of the tubular neighborhood $\tub_{\tau}\man$ is approximately cut it half; while curvature of $\man$ may slightly reduce this volume, considering $r_0(\man) \gg \delta$ makes this a reasonable approximation. Now it remains to bound the minimum probability density. We can do this by simply choosing the minimum value $\rho$ takes on in the tubular neighborhood,
\begin{align}
    \min_{z \in \tub_{\tau}\man}\rho(z) &= \frac{1}{Z}e^{-\frac{\tau^2}{2\sigma^2}}\label{eq: delta ball: min measure}
\end{align}
Combining everything,
\begin{equation}
    \mathbb{P}_{z \sim \rho}\Bigl[\|z-x\|_2 \leq \delta \Bigr] \geq \ddfrac{\delta^D\vol\bigl(B_1(0)\bigr)}{2Z} \cdot e^{-\frac{\tau^2}{2\sigma^2}}.
\end{equation}
\qed{}

Finally, we will show that the probability that the neighborhoods of two points overlap completly approaches $1$ as the points converge to each other. This proposition is also used in \Cref{thm: good orc}. 
\begin{prop}\label{lem: probability intersection}
    Suppose $\{x_i\}_{i=1}^{\infty}$ and $\{y_i\}_{i=1}^{\infty}$ are sequences of points in a series of point clouds sampled i.i.d. according to the probability density function $\rho$ defined by \ref{eq: pdf}. Also suppose that $\lim_{i \rightarrow \infty}\|x_i - y_i\|_2 = 0$. Then 
    \[\lim_{i \rightarrow \infty} \mathbb{P}_{a \sim \rho}\Bigl[a \in \eball(x_i) \cap \eball(y_i) \, \Big| \, a \in \eball(x_i) \cup \eball(y_i)\Bigr] = 1.\]
\end{prop}

\textit{Proof.} Our proof will use a similar argument to that of Lemma \ref{lem: probability of safe region}. First we will rearrange to put the term of interest in a friendlier form,
\begin{align}
    \mathbb{P}_{a \sim \rho}\Bigl[a \in \eball(x) \cap \eball(y) \,  \Big| \, a \in \eball(x) &\cup \eball(y)\Bigr] \\
    &= \ddfrac{\mu\Bigl(\eball(x) \cap \eball(y)\Bigr)}{\mu\Bigl(\eball(x) \cup \eball(y)\Bigr)} \\
    &= \ddfrac{\mu\Bigl(\eball(x) \cap \eball(y)\Bigr)}{\mu\Bigl(\eball(x)\Bigr) + \mu\Bigl(\eball(y)\Bigr) - \mu\Bigl(\eball(x) \cap \eball(y)\Bigr)}. \label{eq: expression for measure of intersection}
\end{align}
Computing each of these terms involves integrating $\rho$ (defined by \ref{eq: pdf}) over the set of interest. We define $S_x = \eball(x)$, $S_y = \eball(y)$ and $S_{x,y} = \eball(x) \cap \eball(y)$. Evaluating the measures, we have 
\begin{align}
    \mu \bigl(\eball(x)\bigr) &= \bigintssss_{z \in S_x} \rho(z) dV \\
    &= \bigintssss_{\mathbb{R}^D} \rho(z) \cdot \chi_{S_x}(z) dV
\end{align}
and 
\begin{align}
    \mu \bigl(\eball(y)\bigr) &= \bigintssss_{z \in S_y} \rho(z) dV \\
    &= \bigintssss_{\mathbb{R}^D} \rho(z) \cdot \chi_{S_y}(z) dV
\end{align}
where $\chi_A(z)$ is an indicator function, defined as 
\[\chi_A(z) = \begin{cases}
    1 & \text{if } z \in A \\
    0 & \text{if } z \notin A
\end{cases}.\]
The measure of the intersection of the two epsilon balls can also be described with 
\begin{align}
    \mu \bigl(\eball(x) \cap \eball(y)\bigr) &= \bigintssss_{z \in S_{x,y}} \rho(z) dV \\
    &= \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi_{S_{x,y}}(z) dV. \label{eq: indicator integral intersection}
\end{align}
Now suppose we have two sequences, $\{x_i\}_{i=1}^{\infty}$ and $\{y_i\}_{i=1}^{\infty}$ where $\lim_{i \rightarrow \infty}x_i = x$, $\lim_{i \rightarrow \infty}y_i = y$, and $\lim_{i \rightarrow \infty} \|x_i - y_i\|_2 = 0$. Now define $S_{x,i} = \eball(x_i)$, $S_{y,i} = \eball(y_i)$ and $S_i = \eball(x_i) \cap \eball(y_i)$.

We will show that $\lim_{i \rightarrow \infty} \chi_{S_{x,i}}(z) = \lim_{i \rightarrow \infty} \chi_{S_{y,i}}(z)$ pointwise, from which it will follow that $\chi_{S_i}$ will converge to the same function pointwise. Define $\chi(z):= \lim_{i \rightarrow \infty} \chi_{S_{y,i}}(z)$. Now we'll show that $\lim_{i \rightarrow \infty} \chi_{S_{x,i}}(z) = \chi(z)$. This involves showing that for all $a \in \mathbb{R}^D$ we have $\lim_{i \rightarrow \infty} \chi_{S_{x,i}}(a) = \chi(a)$. Consider two cases:
\begin{itemize}
    \item $\chi(a) = 1$. Since $x_i \rightarrow x$ and $\|x_i - y_i\|_2 \rightarrow 0$, we have $x_i \rightarrow y$. Since $\chi(a) = 1$, we know that for sufficiently large $i$, $\|a - y_i\|_2 \leq \epsilon$, so it follows that $\|a-y\|_2 \leq \epsilon$. Since $x_i \rightarrow y$, it must be true that $\|a - x_i\|_2 \leq \epsilon$ for sufficiently large $i$. Thus for sufficiently large $i$, $\chi_{S_{x,i}}(a) = \chi(a) = 1$. 
    \item $\chi(a) = 0$. This implies $\|a - y_i\|_2 > \epsilon$ for sufficiently large $i$. Since $\|x_i - y_i\|_2 \rightarrow 0$ we must also have that $\|a - x_i\|_2 > \epsilon$ for sufficiently large $i$ as well. Thus for sufficiently large $i$ we have $\chi_{S_{x,i}}(a) = \chi(a) = 0$. 
\end{itemize}

Therefore $\lim_{i \rightarrow \infty} \chi_{S_{x,i}}(z) = \lim_{i \rightarrow \infty} \chi_{S_{y,i}}(z) = \chi(z)$. It then follows that the indicator function on intersection of the two epsilon balls (denoted $S_{x_i, y_i}$) must also converge pointwise to $\chi(z)$. Namely, $\lim_{i \rightarrow \infty}\chi_{S_{x_i, y_i}}(z) = \chi(z)$.   

Now we want to use these results to evaluate \ref{eq: expression for measure of intersection} in the limit. As we will show, the denominator converges to a nonzero value, and thus the limit can be taken into the numerator and denominator as follows,
\begin{align}
    &\lim_{i \rightarrow \infty} \mathbb{P}_{a \sim \rho}\Bigl[a \in \eball(x_i) \cap \eball(y_i) \, \Big| \, a \in \eball(x_i) \cup \eball(y_i)\Bigr] \\
    &\hspace{50mm}= \lim_{i \rightarrow \infty} \ddfrac{\mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr)}{\mu\bigl(\eball(x_i)\bigr) + \mu\bigl(\eball(y_i)\bigr) - \mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr)} \\
    &\hspace{50mm}= \ddfrac{\lim_{i \rightarrow \infty}\mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr)}{\lim_{i \rightarrow \infty} \biggl(\mu\bigl(\eball(x_i)\bigr) + \mu\bigl(\eball(y_i)\bigr) - \mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr)\biggr)}.
\end{align}
Let's consider the numerator first. Rewriting using \ref{eq: indicator integral intersection}, we have
\begin{equation*}
    \lim_{i \rightarrow \infty} \mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr) = \lim_{i \rightarrow \infty} \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi_{S_{x_i,y_i}}(z) dV.
\end{equation*}
Observe that $|\rho(z)\chi_{S_{x_i, y_i}}(z)| \leq \rho(z)$ for all $i$; $\rho(z)$ is integrable as it represents a probability density function over $\mathbb{R}^D$. Thus, we can invoke the dominated convergence theorem to pull the limit inside of the integral to obtain,
\begin{align*}
    \lim_{i \rightarrow \infty} \mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr) &= \bigintssss_{\mathbb{R}^D} \lim_{i \rightarrow \infty} \rho(z)\cdot \chi_{S_{x_i,y_i}}(z) dV \\
    &= \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV.
\end{align*}
Now let's evaluate $\mu(\eball(x_i))$ in the limit. We can invoke the dominated convergence theorem again for both to pull the limit inside of the integral as before,
\begin{align*}
    \lim_{i \rightarrow \infty} \mu\bigl(\eball(x_i) \bigr) &= \lim_{i \rightarrow \infty} \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi_{S_{x_i}}(z) dV \\
    &= \bigintssss_{\mathbb{R}^D} \lim_{i \rightarrow \infty} \rho(z)\cdot \chi_{S_{x_i}}(z) dV \\
    &= \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV.
\end{align*}
And finally the same steps can be taken to find that $\lim_{i \rightarrow \infty} \mu\bigl(\eball(y_i) \bigr) = \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV$. Stitching it all together, we have
\begin{align*}
    &\lim_{i \rightarrow \infty} \mathbb{P}_{a \sim \rho}\Bigl[a \in \eball(x_i) \cap \eball(y_i) \, \Big| \, a \in \eball(x_i) \cup \eball(y_i)\Bigr] \\
    &\hspace{30mm}= \ddfrac{\lim_{i \rightarrow \infty}\mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr)}{\lim_{i \rightarrow \infty} \biggl(\mu\bigl(\eball(x_i)\bigr) + \mu\bigl(\eball(y_i)\bigr) - \mu\bigl(\eball(x_i) \cap \eball(y_i)\bigr)\biggr)} \\
    &\hspace{30mm}= \ddfrac{\bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV}{\bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV + \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV - \bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV} \\
    &\hspace{30mm}= \ddfrac{\bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV}{\bigintssss_{\mathbb{R}^D} \rho(z)\cdot \chi(z) dV } \\
    &\hspace{30mm}= 1.
\end{align*}
\qed{}
