\title{Fast and Simple Densest Subgraph with Predictions}
\author{Thai Bui\thanks{tbui8182@sdsu.edu, San Diego State University. Supported by NSF Grant No. 2342527.} ,  Hoa T. Vu\thanks{hvu2@sdsu.edu, San Diego State University. Supported by NSF Grant No. 2342527.}}
