Exact algorithms for the densest subgraph problem exist using linear programming or maximum flow \cite{Charikar00, Goldberg84}. In theory, there are $O(m^{1+o(1)})$ time  algorithms for maximum flow \cite{ChenKLPGS22}; however, these algorithms are complicated with overhead factors that make them rather impractical. One can also approximate the densest subgraph up to a $1-\epsilon$ factor using the multiplicative weights method to solve the dual linear program followed by a clever rounding algorithm \cite{SuV20, BahmaniGM14, GhaffariLM19} which runs in $O(m\cdot 1/\epsilon^2 \cdot \log^2 n)$ time. The extra $1/\epsilon^2 \cdot \log^2 n$ factor can also be very expensive (e.g., $\epsilon = 0.05$ and $n = 10^6$ lead to a painful $\approx 76\times 10^3$  overhead). There is however a simple and practical greedy $1/2$-approximation that can be implemented in $O(m)$ time by Charikar \cite{Charikar00} (this is often referred to as the ``peeling'' algorithm); this algorithm keeps removing the node with the lowest degree from the graph and recording the densest subgraph in the process. 





\paragraph{Algorithmic Results.} In this work, we show that if we are provided with a large partial solution to the densest subgraph, then we have a simple linear time  algorithm that yields a good approximation.  More formally, we will prove the following result.

\begin{theorem}[Main result 1]\label{theorem:greedy-alg-for-simple-variant-of-dsp} 
    Consider the densest subgraph  $H^{\ast} \subseteq V$. Suppose we are given $S \subseteq V$ such that 
    \begin{enumerate}
        \item $|S \cap H^{\ast}| \geq (1- \epsilon)|H^{\ast}|$, and
        \item $|S \setminus H^{\ast}| \leq \epsilon|H^{\ast}|$
    \end{enumerate}
    , then there exists $O(m)$ time algorithm that finds a subgraph whose density is at least $(1- 3 \epsilon) \ds(H^{\ast})$. 
\end{theorem}

Intuitively, the two conditions say that the provided partial solution $S$ has most nodes in $H^{\ast}$ and few nodes outside $H^{\ast}$. Hereinafter, we will informally refer to $S$ as a $(1-\epsilon)$ partial solution to the densest subgraph $H^{\ast}$. Note that for small enough $\epsilon$, this result is better than the 1/2-approximation of Charikar's greedy algorithm \cite{Charikar00}.

We remark that our algorithm also works for the at-most-$k$ densest subgraph problem which asks to compute the densest subgraph whose number of nodes is at most $k$. This variant is NP-Hard and there is no known non-trivial polynomial time approximation \cite{AndersenC09, KhullerS09}.

We have similar a result for the directed densest subgraph problem.

\begin{theorem} [Main result 2] \label{theorem:greedy-alg-for-directed-variant-of-dsp}
Let $S_1^{\ast}, S_2^{\ast} \subseteq V$ be the solution to the directed densest subgraph problem. Suppose we are given $S_1, S_2 \subseteq V$ such that for $i=1,2$,
\begin{enumerate}
    \item $|S_i \cap S^{\ast}_i| \ge (1-\epsilon_i)|S_i^{\ast}|$; and
    \item  $|S_i \setminus S^{\ast}_i| \le \epsilon_i |S^{\ast}_i|$
\end{enumerate}
Then, with $\epsilon = \max\{\epsilon_1, \epsilon_2\}$, there exists a $O(m)$ time algorithm that finds a solution whose density is at least $(1-O(\epsilon))\ds(S_1^{\ast}, S_2^{\ast})$.

\end{theorem}

Additionally, if in Theorem \ref{theorem:greedy-alg-for-simple-variant-of-dsp} we replace the standard density measure with a different density function $g: 2^V \to \mathbb{R}$, defined by
\[
    g(S) =\frac{|E(S)|^2}{|S|}
\]
for $S \subseteq V$, then we also obtain a similar result. We note that this notion measures how close $S$ is to forming a large clique.

\begin{theorem} [Main result 2] \label{theorem:greedy-alg-for-simple-variant-of-dsp-different-density} 
    Consider the subgraph  $H^{\ast} \subseteq V$ such that $g(H^\ast)$ is maximized. Suppose we are given $S \subseteq V$ such that 
    \begin{enumerate}
        \item $|S \cap H^{\ast}| \geq (1- \epsilon)|H^{\ast}|$; and
        \item $|S \setminus H^{\ast}| \leq \epsilon|H^{\ast}|$
    \end{enumerate}
    where $0 < \epsilon \le 1/2$, then there exists $O(m)$ time algorithm that finds a subgraph whose density is at least $(1- 3 \sqrt{\epsilon})\cdot g(H^{\ast})$. 
\end{theorem}




\paragraph{Preliminaries.} For a subset of nodes $U \subseteq V$, let $E(U)$  denote the set of edges induced by $U$. For directed graphs, $E(S_1,S_2)$ denotes the set of edges $u \to v$ where $u \in S_1$ and $v \in S_2$. Here, $S_1$ and $S_2$ are not necessarily disjoint. Unless stated otherwise, $n$ and $m$ refer to the number of nodes and edges in the input graph respectively.

\paragraph{Paper organization.} In Section~\ref{sec:algorithms}, we provide formal descriptions and proofs of correctness for Theorems~\ref{theorem:greedy-alg-for-simple-variant-of-dsp}, \ref{theorem:greedy-alg-for-directed-variant-of-dsp}, and \ref{theorem:greedy-alg-for-simple-variant-of-dsp-different-density}. Section~\ref{sec:experiments} presents a simple experiment on the Twitch Ego Nets dataset.

\section{Algorithms}\label{sec:algorithms}
\subsection{Undirected Densest Subgraph}
This section demonstrates that, given a $1-\epsilon$ partial solution $S$  to the densest subgraph, we can compute a $1 - \epsilon$ approximation in linear time. We propose a simple algorithm that augments $S$ by selecting an additional $\frac{\epsilon}{1 - \epsilon}|S|$ nodes from outside $S$ that have the highest number of connections to nodes in $S$. See Algorithm~\ref{alg:1} for the formal algorithm. A high-level justification of the algorithm’s correctness is illustrated in Figure~\ref{fig:undirected}.

\begin{algorithm}[h] 
    \caption{Approximate Densest Subgraph with Prediction}
    \label{alg:1}
    \KwIn{Graph $G = (V, E)$, and a set $S \subseteq V$ satisfying properties of Theorem \ref{theorem:greedy-alg-for-simple-variant-of-dsp}}

    For $v \notin S$, let $t(v) = |\{u \in S:vu \in E \}|$ be the number of neighbors of $v$ in $S$. If $v \in S$, let $t(v)=0$.
    Let $U$ be the set of nodes outside $S$ of size $\frac{\epsilon}{1-\epsilon}|S|$ with highest $t$-values.

    \Return $S \cup U$\;
\end{algorithm}


