We first observe that the number of edges induced by the nodes of $H^{\ast}$ outside $S$ is small.
\begin{prop}\label{prop:size-of-S-bar}
    Let $H^{\ast}_1 = H^{\ast} \setminus S$. Then, $|E(H^{\ast}_1) | \le \epsilon |E(H^{\ast})|$.
    \begin{proof}
        Recall that $|H^{\ast}_1| \leq \epsilon |H|$ according to the first assumption on $S$. We have
        \begin{align*}
            \ds({H^{\ast}_1}) & \leq \ds(H^{\ast}) \\
            \frac{|E(H^{\ast}_1)|}{|H^{\ast}_1|} & \leq \frac{|E(H^{\ast})|}{|H^{\ast}|} \\
            |E(H^{\ast}_1)| & \leq \frac{|E(H^{\ast})|}{|H^{\ast}|} |{H^{\ast}_1}|  \leq \epsilon |E(H^{\ast})|. \qedhere
        \end{align*}     
    \end{proof}
\end{prop}


We now prove the first main result.

\begin{proof}[Proof of Theorem \ref{theorem:greedy-alg-for-simple-variant-of-dsp} ]
   Consider Algorithm \ref{alg:1}. If $v \notin S$, let $t(v) = |\{u \in S:vu \in E \}|$ be the number of neighbors of $v$ in $S$; otherwise, let $t(v) = 0$. We observe that 
   \begin{align*}
        |U| = \frac{\epsilon}{1-\epsilon}|S| \ge \frac{\epsilon}{1-\epsilon}(1-\epsilon)|H^\ast | = \epsilon |H^\ast| \ge |H^\ast \setminus S|.
   \end{align*}

    The first and second inequalities follow from the first  property of $S$. Note that we choose $U \subseteq V \setminus S$ in a way that maximizes the number of edges $|E(U,S)|$ among the sets whose size is at most $\frac{\epsilon}{1-\epsilon}|S|$. We also showed that $|U| \ge |H^\ast \setminus S|$.  Therefore,

    \begin{align*}
         E(H^{\ast} \cap S) \sqcup  E(H^{\ast} \setminus S, H^{\ast} \cap S) \sqcup E(H^{\ast} \setminus S) & = E(H^{\ast})  \\
        |E(H^{\ast} \cap S)| +  |E(H^{\ast} \setminus S, H^{\ast} \cap S| & = |E(H^{\ast})| - |E(H^{\ast} \setminus S)| \\
        |E(H^{\ast} \cap S)| +  |E(H^{\ast} \setminus  S, H^{\ast} \cap S| & \ge (1-\epsilon) |E(H^{\ast}) | \\
        \implies |E(H^{\ast} \cap S)|  + |E(H^{\ast} \setminus  S, S)| & \ge (1-\epsilon) |E(H^{\ast}) | \\
        \implies |E(S)|  + |E(U, S)| & \ge (1-\epsilon) |E(H^{\ast}) | \\
        \implies |E(S \cup U)| \ge (1-\epsilon) |E(H^{\ast}) | .
    \end{align*}
    The first inequality follows from Proposition \ref{prop:size-of-S-bar}. Hence, 
    \begin{align*}
        \ds(U \cup S) & \ge (1-\epsilon) \frac{ |E(H^{\ast})| }{|U \cup S|}.
    \end{align*}
    We also have that 
    \begin{align*}
        |U \cup S| & = \frac{\epsilon |S|}{1-\epsilon} + |S| \\
                    & \le  (1+\epsilon + \epsilon/(1-\epsilon)) |H^\ast|
    \end{align*}

    which implies  $\ds(U \cup S)  \ge (1-3\epsilon) \ds(H^\ast)$.

    It is relatively simple to implement this algorithm in $O(m + n)$ time by going through each edge $uv$ and if $u \notin S, v \in S$ (using a hash table to check for membership of $S$), we increment $t(u)$. Then, we can use linear time selection \footnote{In practice, sorting or randomized selection is more practical.} to find $U$, i.e., the top $\frac{\epsilon}{1-\epsilon}|S|$ nodes with highest $t$-values.
\end{proof}


\subsection{Directed Densest Subgraph}\label{section:dds-greedy-predictor} Recall that for directed densest subgraph, we are provided with $S_1, S_2 \subseteq V$ such that

\begin{enumerate}
    \item $|S_i \cap S^{\ast}_i| \ge (1-\epsilon_i)|S_i^{\ast}|$; and
    \item  $|S_i \setminus S^{\ast}_i| \le \epsilon_i |S^{\ast}_i|$
\end{enumerate}

We first start with the following proposition.
\begin{prop}\label{prop:bound-on-the-number-of-inbetween-edges}
    Let $S'_i=S^{\ast}_i \setminus S_i$ for $i=1,2$, then $
        |E(S'_1, S'_2)| \le \sqrt{\epsilon_1 \epsilon_2}  \cdot |E(S^\ast_1, S^\ast_2)|$. 

\end{prop}

\begin{proof}
    By the optimality of the pair $(S^{\ast}_1, S^{\ast}_2)$, we have $f(S'_1, S'_2)  \le f(S^{\ast}_1, S^{\ast}_2)$, which gives
\[
    |E(S'_1, S'_2)|  \le  \frac{|E(S_1^\ast,S_2^\ast)|}{\sqrt{|S_1^\ast||S_2^\ast|}} \cdot \sqrt{|S'_1||S'_2|} \le \sqrt{\epsilon_1 \epsilon_2} \cdot |E(S^\ast_1, S^\ast_2)|. \qedhere
\]
\end{proof}

For each $v \in V$, we define $w_{S_1}(v)$ and $w_{S_2}(v)$ as follows
\begin{align*}
    w_{S_1}(v) = 
    \begin{cases}
        0 & \text{  if $v \in S_1$  }\\
        |\{v \to u \in : u \in S_2\}| & \text{ otherwise }
    \end{cases} 
\end{align*}
and
\begin{align*}
    w_{S_2}(v) = 
    \begin{cases}
        0 & \text{  if $v \in S_2$  }\\
        |\{u \to v \in E: u \in S_1\}| & \text{ otherwise.}
    \end{cases}
\end{align*}


The algorithm below follows a greedy approach: it first selects $\frac{\epsilon_1}{1-\epsilon_1}|S_1|$ nodes with the highest $w_{S_1}$ values and $\frac{\epsilon_2}{1-\epsilon_2}|S_2|$ nodes with the highest $w_{S_2}$ values. These nodes are then added to $S_1$ and $S_2$, respectively, to produce the final output.

\begin{algorithm}[h] \label{alg:dds}
    \caption{Approximate Directed Densest Subgraph with Prediction}
    \label{alg:2}
    \KwIn{Graph $G = (V, E)$, initial sets $S_1, S_2 \subseteq V$ satisfying properties of Theorem  \ref{theorem:greedy-alg-for-simple-variant-of-dsp}}
    For each $v \in V(G)$, compute $w_{S_1}(v)$ and $w_{S_2}(v)$\;
    $U_1 \leftarrow $ $\frac{\epsilon_1}{1-\epsilon_1}|S_1|$ nodes with the highest $w_{S_1}$ values\;
    $U_2 \leftarrow$ $\frac{\epsilon_2}{1-\epsilon_2}|S_2|$ nodes with the highest $w_{S_2}$ values\;
    \Return $(S_1 \cup U_1, S_2 \cup U_2)$\;
\end{algorithm}



\begin{proof} [Proof of Theorem \ref{theorem:greedy-alg-for-directed-variant-of-dsp}]
Set $\overline{S}_i := S_i \cap S^{\ast}_i$ for each $i=1,2,$ we have the following decomposition of $E(S^{\ast}_1, S^\ast_2)$
\[
    E(S^\ast_1, S^\ast_2) = E(\overline{S}_1, \overline{S}_2) \sqcup E(\overline{S}_1, S'_2) \sqcup E(S'_1, \overline{S}_2) \sqcup E(S'_1, S'_2).
\]
The upper bound on $|E(S'_1, S'_2)|$ and the decomposition of $E(S^\ast_1, S^\ast_2)$ above imply
\[
    |E(\overline{S}_1, \overline{S}_2)| + |E(\overline{S}_1, S'_2)| + |E(S'_1, \overline{S}_2)| \ge (1-\sqrt{\epsilon_1 \epsilon_2})|E(S^\ast_1, S^\ast_2)|.
\]
Let $U_1, U_2$ be the sets of $\frac{\epsilon_1}{1-\epsilon_1} |S_1|$ and $\frac{\epsilon_2}{1-\epsilon_2} |S_2|$ nodes with the highest $w_{S_1}(\cdot)$ and $w_{S_2}(\cdot)$ values respectively. 


Observe that $|S_1| \ge |\overline{S}_1|$ and
\[
|U_2| = \frac{\epsilon_2}{1-\epsilon_2} |S_2| \ge \frac{1}{1-\epsilon_2} |S_2'| \ge |S_2'|
\] and since we choose $U_2$ greedily in terms of indegree from $S_1$, we deduce that $|E(S_1, U_2)|  \ge |E(\overline{S_1}, S'_2)|$. Using a similar argument, we also have $|E(U_1, S_2) \ge |E(S'_1, \overline{S}_2)|$. It is trivial that $|E(S_1, S_2)|  \ge |E(\overline{S}_1, \overline{S}_2)|$ as $\overline{S}_1 \subseteq S_1, \overline{S}_2 \subseteq S_2$.

The edges in the solution can be decomposed as $E(S_1 \cup U_1, S_2 \cup U_2) = E(S_1, S_2) \sqcup E(S_1, U_2) \sqcup E(U_1, S_2) \cup E(U_1, U_2)$. Therefore,
\begin{align*}
    |E(S_1 \cup U_1, S_2 \cup U_2| & \ge |E(\overline{S}_1, \overline{S}_1)| + |E(\overline{S}_1, S_2')| + |E(S_1', \overline{S}_2')| + 0 \\
    & \ge |E(S^\ast_1, S^\ast_2)| - |E(S'_1, S'_2)| \ge (1- \sqrt{\epsilon_1 \epsilon_2} ) |E(S^\ast_1, S^\ast_2)|.
\end{align*}

Note that for $\epsilon_i < 1/2$,
\[
|S_i \cup U_i| \le (1+\epsilon_i) |S^\ast_i| + \frac{\epsilon_1}{1-\epsilon_1} |S_1| \le (1+\epsilon_i) |S^\ast_i| + \frac{\epsilon_1}{1-\epsilon_1} |S^\ast_i| < (1+3\epsilon_i)|S^\ast_i|.
\]
Putting  these together, we conclude that
\[
    \ds(S_1 \cup U_1 , S_2 \cup U_2) \ge \frac{1-\sqrt{\epsilon_1 \epsilon_2}}{\sqrt{(1+3\epsilon_1 )(1+3\epsilon_2)}}\cdot \ds(S_1^\ast, S_2^\ast)= (1-O(\epsilon))\ds(S_1^\ast, S_2^\ast). 
\]
Similar to the previous result, it is trivial to implement this algorithm in $O(m + n \log n)$ time.
\end{proof}



\subsection{The Clique Notion of Density}
Throughout this section, let $S$ be as in the situation of theorem \ref{theorem:greedy-alg-for-simple-variant-of-dsp-different-density}.

\begin{proof}[Proof of theorem \ref{theorem:greedy-alg-for-simple-variant-of-dsp-different-density}]
    We first restrict our attention to the case where $S \subseteq H^{\ast}$, then we will show how this condition can be relaxed without significantly affecting the lower bound of the approximation. To this end, suppose that $S \subseteq H^\ast$ and let 
    \begin{align*}
        \begin{cases}
            \overline{S} & = H^\ast \setminus S\\
            A & = |E(S)|\\
            B & = |E(\overline{S})|\\
            C & = |E(S, \overline{S})|
        \end{cases}
    \end{align*}
    By a similar argument as in the proof of proposition \ref{prop:size-of-S-bar}, we deduce that $B \le \sqrt{\epsilon} |E(H^\ast)|$. For $v \in V$, let $t(v)$ be defined as in algorithm \ref{alg:1}. That is, if $v \notin S$, then $t(v)$ is the number of edges $vu$ in which $u \in S$; if $v \in S$, then $t(v)=0$.
    Then, let $\tilde{U} \subseteq V$ be a subset of $\epsilon|H^\ast|$ nodes with the highest $t$-value. We claim that 
    \[
        |E(S\cup \tilde{U})|^2 \ge (1-2\sqrt{\epsilon})|E(H^\ast)|^2. 
    \]
    Note that 
    \[
        |E(S \cup \tilde{U})| \ge |E(S)| + |E(S,\tilde{U})| \ge A + C
    \]
    where the last inequality follows from the way we choose $\tilde{U}$. Thus, it suffices to show
    \[
        (A+C)^2 \ge (1-2\sqrt{\epsilon})|E(H^\ast)|^2.
    \]
    To this end, we have
    \begin{align*}
        (A+C)^2 & = (A+B+C)^2 - B^2-2B(A+C)\\
        & = |E(H^\ast)|^2 - B(B+2A+2C)\\
        & \ge |E(H^\ast)|^2 -2B(A+B+C)\\
        & \ge (1-2\sqrt{\epsilon})\cdot |E(H^\ast)|^2
    \end{align*}
    where the last inequality follows from $B \le \sqrt{\epsilon}|E(H^\ast)|$ and $A+B+C =  |E(H^\ast)|$. Clearly, $|S \cup \tilde{U}| \le (1+\epsilon)|H^\ast|$ so we have
    \[
        g(S \cup \tilde{U}) \ge \frac{1-2\sqrt{\epsilon}}{1+\epsilon}\cdot g(H^\ast).
    \]

    If there are some nodes of $S$ not contained in $H^\ast$ (that is $S \not \subset H^\ast$), let $S^\ast = S \cap H^\ast$ and let $U \subseteq V$ be a subset of $\frac{\epsilon}{1-\epsilon}\cdot|S|$ nodes with the highest $t$-value. By following the same argument shown above,
    \[
        |E(S \cup U)|^2 \ge |E(S^\ast \cup S')|^2 \ge (1-2\sqrt{\epsilon})|E(H^\ast)|^2.
    \]
    On the other hand, $(1-\epsilon)|H^\ast| \le |S| \le (1+\epsilon)|H^\ast|$ by the definition of $S$ so we have
    \[
        |S \cup U| \le (1+\epsilon)|H^\ast| + \frac{\epsilon(1+\epsilon)}{1-\epsilon}\cdot |H^\ast| = \frac{1+\epsilon}{1-\epsilon}\cdot|H^\ast|.
    \]
    As such, when $0< \epsilon \le 1/2$, this gives
    \[
        g(S \cup S^\ast) \ge (1-O(\sqrt{\epsilon}))\cdot g(H^\ast).
    \]
    This completes the proof of theorem \ref{theorem:greedy-alg-for-simple-variant-of-dsp-different-density}.
\end{proof}



\section{Experiment} \label{sec:experiments}

We conduct an experiment to evaluate the effectiveness of our method. The dataset we use consists of ego-networks of Twitch users who participated in the partnership program in April 2018, as described in \cite{karateclub}. It contains over 127,000 graphs. Each node represents a user, and each edge represents a friendship. 

We restrict our experiment to graphs with at least 100 edges. Approximately 300 graphs are used to form the training data set. Since the nodes lack attributes, we follow a standard practice in graph learning and use local structural features. Specifically, each node is characterized by its degree, the average degree of its neighbors, and the total number of nodes in its graph. These features can be computed for all nodes in $O(m)$ time, which matches the linear time complexity of our algorithm. The label is 1 if a node belongs to the densest subgraph, and 0 otherwise.

To generate ground truth labels for nodes in the training graphs, we compute the exact densest subgraphs using Goldberg's max-flow-based algorithm, implemented by Tsourakakis \cite{tsourakakis_densest_subgraph_2025}. We use a random forest with 10 decision trees as the classifier.

In summary, each data point corresponds to a node, described by its degree, the average degree of its neighbors, and the total number of nodes in its graph. The label indicates whether the node belongs to the densest subgraph. An example densest subgraph is shown in Figure \ref{fig:ds-ex}.



