            F_{\hat{R}} = & 1- \frac{1}{\pi^{2M}} \iint_\mathbb{C} \cdots \iint_\mathbb{C}  \exp{\left\{ - \sum_{m=0}^{M-1} \left[ \lvert a_m^{({\rm D})}\rvert^2 + \lvert a_m^{({\rm SI})}\rvert ^2 \right]\right\}} \\ & \!\! \times \!\! \prod_{n=0}^{N-1} \frac{1}{2\beta_n^{({\rm D})}} \!\! \int_0^{+\infty} \!\!\!\! {Q_1 \!\! \left(\sqrt{\frac{\alpha_n^{({\rm SI})}}{\beta_n^{({\rm SI})}}},\sqrt{\frac{rz}{\beta_n^{({\rm SI})}}}\right)} \! \exp{\left(-\frac{\alpha_n^{({\rm D})}+z}{2\beta_n^{({\rm D})}}\right)I_0\left(\frac{\sqrt{\alpha_n^{({\rm D})}z}}{\beta_n^{({\rm D})}}\right)}dz da_0^{({\rm D})} da_0^{({\rm SI})}\cdots da_{M-1}^{({\rm D})} da_{M-1}^{({\rm SI})}
