\section{Proof of Theorem \ref{th:cdf_R}}\label{app:ProofTheo1}
From \eqref{Eq:hh}, we can derive that
\begin{equation}
    \frac{|h_n^{({\rm SI})}|^2}{|h_n^{({\rm D})}|^2} = \frac{\sigma_g \lambda_n|a_n^{({\rm SI})}|^2}{\sigma_g \lambda_n|a_n^{({\rm D})}|^2} = \frac{|a_n^{({\rm SI})}|^2}{|a_n^{({\rm D})}|^2}.
\end{equation}
For all $0\leq n <N$ and ${\rm Z} \in \{{\rm D},{\rm SI}\}$, it can be seen that $a_n^{({\rm Z})}$ are independent of each other, $|a_n^{({\rm Z})}| \sim {\rm Rayleigh}\left(1/\sqrt{2}\right)$, and $|a_n^{({\rm Z})}|^2 \sim {\rm Exponential}\left(1\right)$. The random variable in \eqref{Eq:RR_min} can be reformulated as 
\begin{equation}\label{Eq:RRR_min}
    R' = \min\left\{\frac{|a_0^{({\rm SI})}|^2}{|a_0^{({\rm D})}|^2},\cdots,\frac{|a_{N-1}^{({\rm SI})}|^2}{|a_{N-1}^{({\rm D})}|^2}\right\}. 
\end{equation}
Evidently, $\kappa_y E_{\rm SI} R'$, with $R'$ in \eqref{Eq:RRR_min}, can be interpreted as the average RSI power in an uncorrelated channel represented by
\begin{equation}\label{Eq:y_vector_uc}
    \tilde{\boldsymbol{y}} = \boldsymbol{a}^{({\rm D})}s_{\rm D} +\sqrt{\kappa_y} \boldsymbol{a}^{({\rm SI})}\Psi (s_{\rm SI}) + \tilde{\boldsymbol{\eta}}.
\end{equation}
This uncorrelated channel can additionally be regarded as a special case of that in \eqref{Eq:y_vector}, applicable when ports are sufficiently distanced such that the channel gains across different ports are uncorrelated. Therefore, the CDF of $R'$ serves as an upper bound for that of $R$, such that $\overline{P}_{lb} = \kappa_y E_{\rm SI} \mathbb{E}\{R'\}$ is the lower bound for $\overline{P} = \kappa_y E_{\rm SI} \mathbb{E}\{R\}$.

The CDF of $R'$ can be calculated as
\begin{align}
F_{R'}(r) & = {\rm Pr}\left\{\min\left\{\frac{|a_0^{({\rm SI})}|^2}{|a_0^{({\rm D})}|^2},\cdots,\frac{|a_{N-1}^{({\rm SI})}|^2}{|a_{N-1}^{({\rm D})}|^2}\right\} \leq r\right\}\notag\\ 
& = 1- {\rm Pr}\left\{\frac{|a_0^{({\rm SI})}|^2}{|a_0^{({\rm D})}|^2} > r, \dots, \frac{|a_{N-1}^{({\rm SI})}|^2}{|a_{N-1}^{({\rm D})}|^2} > r \right\}\notag\\ 
& = 1 - \left(1-{\rm Pr}\left\{\frac{\hat{X}}{X} \leq r \right\} \right)^N,\label{Eq:CDFRR_min_proof}
\end{align}
where $\hat{X}$, $X\sim {\rm Exponential}(1)$ and they are independent. Hence, the CDF of $\hat{X}/X$ can be derived as 
\begin{align}
{\rm Pr}\left\{\frac{\hat{X}}{X} \leq r \right\} & \hspace{.5mm}= {\rm Pr} \left\{\hat{X}<rX \right\}\notag\\ 
& \hspace{.5mm}= \int_0^{+\infty} {F_{\hat{X}}\left(rx\right) f_X\left(x\right)}dx \notag\\ 
& \overset{(a)}{=} \int_0^{+\infty} (1-\exp(-rx))\exp(-x)dx\notag\\ 
& \hspace{.5mm}= 1-\frac{1}{r+1},\label{Eq:ExpDivExp}
\end{align}
where $(a)$ uses the CDF and PDF of exponential distribution for $\hat{X}$ and $X$. By substituting \eqref{Eq:ExpDivExp} into \eqref{Eq:CDFRR_min_proof}, we have \eqref{Eq:ubCDFRR}.

The expectation of $R'$ can be calculated as
\begin{align}
\mathbb{E}\left\{ R' \right\} & = \int_0^{+\infty} {\left[1-F_{R'}(r)\right]} dr\notag\\ 
& = \int_0^{+\infty} {\left(\frac{1}{r+1}\right)^N} dr\notag\\ 
& = \frac{1}{N-1}.\label{Eq:expRR_min}
\end{align}
By substituting \eqref{Eq:expRR_min} into $\overline{P}_{lb} = \kappa_y E_{\rm SI} \mathbb{E}\{R'\}$, we obtain \eqref{Eq:lbaveP}.

\section{Proof of Theorem \ref{th:approx}}\label{app:ProofTheo2}
It is established from \eqref{Eq:g_fsapprox} that the approximated channel $\hat{g}^{({\rm Z})}_n$ adheres to a Gaussian distribution. Given a specific $\hat{\boldsymbol{a}}^{({\rm Z})} = [a_0^{({\rm Z})},\dots,a_{M-1}^{({\rm Z})}]^T$, we have
\begin{equation}
\hat{g}^{({\rm Z})}_n \sim \mathcal{CN} \left(\sigma_g \sum_{m=0}^{M-1} \sqrt{\lambda_m} \mu_{n,m} a_m^{({\rm Z})}, 2\beta_n^{({\rm Z})} \right),
\end{equation}
where $\beta_n^{({\rm Z})}$ is given in \eqref{Eq:alphabeta}. Consequently, $\lvert \hat{g}^{({\rm Z})}_n \rvert$ follows Rice distribution as
\begin{equation}
\lvert \hat{g}^{({\rm Z})}_n\rvert \sim {\rm Rice} \left( \sqrt{\alpha_n^{({\rm Z})}}, \sqrt{\beta_n^{({\rm Z})}} \right),
\end{equation}
where $\alpha_n^{({\rm Z})}$ and $\beta_n^{({\rm Z})}$ are given in \eqref{Eq:alphabeta}. We now consider the random variable of $\lvert \hat{g}^{({\rm Z})}_n \rvert ^2$ conditioned on $\hat{\boldsymbol{a}}^{({\rm Z})}$. This variable follows a non-central Chi-square distribution, with CDF and PDF expressed, respectively, as 
\begin{equation}
F_{\lvert \hat{g}^{({\rm Z})}_n\rvert^2 | \hat{\boldsymbol{a}}^{({\rm Z})}}(r) = 1-Q_1\left(\sqrt{\frac{\alpha_n^{({\rm Z})}}{\beta_n^{({\rm Z})}}},\sqrt{\frac{r}{\beta_n^{({\rm Z})}}}\right),
\end{equation}
and
\begin{equation}
f_{\lvert \hat{g}^{({\rm Z})}_n\rvert^2 | \hat{\boldsymbol{a}}^{({\rm Z})}}\!(r) = \frac{1}{2\beta_n^{({\rm Z})}} \!\! \exp\!\!{\left(\!\!-\frac{\alpha_n^{({\rm Z})}+r}{2\beta_n^{({\rm Z})}}\!\right)\!\! I_0\!\!\left(\!\!\frac{\sqrt{\alpha_n^{({\rm Z})}r}}{\beta_n^{({\rm Z})}}\right)}.
\end{equation}
Note that $\lvert \hat{g}^{({\rm D})}_n\rvert^2$ and $\lvert \hat{g}^{({\rm SI})}_n\rvert^2$ are independent. Therefore, the random variable $\hat{R}_n = \lvert \hat{g}^{({\rm SI})}_n\rvert^2 / \lvert \hat{g}^{({\rm D})}_n\rvert^2$ conditioned on $(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})$ represents the ratio of these two independent random variables. Its CDF can then be derived as
\begin{align}
F_{\hat{R}_n}&_{|(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})}(r) \notag\\ 
= & \int_0^\infty F_{\lvert \hat{g}^{({\rm SI})}_n\rvert^2|\hat{\boldsymbol{a}}^{({\rm SI})}}(rz) f_{\lvert \hat{g}^{({\rm D})}_n\rvert^2|\hat{\boldsymbol{a}}^{({\rm D})}}(z) dz \notag\\ 
= & 1-\frac{1}{2\beta_n^{({\rm D})}} \int_0^{+\infty} {Q_1\left(\sqrt{\frac{\alpha_n^{({\rm SI})}}{\beta_n^{({\rm SI})}}},\sqrt{\frac{rz}{\beta_n^{({\rm SI})}}}\right)}\notag\\ 
& \quad\times \exp{\left(-\frac{\alpha_n^{({\rm D})}+z}{2\beta_n^{({\rm D})}}\right)I_0\left(\frac{\sqrt{\alpha_n^{({\rm D})}z}}{\beta_n^{({\rm D})}}\right)}dz.
\end{align}
For a specified pair $(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})$, the independent variables $b_n^{({\rm Z})}, \forall n \in \{0,\dots, N-1\}$ in \eqref{Eq:g_fsapprox} indicate that $\hat{R}_n$ are independent of each other. Consequently, the CDF of $\hat{R} = \min\{\hat{R}_0,\dots, \hat{R}_{N-1}\}$ can be calculated as
\begin{align}
F_{\hat{R}}& _{|(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})}(r) \notag\\ 
= & 1- \prod_{n=0}^{N-1}\left[1-F_{\hat{R}_n|(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})}(r)\right] \notag\\ 
= & 1- \prod_{n=0}^{N-1} \frac{1}{2\beta_n^{({\rm D})}} \int_0^{+\infty} {Q_1\left(\sqrt{\frac{\alpha_n^{({\rm SI})}}{\beta_n^{({\rm SI})}}},\sqrt{\frac{rz}{\beta_n^{({\rm SI})}}}\right)} \notag\\ 
& \quad\times \exp{\left(-\frac{\alpha_n^{({\rm D})}+z}{2\beta_n^{({\rm D})}}\right)I_0\left(\frac{\sqrt{\alpha_n^{({\rm D})}z}}{\beta_n^{({\rm D})}}\right)}dz.\label{Eq:conPDF_hatR}
\end{align}
As a result, the CDF of $\hat{R}$ can be considered as the expectation of \eqref{Eq:conPDF_hatR} over $(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})$, resulting in \eqref{Eq:CDF_fsapprox}.
Similarly, based on the CDF in \eqref{Eq:conPDF_hatR}, the expectation of $\hat{R}$ conditioned on $(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})$ is expressed as
\begin{align}
\mathbb{E} \{& \hat{R}| (\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})}) \} \notag\\ 
= & \int_{0}^{+\infty} 1- F_{\hat{R}| (\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})}(r) dr \notag\\ 
= & \int_{0}^{+\infty} \prod_{n=0}^{N-1} \frac{1}{2\beta_n^{({\rm D})}} \int_0^{+\infty} {Q_1\left(\sqrt{\frac{\alpha_n^{({\rm SI})}}{\beta_n^{({\rm SI})}}},\sqrt{\frac{rz}{\beta_n^{({\rm SI})}}}\right)} \notag\\ 
& \quad\times \exp{\left(-\frac{\alpha_n^{({\rm D})}+z}{2\beta_n^{({\rm D})}}\right)I_0\left(\frac{\sqrt{\alpha_n^{({\rm D})}z}}{\beta_n^{({\rm D})}}\right)}dzdr.\label{Eq:conExp_hatR}
\end{align}
Thus, the expectation of $\hat{R}$ can be obtained by the expectation of \eqref{Eq:conExp_hatR} over $(\hat{\boldsymbol{a}}^{({\rm D})},\hat{\boldsymbol{a}}^{({\rm SI})})$, leading to the result in \eqref{Eq:Exp_fsapprox}.

