Let $\ast$ be a lexicographic AGM revision function, and let $\dotminus$ be a moderate AGM contraction function. Suppose that $\ast$ assigns (via (R)) at $K_1$ a faithful preorder $\preceq_{K_1}^{\ast}$ over $\mathbb{M}$, such that

\begin{center}
$\underbrace{r_1}_{[K_1]} \quad \prec_{K_1}^{\ast}\quad r_2\quad \approx_{K_1}^{\ast}\quad r_3\quad \approx_{K_1}^{\ast}\quad r_4\quad \approx_{K_1}^{\ast}\quad r_5$.
\end{center}

\noindent Moreover, suppose that $\ast$ assigns (via (R)) at $K_2$ a faithful preorder $\preceq_{K_2}^{\ast}$, such that $\preceq_{K_2}^{\ast}\ =\ \preceq_{K_2}^{\dotminus}$. Finally, suppose that, for any \mbox{$i\in\{1,2\}$}, $\dotminus$ assigns (via (C)) at $K_i\ast\varphi_{1}^{i}$ a faithful preorder $\preceq_{K_i\ast\varphi_{1}^{i}}^{\dotminus}$ over $\mathbb{M}$, such that $\preceq_{K_i\ast\varphi_{1}^{i}}^{\dotminus}\ =\ \preceq_{K_i\ast\varphi_{1}^{i}}^{\ast}$.

Thereafter, we examine separately the two transitions $K_1$-to-$K_2$ and $K_2$-to-$K_3$.

\begin{itemize}
\item \underline{From $K_1$ to $K_2$} 

\noindent First, observe that $[K_1]\cap[K_2] = \varnothing$. Let $\varphi_{1}^{2}$, $\varphi_{2}^{2}$ be two sentences of $\mathbb{L}$ such that \mbox{$[\varphi_{1}^{1}] = [K_2] = \{r_4,r_5\}$} and let $[\neg\varphi_{2}^{1}]=\varnothing$ (i.e., $\varphi_{2}^{1} \equiv\top$). Then, we derive from condition (R) that $[K_1\ast\varphi_{1}^{1}] = \min([\varphi_{1}^{1}],\preceq_{K_1}^{\ast}) = [\varphi_{1}^{1}] = \{r_4,r_5\} = [K_2]$. Moreover, since $\ast$ is a lexicographic AGM revision function, it follows that the faithful preorder $\preceq_{K_1\ast\varphi_{1}^{1}}^{\ast}$ is such that

\begin{center}
$\underbrace{r_4\enspace \approx_{K_1\ast\varphi_{1}^{1}}^{\ast}\enspace r_5}_{[K_1\ast\varphi_{1}^{1}]} \quad \prec_{K_1\ast\varphi_{1}^{1}}^{\ast}\quad r_1\quad \prec_{K_1\ast\varphi_{1}^{1}}^{\ast}\quad r_2\quad \approx_{K_1\ast\varphi_{1}^{1}}^{\ast}\quad r_3$.
\end{center}

\noindent Given that $\preceq_{K_1\ast\varphi_{1}^{1}}^{\dotminus}\ =\ \preceq_{K_1\ast\varphi_{1}^{1}}^{\ast}$ (by the definition of $\ast$ and $\dotminus$), we derive from condition (C) that \mbox{$\big[\big(K_1\ast\varphi_{1}^{1}\big)\dotminus\varphi_{2}^{1}\big] =$} \mbox{$[K_1\ast\varphi_{1}^{1}] \cup \min([\neg\varphi_{2}^{1}],\preceq_{K_1\ast\varphi_{1}^{1}}^{\dotminus}) = [K_1\ast\varphi_{1}^{1}] = [K_2]$}. Therefore, \mbox{$K_{2} = \big(K_1\ast\varphi_{1}^{1}\big)\dotminus\varphi_{2}^{1}$}. Furthermore, since $\dotminus$ is a moderate AGM contraction function and $\varphi_{2}^{1} \equiv\top$ (i.e., $[\neg\varphi_{2}^{1}]=\varnothing$), it follows that $\preceq_{K_{2}}^{\dotminus}\ =\ \preceq_{K_1\ast\varphi_{1}^{1}}^{\dotminus}$; namely,

\begin{center}
$\underbrace{r_4\enspace \approx_{K_{2}}^{\dotminus}\enspace r_5}_{[K_2]} \quad \prec_{K_{2}}^{\dotminus}\quad r_1\quad \prec_{K_{2}}^{\dotminus}\quad r_2\quad \approx_{K_{2}}^{\dotminus}\quad r_3$.
\end{center}

\newpage

\item \underline{From $K_2$ to $K_3$} 

\noindent First, observe that $[K_2]\cap[K_3] \neq \varnothing$. Let $\varphi_{1}^{2}$, $\varphi_{2}^{2}$ be two sentences of $\mathbb{L}$ such that \mbox{$[\varphi_{1}^{2}] = [K_2]\cap[K_3] = \{r_4,r_5\}$} and \mbox{$[\neg\varphi_{2}^{2}] = [K_3]\setminus[K_2] = \{r_2,r_3\}$}. 

Given that $\preceq_{K_2}^{\ast}\ =\ \preceq_{K_2}^{\dotminus}$ (by the definition of $\ast$ and $\dotminus$), we derive from condition (R) that $[K_2\ast\varphi_{1}^{2}] = \min([\varphi_{1}^{2}],\preceq_{K_2}^{\ast}) = [K_2+\varphi_{1}^{2}] = [\varphi_{1}^{2}] = \{r_4,r_5\}$. Moreover, since $\ast$ is a lexicographic AGM revision function, it follows that the faithful preorder $\preceq_{K_2\ast\varphi_{1}^{2}}^{\ast}$ is such that

\begin{center}
$\underbrace{r_4\enspace \approx_{K_2\ast\varphi_{1}^{2}}^{\ast}\enspace r_5}_{[K_2\ast\varphi_{1}^{2}]} \quad \prec_{K_2\ast\varphi_{1}^{2}}^{\ast}\quad r_1\quad \prec_{K_2\ast\varphi_{1}^{2}}^{\ast}\quad r_2\quad \approx_{K_2\ast\varphi_{1}^{2}}^{\ast}\quad r_3$.
\end{center}

\noindent Next, since $\preceq_{K_2\ast\varphi_{1}^{2}}^{\dotminus}\ =\ \preceq_{K_2\ast\varphi_{1}^{2}}^{\ast}$ (by the definition of $\ast$ and $\dotminus$), we derive from condition (C) that \mbox{$\big[\big(K_2\ast\varphi_{1}^{2}\big)\dotminus\varphi_{2}^{2}\big] =$} \mbox{$[K_2\ast\varphi_{1}^{2}] \cup \min([\neg\varphi_{2}^{2}],\preceq_{K_2\ast\varphi_{1}^{2}}^{\dotminus}) = [K_2\ast\varphi_{1}^{2}] \cup [\neg\varphi_{2}^{2}] = \{r_2,r_3,r_4,r_5\} = [K_3]$}. Therefore, \mbox{$K_{3} = \big(K_2\ast\varphi_{1}^{2}\big)\dotminus\varphi_{2}^{2}$}.
\end{itemize}

Consequently, and as expected due to Theorem~\ref{thm_backprop_dp} (since condition (SD) holds), there exist a DP revision function $\ast$, a DP contraction function $\dotminus$, and two sentences $\varphi_{1}^{i},\varphi_{2}^{i}\in\mathbb{L}$, such that \mbox{$K_{i+1} = \big(K_i\ast\varphi_{1}^{i}\big)\dotminus\varphi_{2}^{i}$}, for any \mbox{$i\in\{1,2\}$}.
\end{example}


\section{Conclusion}

This article is a continuation of the research initiated in our earlier work \cite{aravanis25a}, where the foundational connection between belief-change theory and the training dynamics of binary Artificial Neural Networks (ANNs) was introduced. In that work, we proposed a symbolic framework in which the knowledge encoded by binary ANNs is represented via propositional logic, and the training process is interpreted as a sequence of belief-set transitions, modelled through full-meet belief change.

In the present study, we extended that framework by addressing key conceptual and technical limitations. First, we showed that Dalal's method for belief change \cite{dalal88} inherently enables a structured and gradual modification of belief sets, progressing through intermediate states of belief. More significantly, we replaced the restrictive full-meet operation with well-behaved belief-change operators ---namely, lexicographic revision \cite{nayak94,nayak03} and moderate contraction \cite{ramachandran12}--- that are consistent with the Darwiche-Pearl approach for iterated belief change \cite{darwiche97}. This refinement allows for a more expressive and robust modelling of the dynamics underlying binary ANN training.

Taken together, our results strengthen the theoretical foundations of symbolic reasoning in machine learning, and pave the way for future work that explores the interpretability, robustness, and epistemic characterization of ANN behaviour through the lens of formal logic and belief dynamics.

