\begin{algorithm}
\caption{Entity–Event KG Insertion (Pre-processing)}
\label{alg:insertion}
\begin{algorithmic}[1]
\Require
  document $D$;  
  entity, event extractor $g(\cdot)$;  

  text encoder   $f(\cdot)$;  
  top-$L$ chunk size $m$
\Ensure
  graphs \(\mathcal{G}_{\text{ent}},\mathcal{G}_{\text{evt}}\);  
  bipartite edge set \(\mathcal{B}\);  
  vector stores \(\mathcal{I}_{\mathrm{ent}},\mathcal{I}_{\mathrm{evt}}\)
%
\Procedure{InsertDocument}{$D$}
  %-----------------------------------------------------------
  \State \textbf{Step 1: chunking}
  \State $\{c_\ell\}_{\ell=1}^{L}\gets\textsc{Chunk}(D,m)$
  %-----------------------------------------------------------
  \State \textbf{Step 2: node extraction}
  \For{$\ell\gets1$ \textbf{to} $L$}
    \State $V_{\mathrm{ent}}^{(\ell)}, V_{\mathrm{evt}}^{(\ell)}\gets g(c_\ell)$
  \EndFor
  \State $V_{\mathrm{ent}}\gets\bigcup_\ell V_{\mathrm{ent}}^{(\ell)}$;\;
        $V_{\mathrm{evt}}\gets\bigcup_\ell V_{\mathrm{evt}}^{(\ell)}$
  %-----------------------------------------------------------
  \State \textbf{Step 3: build edge sets}
  \State $E_{\mathrm{ent}},E_{\mathrm{evt}}\gets
         \textsc{IntraChunkEdges}(\{c_\ell\},V_{\mathrm{ent}},V_{\mathrm{evt}})$
  \State $\mathcal{B}\gets\Call{BuildBipartite}{V_{\mathrm{ent}},V_{\mathrm{evt}}}$
  %-----------------------------------------------------------
  \State \textbf{Step 4: embed and index}
  \ForAll{$v\in V_{\mathrm{ent}}$}  \Comment{entities}
      \State $\mathcal{I}_{\mathrm{ent}}.\textsc{Add}\bigl(v,f(\textsc{Canon}(v))\bigr)$
  \EndFor
  \ForAll{$e\in V_{\mathrm{evt}}$}  \Comment{events}
      \State $\mathcal{I}_{\mathrm{evt}}.\textsc{Add}\bigl(e,f(\textsc{Canon}(e))\bigr)$
  \EndFor
  %-----------------------------------------------------------
  \State \Return \(\mathcal{G}_{\text{ent}}=(V_{\mathrm{ent}},E_{\mathrm{ent}}),
                  \;\mathcal{G}_{\text{evt}}=(V_{\mathrm{evt}},E_{\mathrm{evt}}),
                  \;\mathcal{B}\)
\EndProcedure
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\textsc{BuildBipartite}: connect entity mentions to events}
\label{alg:bipartite}
\begin{algorithmic}[1]
\Require
  entity nodes $V_{\mathrm{ent}}$,  
  event nodes  $V_{\mathrm{evt}}$
\Ensure
  bipartite edge set \(\mathcal{B}\)
%
\Function{BuildBipartite}{$V_{\mathrm{ent}},V_{\mathrm{evt}}$}
  \State $\mathcal{B}\gets\varnothing$
  \State \textit{/* surface-form string match inside the same chunk */}  
  \ForAll{$v\in V_{\mathrm{ent}}$}
    \State $c\gets\textsc{ChunkID}(v)$;\;
           $S\gets\textsc{Name}(v)$
    \ForAll{$e\in V_{\mathrm{evt}}\;\textbf{with}\;\textsc{ChunkID}(e)=c$}
        \If{$S\subset\textsc{Desc}(e)$}
            \State $\mathcal{B}\gets\mathcal{B}\cup\{(v,e)\}$
        \EndIf
    \EndFor
  \EndFor
  \State \Return $\mathcal{B}$
\EndFunction
\end{algorithmic}
\end{algorithm}

