\begin{algorithm}
\caption{Entity–Event KG \textsc{Retrieve} (Inference-time)}
\label{alg:retrieval}
\begin{algorithmic}[1]
\Require
  query $q$ (or hypothetical response transformed text),\\
  entity store $\mathcal{I}_{\mathrm{ent}}$, event store $\mathcal{I}_{\mathrm{evt}}$,\\
  bipartite edge set $\mathcal{B}$, similarity encoder $f(\cdot)$,\\
  entity, event extractor $g(\cdot)$,   top-$k$ parameter $k$
\Ensure
  ranked context bundle $C$ (passages $+$ linearised subgraph)
%
\Procedure{Retrieve}{$q$}
  %-----------------------------------------------------------
  \State \textbf{Cue extraction}
  \State $S_{\mathrm{ent}},S_{\mathrm{evt}}\gets g(q)$
  \State $V_q \gets \textsc{Lookup}(S_{\mathrm{ent}},\mathcal{I}_{\mathrm{ent}})
                 \cup
                 \textsc{Lookup}(S_{\mathrm{evt}},\mathcal{I}_{\mathrm{evt}})$
  %-----------------------------------------------------------
  \State \textbf{One-hop expansion across $\mathcal{B}$}
  \State $V_q^{+}\!\gets\!V_q
        \cup\{e\mid(v,e)\!\in\!\mathcal{B},\,v\!\in\!V_q\}
        \cup\{v\mid(v,e)\!\in\!\mathcal{B},\,e\!\in\!V_q\}$
  %-----------------------------------------------------------
  \State \textbf{Similarity ranking}
  \State $\mathcal{P}\gets\{\textsc{Chunk}(x)\mid x\in V_q^{+}\}$ \Comment{candidate passages}
  \State $\mathbf{z}\gets f(q)$
  \State $\text{scores}[p]\gets\langle f(p),\mathbf{z}\rangle\quad\forall p\in\mathcal{P}$
  \State $\mathcal{P}_k\gets\textsc{TopK}(\text{scores},k)$
  %-----------------------------------------------------------
  \State \textbf{Context assembly}
  \State $G_{\text{sub}}\gets
         (\,V_q^{+},\,
           (E_{\mathrm{ent}}\cup E_{\mathrm{evt}}\cup\mathcal{B})
           \cap (V_q^{+}\!\times\!V_q^{+})\,)$
  \State $C\gets\textsc{FormatContext}(\mathcal{P}_k,G_{\text{sub}})$
  \State \Return $C$
\EndProcedure
\end{algorithmic}
\end{algorithm}

