\begin{figure}
    \centering
    \includegraphics[width=1\linewidth]{images/figures/Ark_Tools.pdf}
    \caption{ Graphical debugging tools provided by Ark. Ark Graph displays active nodes and their communication channels for network analysis. Ark Viewer renders live image streams to support camera calibration and inspection. Ark Plot visualizes real-time numerical data on any channel, aiding in system monitoring and debugging.}
