	\begin{section}{Appendix}
		\begin{subsection}{Example \ref{ex:euclid}}

			We will show that if $C\seq \R^n$ is convex and
			$f\from C \to \R$ is convex and locally Lipschitz on $C$ then $f$ has a (Euclidean) subgradient at each point 
			 in $C$. 
			For any $x\in C$, if $f$ is locally 
			Lipschitz one can find $L, \delta > 0$ such that 
			$|f(y) - f(z)| \leq L \|y-z\|$ for all $y\in C \cap B_{\delta}(x) =: C'$.
			Define $g\from \R^n \to (-\infty,+\infty]$ as follows: 
			\[ g(y) = \begin{cases}
					f(y), & y\in C'\\
					+\infty, & \text{else}.
			\end{cases}\]
			Then set $h(y) = \inf_{z\in \R^n} \st{g(z) + L\|y-z\|}$. We claim that 
			$h$ is finite-valued, convex, and agrees with $f$ on $C'$. Clearly $h(y) < +\infty$ for any $y$ because
			$C'$ is nonempty, while $h(y) > -\infty$ because $C'$ is bounded and
			\[h(y) = \inf_{z\in C'} \st{f(z) + L\|y-z\|} \geq f(x) + L\inf_{z\in C'}\st{\|y-z\|-\|z-x\|} > -\infty.\]
			Thus $h$ is finite-valued, and convexity of $h$ follows by recognizing $h$ as the 
			infimal convolution of the convex function $g$ with the finite-valued convex function 
			$L\|\cdot\|$. Given $y\in C'$ we observe $h(y) \leq f(y)$ because $y$ is feasible for the infimum defining
			$h$, while on the other hand the $L$-Lipschitz property for $f$ on $C'$ implies 
			\[f(z) + L\|y-z\| \geq f(y) \text{ for all } z\in C'.\]
			Taking the infimum over $z\in C'$ implies $h(y) \geq f(y)$, hence $h \equiv f$ on $C'$.

			Now, $h$ is a real-valued convex function on $\R^n$ and thus admits a subgradient $v$ at $x$. 
			We claim that $v$ is a subgradient of $f$.
			The subgradient inequality for $h$ reads
			\[h(y)\geq h(x) + v^T(y-x) \text{ for all } y\in \R^n.\]
			Restricting to points in $C'$ where $h \equiv f$ this shows 
			$\tilde{f} := f-v^T(\cdot- x)$ is minimized
			over $C'$ at $x$. By definition of $C'$ it follows that $x$ is a local minimizer of $\tilde f$ on $C$,
			from which convexity of $\tilde f$ implies $x$ minimizes $\tilde f$ on $C$. This says exactly that 
			$v$ is a subgradient of $f$ at $x$.



		\end{subsection}

		\begin{subsection}{Example \ref{ex:distnotbuse2}}
			Let $\bar x = (0,0,0)$ be the reference point with respect to which we define our Busemann functions.
			Suppose for a contradiction that $f$ has a Busemann subgradient $[\xi,s]$ at $x_0 = (1,1,0)$. 
			As $x_0$ is not a minimizer of $f$, we have $s > 0$. Moreover,
			\begin{equation}
				\label{eqn:subatxzero}
				f(y) - sb_\xi(y) \geq \frac{\sqrt{2}}{2} - sb_\xi(x_0) \text{ for all } y\in X.
			\end{equation}

			\textbf{Case 1:} Suppose $\xi$ is the direction of the ray $\gamma$ issuing from $\bar x$ and passing
			through $x_0$. Taking $y = (1/2,1/2,0)$ we have $f(y) = 0, b_\xi(y) = -\sqrt{2}/2$, and $b_\xi(x_0) = -\sqrt{2}$, in
			contradiction to \eqref{eqn:subatxzero}.

			\textbf{Case 2:} Suppose $\xi$ is the direction of a ray $r$ in the plane $\st{z = 0}$ issuing from $\bar x$ and obtained
			by moving $\gamma$ an angle $\alpha\in (0,3\pi/4]$ in the trigonometric sense. Taking $y = (3/2,1/2,0)$, we have
			$f(y) = \sqrt{2}/2$ and $d(\bar x,y) = \sqrt{5}/\sqrt{2}$. Moreover, for all $t > 0$,
			\[					d(x_0,r(t))^2 = 2 + t^2 -2\sqrt{2}t\cos\alpha
			\]			and
\[				d(y,r(t))^2 = \frac{5}{2} + t^2 -2t(\sqrt{2}\cos\alpha- (1/\sqrt{2})\sin\alpha).\]
Hence, $b_\xi(x_0) = -\sqrt{2}\cos\alpha$ and $b_\xi(y) = -\sqrt{2}\cos\alpha + (1/\sqrt{2})\sin\alpha$, in contradiction to \eqref{eqn:subatxzero}.

\textbf{Case 3:} Suppose $\xi$ is the direction of a ray $r$ in the quadrant $\st{x\leq 0, y = 0, z\geq 0}$. Taking $y=(3/2,1/2,0)$,
we have $f(y) = \sqrt{2}/2$ and $b_\xi(x_0) \leq \sqrt{2}$.

Fix $t > 0$ and let $v = (-s,0,0)$, where $s\geq 0$, be such that $d(y,r(t)) = d(y,v) + d(v,r(t))$. Then $s\leq t$
and
\[d(y,r(t)) = d(v,r(t)) + \sqrt{\frac{5}{2}+s^2+3s} \geq t-s + \sqrt{\frac{5}{2}+s^2+3s} \geq \sqrt{\frac{5}{2}+t^2+3t}.\]

We conclude that $b_\xi(y) \geq 3/2$, so $b_\xi(y) > b_\xi(x_0)$, a contradiction.

The rest of the possible cases follow by symmetry.

		\end{subsection}

		\begin{subsection}{Example \ref{ex:nonhoro}}

			Defining $\tilde{x}= (2/5,0,0), \bar x = (1/4,1/4,0)$, we do some preliminary calculations:
			\begin{equation}
\label{eqn:prelim}
			\begin{aligned}
				f(\tilde{x}) &= \frac{1}{2}\left(d(\tilde{x},a_1)^2+ d(\tilde{x},a_2)^2\right) = 37/25,\\
				f(\bar{x}) &= \frac{1}{2}\left(d(\bar{x},a_1)^2+ d(\bar{x},a_2)^2\right) = 13/8.
		\end{aligned}
	\end{equation}
			Any ray issuing from $\bar x$ is determined by a choice of 
			unit vector $v = (v_1,v_2,0)$, or equivalently an angle $\theta\in[0,2\pi]$ such that 
			$v = (\cos \theta,\sin \theta,0)$. By symmetry it suffices to consider $\pi/4 \leq \theta \leq 5\pi/4$.
			We denote a ray $r$ originating from $\bar x$ in direction $v$ using the notation $r_v$.

		\textbf{Case 1:} 
		Corresponding to $\theta = 5\pi/4$ consider the direction $v= (-1/\sqrt{2},-1/\sqrt{2},0)$,
		pointing from $\bar x$ to the origin $\mathbf{0} := (0,0,0)$. Since the ray ultimately extends up the spine
		$\st{0}\times \st{0}\times
		\R_+$, for $t > 0$ sufficiently large the geodesic between $r_v(t)$ and any $x\in \R_+\times\R_+ \times\st{0}$ 
		consists of the two segments $[x,\mathbf{0}] \cup [\mathbf{0},r_v(t)]$. Hence
		\[d(x,r_v(t)) = \|x\|+ \|(t-\|\bar x\|)(0,0,1)\| = \|x\| + t- \|\bar x\| \text{ for all } t \geq \|\bar x\|.\]
	The corresponding Busemann function at such an $x$ is thus
	\[b_{r_v}(x) = \|x\| - \|\bar x\|.\]
		Plugging in $\tilde x$ we find $b_{r_v}(\tilde x) = 2/5 - \sqrt{2}/4 = (8-5\sqrt{2})/20 > 0$. On the other hand, the preliminary calculations (\ref{eqn:prelim}) show $f(\tilde{x}) < f(\bar x)$, so $\tilde{x}\in f_{\bar x}\setminus \st{b_{r_v}\leq 0}$
		i.e.\ this horoball does not contain the given level set.

		\textbf{Case 2:} Now consider any direction $v$ corresponding to $\pi < \theta < 5\pi/4$. After sufficient time,
		the point $r_v(t)$ will inhabit the upright quadrant
		$\R_-\times\st{0}\times\R_+$. By imagining the quadrant $\R_-\times\st{0}\times\R_+$ being folded down into 
		$\R_- \times \R_-\times\st{0}$, we see that for $t > 0$ large enough  the distance $d(\mathbf{0},r_v(t))$ is equal to the Euclidean distance $\|\bar x + tv\|$ when we identify $\bar x,v$ with vectors in $\R^3$.
		Since the geodesic from $\tilde{x}$ to such an $r_v(t)$ consists again of the 
		two segments $[\tilde{x},\mathbf{0}]\cup[\mathbf{0},r_v(t)]$,
		it follows that
		\[d(\tilde{x},r_v(t)) = \|\tilde{x}\| + \|\bar x + tv\|.\]
		The corresponding Busemann function evaluated at $\tilde{x}$ is thus 
		\[b_{r_v}(\tilde{x}) = \|\tilde{x}\| + v^T\bar x \geq \|\tilde{x}\| - \|\bar x\| > 0.\]
		As in the previous case we conclude $\tilde{x}\in f_{\bar x}\setminus \st{b_{r_v}\leq 0}$.

		\textbf{Case 3:} Finally, consider directions $v$ corresponding to $\pi/4 \leq \theta \leq \pi$. In this case we 
		have $d(\tilde{x}, r_v(t)) = \|\tilde{x} - \bar x - tv\|$, from which we deduce
		$b_{r_v}(\tilde{x}) = v^T(\bar x - \tilde{x})$. Using $v = (\cos\theta,\sin\theta,0)$ we find:
		\[b_{r_v}(\tilde{x}) =  -\frac{3}{20} \cos\theta + \frac{1}{4}\sin \theta.\]   
		Using calculus, one can show that the righthand side is a concave function of $\theta$ on $[\pi/4,\pi]$ and so attains its minimum at an endpoint. It is easy to check that the values at these endpoints are both positive, so $b_{r_v}(\tilde{x}) > 0$ for all such $\theta$. As before, $\tilde{x}\in f_{\bar x} \setminus \st{b_{r_v}\leq 0}$.
		We conclude that no ray issuing from $\bar x\in \bd f_{\bar x}$ supports $f_{\bar x}$, so $f_{\bar x}$ is not horospherically convex.

		Define the geodesic $\eta \from [0,1]\to X, \eta(t) = \bar x + (t/\sqrt{2})(1,1,0)$.
		We will show that $([\eta],3/\sqrt{2}) \in T_{\bar x} X$ is a subgradient for $f$ at $\bar x$. 
		According to \eqref{eqn:cat0subgrad} and the value computed for $f(\bar x)$ in \eqref{eqn:prelim},
		it suffices to prove 
		\begin{equation}
			\label{eqn:finalsubgrad}
		\frac{3}{\sqrt{2}}d(\bar x,y)\cos \angle (\eta,\gamma_y) + \frac{13}{8} \leq f(y) \text{ for all } y\in X.
	\end{equation}
		Despite the initial requirement that this inequality holds for all $y\in X$, 
		it is shown in \cite[Remark 3.3(iv)]{sumrule} that the subdifferential of a geodesically convex function 
		depends only on the function locally. Thus it suffices to verify \eqref{eqn:finalsubgrad} on a small ball 
		around $\bar x$ contained in the quadrant $Q = \R_+\times\R_+\times\st{0}$, say $B_{1/5}(\bar x)$.
		For $y = (y_1,y_2,0) \in Q$ we have
		\begin{equation}
			\label{eqn:fonQ}
		f(y) = \frac{1}{2}\left( (y_1+1)^2+y_2^2 + y_1^2 + (y_2+1)^2 \right).
		\end{equation}
		Furthermore, for $y \in B_{1/5}(\bar x)$ the geodesic segment $[\bar x,y]$ is 
		the Euclidean line segment joining these points in $Q$. It follows that $d(\bar x,y) = \|y-\bar x\|$ and
		\begin{equation}
			\label{eqn:anglexpr}
			\cos \angle(\eta,\gamma_y) =  \frac{(1,1,0)^T(y-\bar x)}{\sqrt{2}\|y-\bar x\|} = 
			\frac{y_1+y_2 -1/2}{\sqrt{2}\|y-\bar x\|}.
	\end{equation}
	Thus after restricting to $y\in B_{1/5}(\bar x)$ and substituting \eqref{eqn:fonQ} and \eqref{eqn:anglexpr}
	into \eqref{eqn:finalsubgrad}, our desired inequality becomes
		\[\frac{3}{2}y_1 + \frac{3}{2}y_2 + \frac{7}{8} \leq \frac{1}{2}\left( (y_1+1)^2+y_2^2 + y_1^2 + (y_2+1)^2 \right)
		\text{ for all } y = (y_1,y_2,0) \in B_{1/5}(\bar x).\]
		This now holds by the Euclidean subgradient inequality for the differentiable convex function
		$h(a,b) = \frac{1}{2}\left( (a+1)^2+b^2 + a^2 + (b+1)^2 \right)$ at the point $(1/4,1/4)$.
\end{subsection}

	\end{section}
