\title{The Complexity of Correlated Equilibria in Generalized Games}




\author{
    Martino Bernasconi\thanks{Bocconi University, \texttt{martino.bernasconi@unibocconi.it}}\and
    Matteo Castiglioni\thanks{Politecnico di Milano, \texttt{matteo.castiglioni@polimi.it}} \and
