In the rest of this section, we review related works in the literature on energy markets with locational (nonuniform) prices in electric grids, as well as the concept of DOEs which are required for further developments. Let $\mathbf p_i=( p_i(0), \dots,  p_i(T-1))^\top$, $\mathbf q_i=( q_i(0), \dots,  q_i(T-1))^\top$, and $\mathbf U_i=(\mathbf u_i^\top(0), \dots, \mathbf u_i^\top(T-1))^\top$ denote the vectors of active power injections,  reactive power injections, and control inputs associated with prosumer $i$ over the entire time horizon, respectively. Denote by $\mathbf p(t)= ( p_1(t), \dots,  p_N(t) )^\top$, $\mathbf q(t)= ( q_1(t), \dots,  q_N(t) )^\top$, and $\mathbf u(t)= (\mathbf u_1^\top(t), \dots, \mathbf u_N^\top(t) )^\top$ the vectors of  active power injections, reactive power injections, and control inputs associated with all prosumers at time step $t \in \mathcal{T}$, respectively. Also, let $\mathbf P=(\mathbf p^\top(0), \dots, \mathbf p^\top(T-1))^\top$, 
  $\mathbf Q=(\mathbf q^\top(0), \dots, \mathbf q^\top(T-1))^\top$, and $\mathbf U=(\mathbf u^\top(0), \dots, \mathbf u^\top(T-1))^\top$ denote  the vectors of all active power injection, reactive power injection, and control inputs associated with all prosumers at all time steps, respectively. 
\subsection{Competitive Market With Locational Pricing}\label{sec:preliminary_locational}
Market design in the presence of grid constraints, such as voltage and thermal constraints, potentially leads to different locational prices at different nodes. For example, \cite{li2015market} considers an islanded grid with a static formulation and proposes a competitive market for energy exchange that respects voltage constraints, leading to different locational prices at different nodes. Inspired by the work in \cite{li2015market}, we proposed a competitive market for energy exchange in  islanded electric grids with voltage constraints   considering a dynamic formulation  \cite{salehi2024acc}. In the following, we describe such a competitive market and the associated equilibrium point. 

Consider the system model introduced in Section \ref{sec:preliminaries}. For simplicity, we neglect thermal constraints and we only focus on voltage constraints in \eqref{eq_voltage}. Also, we suppose that reactive power injection is negligible at each node, i.e., $q_i(t)=0$ for $i \in \mathcal{N}, t \in \mathcal{T}$. Denote by $\lambda_i(t) \in \mathbb{R}$ the locational price at node $i\in \mathcal{N}$ and time step $t \in \mathcal T$ for unit active power exchange.  Prosumers $i \in \mathcal{N}$ are price takers who receive  price signals $\lambda_i(t)$ from the market operator and form a P2P competitive market among themselves. Each prosumer aims to maximize their payoff as the summation of their utilities $f_i(\mathbf x_i(t), \mathbf u_i(t))$  and $\phi_i(\mathbf x_i(T))$, representing their comfort level from consuming energy throughout the entire time horizon and at the terminal time step, and the income or expenditure $\lambda_i(t)p_i(t)$ from energy trading. Such a competitive market reaches an equilibrium if no participant has an incentive to change their decision unilaterally and the total traded power is balanced while the voltage constraints are satisfied.
\subsubsection{Competitive Equilibrium}
 A well-known equilibrium concept for competitive markets  is a \textit{competitive equilibrium} which is defined in the following. 
\begin{definition}[as in \cite{salehi2024acc}]\label{def0}
    Optimal decisions $(\mathbf u_1^\ast(t),  p_1^\ast(t), \dots, \mathbf u_N^\ast(t),  p_N^\ast(t))$, along with optimal locational prices $(\lambda_1^\ast(t), \cdots, \lambda_N^\ast(t))$ for all $t \in \mathcal{T}$, form a \textit{competitive equilibrium} if the following statements hold.

\begin{itemize}
    \item[(i)]  Given $\lambda^\ast_i (t)$, each prosumer $i$ maximizes their payoff  at $(\mathbf u_i^\ast(t),  p_i^\ast(t))$ for $t \in \mathcal{T}$ as a solution to 
\begin{equation}\label{eq_competitive_0}
%\resizebox {1\linewidth} {!} {$
\begin{aligned}
\max_{{\mathbf U_i}, \mathbf p_i} \quad &  \sum_{t=0}^{T-1} \Big(f_i(\mathbf x_i(t), \mathbf u_i(t)) + \lambda_i^\ast(t)  p_i(t) \Big)  +{\phi_i(\mathbf x_i(T)}) \\
{\rm s.t.} 
\quad &  \mathbf x_i(t+1)= \mathbf A_i \mathbf x_i(t)+ \mathbf B_i \mathbf u_i(t),  \\
\quad &   p_i(t) \leq  a_i (t)-  h_i(\mathbf u_i(t)),  \\
\quad &  \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, \,\,\, \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i,
	\,\,\,  t \in \mathcal{T}.
\end{aligned} %$}
\end{equation}


\item [(ii)] The total traded power is balanced at each time step, i.e., 
$
\sum_{i=1}^N  p_i^\ast(t) =0
$, for $t \in \mathcal{T}$.

 \item[(iii)] The voltage constraints are satisfied such that
	 $
	 	\underline {v}_i \leq v_0+ \sum_{k =1}^N R_{ik}  p_k^\ast(t) \leq \overline { v}_i
	 $ for $i \in \mathcal{N}$ and $t \in \mathcal{T}$.

		\item[(iv)] The locational prices satisfy %\begin{equation}\label{eq_locational_price}
    $\lambda_i^\ast(t)=\alpha^\ast(t)+\sum_{k=1}^{N} \big[\underline\xi_k^\ast(t)-\overline\xi_k^\ast (t) \big] R_{ki}$ for $i \in \mathcal{N}$ and $t \in \mathcal{T}$,
%\end{equation}
	where $\alpha^\ast(t)$ is the electricity price and $\underline\xi_k^\ast(t)-\overline\xi_k^\ast (t)$ is the  price for a unit voltage change at node $k$.

		\item[(v)]  If the voltage constraints are not binding, the price for voltage change is zero for $i \in \mathcal{N}$ and  $t \in \mathcal{T}$, i.e.,
		$
			\underline \xi_i^\ast(t)\Big(\underline v_i - v_0-\sum_{k =1}^N R_{ik}  p_k^\ast(t)\Big)=  \overline \xi_i^\ast(t) \Big( v_0+ \sum_{k =1}^N R_{ik}  p_k^\ast (t)-\overline{ v}_i \Big)=0
		$.

\end{itemize}
\end{definition}

\subsubsection{Social Welfare Maximization}
From a system-level perspective, a decision $(\mathbf u_1^\star(t),  p_1^\star(t),  \dots, \mathbf u_N^\star(t),  p_N^\star(t))$ for all $t \in \mathcal{T}$ is efficient if it maximizes the social welfare of the whole society  as a solution to \cite{salehi2024acc}
\begin{equation}\label{eq_social_locational}
		\begin{aligned}
			\max_{{\mathbf U}, \mathbf P} \quad &  \sum_{i=1}^{N}\Big(\sum_{t=0}^{T-1} f_i(\mathbf x_i(t), \mathbf u_i(t))+ {\phi_i(\mathbf x_i(T))} \Big)\\
			{\rm s.t.} 
			\quad &  \mathbf x_i(t+1)= \mathbf A_i \mathbf x_i(t)+ \mathbf B_i \mathbf u_i(t),  \\
			\quad &  p_i(t) \leq a_i (t)- h_i(\mathbf u_i(t)),  \\
			\quad &	\sum_{i=1}^N p_i(t) = 0,
			 \quad  \underline {v}_i \leq v_0+\sum_{k =1}^N R_{ik}  p_k(t) \leq \overline { v}_i, \\
			 \quad &\underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, \,\,\, \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i, \,\,\, i \in \mathcal{N}, \,\,\, t \in \mathcal{T}.
		\end{aligned}
	\end{equation}

\begin{assumption}\label{assumption1}
    Suppose $f_i(\cdot)$, $\phi_i(\cdot)$, and $-h_i(\cdot)$ are concave functions for $i \in \mathcal{N}$.
\end{assumption}

\begin{assumption}\label{assumption1_2}
     Slater's condition holds for \eqref{eq_competitive_0} and \eqref{eq_social_locational}. 
\end{assumption}


\begin{theorem}[as in \cite{salehi2024acc}]
    Let Assumptions \ref{assumption1} and \ref{assumption1_2} hold. Given feasible initial conditions $\mathbf x_i(0)$ for $i \in \mathcal{N}$, the competitive equilibrium in Definition \ref{def0} is equivalent to the social welfare maximization solution to \eqref{eq_social_locational}.
\end{theorem}

\subsection{Dynamic Operating Envelopes}
\begin{definition}[as in \cite{mahmoodi2023capacity}]
    A DOE refers to a nonempty, convex, and closed set $\Omega_{it}\subseteq \mathbb{R}^2$ in the $(p_{i}(t), q_i(t))$ coordinates that identifies a range for real and reactive power injections  at node $i$ and time $t$ that can be safely accommodated by the electric grid without violating operational constraints.
\end{definition}
DOEs are determined by a system operator responsible for the safe and secure operation of an electrical grid. To obtain DOEs associated with \eqref{eq:constraints}, we use the right-hand side decomposition (RHSD) method \cite{kornai1965two ,konnov2014right}, and decompose the right-hand side of \eqref{eq:constraints} as
\begin{equation}\label{eq:RHSD}
    \boldsymbol \nu(t) = \sum_{i=1}^N \mathbf w_i(t),
\end{equation}
where $\mathbf w_i(t) \in \mathbb{R}^M$ represents the share of prosumer $i$ in satisfying grid constraints at time interval $t$. Substituting  \eqref{eq:RHSD} into \eqref{eq:constraints} yields
$
    \sum_{i=1}^N \mathbf g_{it}( p_i(t),  q_i(t)) \leq \sum_{i=1}^N \mathbf w_i(t)
$,
which can be decomposed to 
$
   \mathbf g_{it}( p_i(t),  q_i(t)) \leq  \mathbf w_i(t)
$, for $i \in \mathcal{N}$.
Then, DOEs can be obtained as 
%\begin{equation}
$
    \Omega_{it}=\big\{(p_{i}(t), q_i(t)) \in \mathbb{R}^2: \mathbf g_{it}( p_i(t),  q_i(t)) \leq \mathbf w_i(t)\big\}$
%\end{equation}
for each prosumer $i\in \mathcal{N}$ at time step $t\in \mathcal{T}$ \cite{mahmoodi2023capacity}.

There exists an infinite number of configurations for $\mathbf w_i(t)$ that satisfy \eqref{eq:RHSD}, and therefore an infinite number of DOEs, among which the system operator looks for the one that optimizes its objective $\mathbb F (\mathbf p(t), \mathbf q(t))$. System operators can have different objectives in determining DOEs, such as maximizing social welfare, minimizing loss, and maximizing grid capacity. In this paper, we suppose that the operator aims to maximize the capacity of the electric grid by maximizing the total possible active power injection to the grid at each time step $t \in \mathcal{T}$, i.e., $\mathbb F (\mathbf p(t), \mathbf q(t))= \sum_{i=1}^N \max \{0, p_i(t)\}$. Denote $\mathbf w(t)=(\mathbf w_1^\top(t), \dots, \mathbf w_N^\top(t))^\top$. An optimal  $\mathbf w(t)$ that serves the objective of the system operator is then obtained solving
\begin{equation}\label{eq:DOE_2}
		\begin{aligned}
			\max_{\mathbf w(t), \mathbf p(t), \mathbf q(t)} \quad &  \sum_{i=1}^{N} \max\{0, p_i(t)\} - \epsilon O(\mathbf w(t)) \\
			{\rm s.t.} 
			\quad &
			 \mathbf g_{it}( p_i(t),  q_i(t)) \leq \mathbf w_i(t) \\
    \quad & \sum_{i=1}^N \mathbf w_i(t) = \boldsymbol \nu(t),
    \,\,\, i \in \mathcal{N},
		\end{aligned}
	\end{equation}
where $\epsilon O(\mathbf w(t))$ is a regularization term and $\epsilon$ is a small positive number. The function $O(\mathbf w(t)): \mathbb{R}^{NM} \mapsto \mathbb{R}$ indicates the  preferences of the operator in assigning different shares of DOEs to prosumers. For example, the operator might prefer to assign larger DOEs to prosumers closer to the feeder, or it might prefer to assign near equal DOEs to all prosumers. 
Following \cite{mahmoodi2023capacity}, we adopt the notion of close-to-equal contributions to promote fairness in assigning DOEs.
%This approach aims to provide prosumers with fair and close-to-equal contributions without harming the main objective of the operator which is maximizing the active power injection to the microgrid. 
Denote by  $\overline{\mathbf{E}} \in \mathbb R^{NM}, \overline{\mathbf{E}}=(\boldsymbol \nu^\top(t)/N, \dots, \boldsymbol \nu^\top(t)/N)^\top$ the equality index. A function $O(\mathbf w(t))$ that leads to close-to-equal contributions can be defined as 
    \begin{equation}    \label{eq:close_to_equal}  
    O(\mathbf w(t))=\|\mathbf w(t)- \overline{\mathbf{E}} \|.
    \end{equation}

Then, solving \eqref{eq:DOE_2}, the operator obtains $\mathbf w^\ast(t)=(\mathbf w_1^{\ast\top}(t), \dots, \mathbf w_N^{\ast\top}(t))^\top$ and sends the DOEs 
\begin{equation}\label{eq_DOE_3}
\mathbf g_{it}( p_i(t),  q_i(t)) \leq \mathbf w_i^\ast(t)   
\end{equation}
to the associated prosumers $i \in \mathcal{N}$ at each time step $t \in \mathcal{T}$. 

%In this paper, we focus on close-to-equal contributions and select $O(\mathbf w(t))=O_2(\mathbf w(t))$ as in \eqref{eq:close_to_equal} to improve fairness.
%
