\subsection{Competitive Market With DOEs}\label{sec:uniform_1}
% In this section, we define a competitive market with uniform pricing that satisfies the network constraints \eqref{eq:constraints}.
A P2P competitive energy market for the islanded radial grid introduced in Section \ref{sec:preliminaries} can be designed in which prosumers are price takers and they receive a uniform  price signal $\lambda(t) \in \mathbb{R}$ for unit energy trading from the market operator at each time step $t \in \mathcal{T}$. Prosumers trade their local electricity supply with their peers according to the announced price signal and the assigned DOEs $\mathbf g_{it}( p_i(t),  q_i(t)) \leq \mathbf w_i^\ast(t)$. They aim to maximize their payoff as the summation of their utility $f_i(\mathbf x_i(t), \mathbf u_i(t))$ and $\phi_i(\mathbf x_i(T))$, representing their comfort/satisfaction level from energy consumption throughout the entire time horizon and at the terminal time step, respectively, and the income or expenditure $\lambda(t)p_i(t)$ from energy transaction. Since energy transaction is done through the electric grid, the grid constraints must be always satisfied to enable a safe and secure system operation. Using DOEs, the grid constraints are decomposed to some local constraints that would be accommodated by each participant independently. Such a market is at an equilibrium if no participant has an incentive to change their decision and the  total traded power is balanced.  

\subsubsection{Competitive Equilibrium}
An equilibrium point for the prescribed competitive market falls into the category of \textit{competitive equilibrium} and is defined in the following.
\begin{definition}\label{def2}
   Optimal decisions $(\mathbf u_1^\ast(t),  p_1^\ast(t),  \dots, \mathbf u_N^\ast(t),  p_N^\ast(t))$, along with uniform optimal prices $ \lambda^\ast(t)$ for all $t \in \mathcal{T}$, form a \textit{competitive equilibrium} if the following statements hold.
   \begin{itemize}
       \item [(i)] Given $ \lambda^\ast(t)$ and $\mathbf w_i^\ast(t)$, each prosumer $i \in \mathcal{N}$ maximizes their payoff at $(\mathbf u_i^\ast(t), p_i^\ast(t))$ for $t \in \mathcal{T}$ as a solution to
       \begin{equation} \label{eq_competitive_2}
			\begin{aligned}		\max_{{\mathbf U_i}, \mathbf p_i} \quad &  \sum_{t=0}^{T-1} \Big(f_i(\mathbf x_i(t), \mathbf u_i(t)) +\lambda^\ast(t) p_i(t) \Big)+{\phi_i(\mathbf x_i(T)}) \\
				{\rm s.t.} 
				\quad &  \mathbf x_i(t+1)= \mathbf A_i \mathbf x_i(t)+ \mathbf B_i \mathbf u_i(t),  \\
				\quad &  p_i(t) \leq a_i (t)- h_i(\mathbf u_i(t)),  \,\,\, \mathbf g_{it}( p_i(t)) \leq \mathbf w_i^\ast(t), 
    \\
				\quad &
    \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, %\\
				%\quad & 
   \,\,\, \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i, 
				\,\,\,  t \in \mathcal{T}.
			\end{aligned}
		\end{equation}

  \item [(ii)] All traded power is balanced at each time step; that is,
  $
      \sum_{i=1}^N p_i^\ast(t)=0
  $ for $t \in \mathcal{T}$.
   \end{itemize}
\end{definition}

\subsubsection{Social Welfare Maximization}
From a system-level perspective, a decision $(\mathbf u_1^\star(t),  p_1^\star(t),  \dots, \mathbf u_N^\star(t),  p_N^\star(t))$ for all $t \in \mathcal{T}$ is efficient if it maximizes the social welfare of the whole society, defined  as the summation of all utilities $f_i(\cdot)$ and $\phi_i(\cdot)$ of all participants, as a solution to
\begin{equation}\label{eq_social_2}
		\begin{aligned}
			\max_{{\mathbf U}, \mathbf P} \quad &  \sum_{i=1}^{N}\Big(\sum_{t=0}^{T-1} f_i(\mathbf x_i(t), \mathbf u_i(t))+ {\phi_i(\mathbf x_i(T))} \Big)\\
			{\rm s.t.} 
			\quad &  \mathbf x_i(t+1)= \mathbf A_i \mathbf x_i(t)+ \mathbf B_i \mathbf u_i(t),  \\
			\quad &  p_i(t) \leq a_i (t)- h_i(\mathbf u_i(t)),   \\
				\quad & \mathbf g_{it}( p_i(t)) \leq \mathbf w_i^\ast(t), \,\,\,	\sum_{i=1}^N p_i(t) = 0,     \\
				\quad &
    \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, %\\
				%\quad & 
   \,\,\, \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i, 
				\,\,\,   i \in \mathcal{N}, \,\,\, t \in \mathcal{T}.
		\end{aligned}
	\end{equation}

\begin{assumption}\label{assumption2}
 Slater's condition holds for \eqref{eq_competitive_2} and \eqref{eq_social_2}. 
\end{assumption}

\begin{theorem}\label{theorem2}
    Let Assumptions \ref{assumption1} and \ref{assumption2} hold. Given feasible initial conditions $\mathbf x_i(0)$ for $i \in \mathcal{N}$, the following statements hold.
    \begin{itemize}
        \item A competitive equilibrium in Definition \ref{def2} is equivalent to a social welfare maximization solution to \eqref{eq_social_2}. 
        \item Let $-\alpha^\ast(t)$ be an optimal dual variable corresponding to the balancing equality constraint $\sum_{i=1}^N p_i(t)=0$ in \eqref{eq_social_2} for $t\in \mathcal{T}$. Then, a uniform equilibrium price can be obtained as $\lambda^\ast(t)=\alpha^\ast(t)$.
        \end{itemize}
\end{theorem}
\begin{proof}
    See Appendix \ref{Appendix_Theorem2}.  
\end{proof}

%\begin{remark}
Using DOEs to decompose the global constraints into local ones makes the approach conservative. That is, in some cases, the assigned DOEs are potentially infeasible to implement in the proposed competitive market due to insufficient generation or consumption. 
To mitigate this conservatism, we introduce an additional degree of freedom in decision-making by designing a competitive market that permits limit trading in DOEs. 
%\end{remark}



\subsection{Competitive Market With Limit Trading in DOEs}\label{sec:main_limit}
The idea of limit trading in DOEs was first introduced in \cite{umer2023novel}, which enhances the utilization of grid capacity in the presence of DOEs. If some prosumers  have excess DOE limits $\mathbf w_i^\ast(t)-\mathbf g_{it}(p_i(t))$, they can sell them to those who have shortage of DOE limits. Denote by $\boldsymbol l_i(t) \in \mathbb R^M$ the traded limit of prosumer $i$ that is physically constrained by $\boldsymbol l_i(t) \leq \mathbf w_i^\ast(t)-\mathbf g_{it}(p_i(t))$.
Limit trading introduces an additional degree of freedom for prosumers to trade their excess of  DOE limits, which are not otherwise used, and gain profit. Denote by $\boldsymbol \beta(t)\in \mathbb{R}^M$ the uniform limit price for unit traded DOE limit. Obtaining the DOE limits  $\mathbf{w}_i^\ast(t)$ according to \eqref{eq:DOE_2},
 the coordinator identifies optimal uniform electricity prices $\lambda^\ast(t)$ and limit prices $\boldsymbol \beta^\ast(t)$ that clear the market for $t \in \mathcal{T}$, which are then broadcast to market participants. After receiving the uniform electricity prices and limit prices, prosumers form a P2P competitive market to trade their energy and limit resources and gain profit. Each prosumer aims to maximize their payoff as the summation of their utility $f_i(\mathbf x_i(t), \mathbf u_i(t))$ and $\phi_i(\mathbf x_i(T))$, and the income $\lambda(t)p_i(t)+\boldsymbol\beta(t) \cdot \boldsymbol l_i(t)$ from electricity and limit trading over the entire time horizon. 

 \subsubsection{Competitive Equilibrium}
 An equilibrium point for such a market falls into the category of \textit{competitive equilibrium} and is defined in the following.
 \begin{definition}\label{def3}
     Optimal decisions $(\mathbf u_1^\ast(t),  p_1^\ast(t), \boldsymbol l_1^\ast(t), \dots, \mathbf u_N^\ast(t),  p_N^\ast(t), \boldsymbol l_N^\ast(t))$, along with optimal uniform prices $ \lambda^\ast(t)$ and $\boldsymbol \beta^\ast(t)$ for all $t \in \mathcal{T}$, form a \textit{competitive equilibrium} if the following statements hold.
     \begin{itemize}
         \item [(i)] Given $\lambda^\ast(t)$, $\boldsymbol \beta^\ast(t)$, and $\mathbf w_i^\ast(t)$, each prosumer $i \in \mathcal{N}$ maximizes their payoff at $(\mathbf u_i^\ast(t), p_i^\ast(t), \boldsymbol l_i^\ast(t))$ for $t \in \mathcal{T}$ as a solution to       
         \begin{equation}\label{eq17}
			%\resizebox {0.447\textwidth} {!} {$
			\begin{aligned}
				\max_{{\mathbf U_i}, \mathbf p_i, \mathbf L_i} \quad &  \sum_{t=0}^{T-1} f_i(\mathbf x_i(t), \mathbf u_i(t)) + {\phi_i(\mathbf x_i(T)}) \\ &+ \sum_{t=0}^{T-1} \Big( \lambda^\ast(t) p_i(t)+\boldsymbol  \beta^\ast(t) \cdot \boldsymbol l_i(t)\Big) \\
				{\rm s.t.} 
				\quad &  \mathbf x_i(t+1)= \mathbf A_i \mathbf x_i(t)+ \mathbf B_i \mathbf u_i(t),  \\
				\quad &  p_i(t) \leq a_i (t)- h_i(\mathbf u_i(t)),  \\
				\quad & \boldsymbol l_i(t) \leq \mathbf w_i^\ast(t)-\mathbf g_{it}( p_i(t)), \\
				\quad &
    \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, %\\
				%\quad & 
   \,\,\, \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i, 
				\,\,\,  t \in \mathcal{T},
			\end{aligned}%$}
		\end{equation}
where $\mathbf L_i=(\boldsymbol l_i^\top(0), \dots, \boldsymbol l_i^\top(T-1))^\top$ is the vector of all traded limits associated with participant $i$ over the entire time horizon.
  \item [(ii)] All traded power and all traded limit are balanced at each time step; that is,
  $
      \sum_{i=1}^N p_i^\ast(t)=0 $ and $\sum_{i=1}^N \boldsymbol l_i^\ast(t)=0$ for $t\in \mathcal{T}
  $.
     \end{itemize}
 \end{definition}


 \subsubsection{Social Welfare Maximization}
 From a system-level perspective, a decision $(\mathbf u_1^\star(t),  p_1^\star(t), \boldsymbol l_1^\star,  \dots, \mathbf u_N^\star(t),  p_N^\star(t), \boldsymbol l_N^\star)$ for all $t \in \mathcal{T}$ is efficient if it maximizes the social welfare of the whole society, defined  as the summation of all utilities $f_i(\cdot)$ and $\phi_i(\cdot)$ of all participants, as a solution to
 \begin{equation}\label{eq2}
		\begin{aligned}
			\max_{{\mathbf U}, \mathbf P, \mathbf L} \quad &  \sum_{i=1}^{N}\Big(\sum_{t=0}^{T-1} f_i(\mathbf x_i(t), \mathbf u_i(t))+ {\phi_i(\mathbf x_i(T))} \Big)\\
			{\rm s.t.} 
			\quad &  \mathbf x_i(t+1)= \mathbf A_i \mathbf x_i(t)+ \mathbf B_i \mathbf u_i(t),  \\
			\quad &  p_i(t) \leq a_i (t)- h_i(\mathbf u_i(t)),   \\
				\quad & \boldsymbol l_i(t) \leq \mathbf w_i^\ast(t)-\mathbf g_{it}( p_i(t)) \\
			\quad &	\sum_{i=1}^N p_i(t) = 0, \,\,\,	\sum_{i=1}^N \boldsymbol l_i(t) = 0, 
    \\
				\quad &
    \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, %\\
				%\quad & 
   \,\,\, \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i, 
				\,\,\,   i \in \mathcal{N}, \,\,\, t \in \mathcal{T},
		\end{aligned}
	\end{equation}
where $\mathbf L=(\mathbf L_1^\top, \dots, \mathbf L_N^\top)^\top$ is the vector of all traded limits associated with all participants over the entire time horizon.


\begin{assumption}\label{assumption3}
 Slater's condition holds for \eqref{eq17} and \eqref{eq2}. 
\end{assumption}
\begin{theorem}\label{theorem3}
Let Assumptions \ref{assumption1} and \ref{assumption3} hold. Given feasible initial conditions $\mathbf x_i(0)$ for $i \in \mathcal{N}$, the following statements hold.
\begin{itemize}
    \item A competitive equilibrium in Definition \ref{def3} is equivalent to a social welfare maximization solution to \eqref{eq2}. 
    \item Let $-\alpha^\ast(t)$ and $-\boldsymbol \delta^\ast(t)$ be optimal dual variables corresponding to the balancing equality constraints $\sum_{i=1}^N p_i(t)=0$ and $\sum_{i=1}^N \boldsymbol l_i(t)=0$ in \eqref{eq2}, respectively, for $t\in \mathcal{T}$. Then,  uniform equilibrium prices can be obtained as $\lambda^\ast(t)=\alpha^\ast(t)$ and $\boldsymbol \beta^\ast(t)=\boldsymbol \delta^\ast(t)$ for $t\in \mathcal{T}$.
    \end{itemize}
\end{theorem}
\begin{proof}
    See Appendix \ref{Appendix_Theorem3}.
\end{proof}

