\subsection{Connection Between Locational and Uniform Pricing}
In this section, we examine the connection between the competitive market with limit trading in DOEs, proposed in Section \ref{sec:main_limit}, and the competitive market with locational pricing introduced in Section \ref{sec:preliminary_locational}. For simplicity, we consider only voltage constraints in the grid to be consistent with the formulation provided in Section \ref{sec:preliminary_locational}.

\begin{theorem}\label{theorem4}
    Let Assumptions \ref{assumption1}, \ref{assumption1_2}, and \ref{assumption3} hold. Then, the competitive market with limit trading in DOEs, proposed in Section \ref{sec:main_limit}, is equivalent to the competitive market with locational pricing introduced in Section \ref{sec:preliminary_locational}. To be precise, if $(\mathbf U^\star, \mathbf P^\star)$ maximizes \eqref{eq_social_locational}, then there exists $\mathbf L^\star$ such that $(\mathbf U^\star, \mathbf P^\star, \mathbf L^\star)$ maximizes \eqref{eq2}, and vice versa.
\end{theorem}
\begin{proof}
   See Appendix \ref{Appendix_Theorem4}. 
\end{proof}

The next theorem shows that  optimal uniform prices proposed in Section \ref{sec:main_limit} are part of  optimal locational prices introduced in Section \ref{sec:preliminary_locational}. From Definition \ref{def0}, the locational prices are given by $\lambda_i^\ast(t)=\alpha^\ast(t)+\sum_{k=1}^{N} \big[\underline\xi_k^\ast(t)-\overline\xi_k^\ast (t) \big] R_{ki}$ for $i \in \mathcal{N}$ and $ t \in \mathcal{T}$. For simplicity, define $\alpha^\ast_i(t)=\sum_{k=1}^{N} \big[\underline\xi_k^\ast(t)-\overline\xi_k^\ast (t) \big] R_{ki}$, which represents the second part of the locational prices. Thus, $\lambda_i^\ast(t)=\alpha^\ast(t)+\alpha^\ast_i(t)$.

\begin{theorem}\label{theorem5}
     Let Assumptions \ref{assumption1}, \ref{assumption1_2}, and \ref{assumption3} hold. Consider optimal locational prices in Section \ref{sec:preliminary_locational} which are defined as $\lambda_i^\ast(t)=\alpha^\ast(t)+\alpha^\ast_i(t)$. Then, optimal uniform  prices $\lambda^\ast(t)$ obtained in the competitive market approach with limit trading in DOEs, proposed in Section \ref{sec:main_limit}, satisfy  $\lambda^\ast(t)=\alpha^\ast(t)$.
\end{theorem}
\begin{proof}
See Appendix \ref{Appendix_Theorem5}.
\end{proof}

\begin{definition}[as in \cite{li2020transactive, ma2020incentive}]
A mechanism is strongly budget balanced (or weakly budget balanced) if the summation of all payments collected by the system coordinator is zero (or nonegative).
\end{definition}

\begin{proposition}\label{proposition_2}
The following statements hold. 
\begin{itemize}
    \item[(i)] The competitive market with locational pricing in Section \ref{sec:preliminary_locational} is weakly budget balanced under the competitive equilibria, i.e.,  $-\sum_{i=1}^N \lambda_i^\ast(t)p_i^\ast(t) \geq 0$ for $t \in \mathcal{T}$.
    \item[(ii)] In contrast, the proposed uniform pricing approaches guarantee that the market is strongly budget balanced under the competitive equilibria, i.e., $\sum_{i=1}^N \lambda^\ast(t)p_i^\ast(t)=0$ and $\sum_{i=1}^N \boldsymbol  \beta^\ast(t) \cdot \boldsymbol l_i^\ast(t)=0$ for $t \in \mathcal{T}$.
\end{itemize}
\end{proposition}

\begin{proof}
See Appendix \ref{Appendix_Proposition_2}.
\end{proof}


Consider the competitive market with locational pricing in Section \ref{sec:preliminary_locational}. If the market operator collects all payments, which are not zero in general, and distributes the associated budget surplus $-\sum_{i=1}^N \lambda_i^\ast(t)p_i^\ast(t)$ to prosumers equally, it is equivalent to  assigning the same DOE limits $\mathbf w_i^\ast(t)=\boldsymbol \nu (t) /N$ to all prosumers in  the design of the competitive market with limit trading in DOEs introduced in Section \ref{sec:main_limit}. In other words, if the system operator assigns different DOE limits $\mathbf w_i^\ast(t)$ to prosumers in  Section \ref{sec:main_limit}, it is equivalent to distributing the budget surplus $-\sum_{i=1}^N \lambda_i^\ast(t)p_i^\ast(t)$, obtained from the locational pricing approach, to prosumers in a nonuniform manner. This result is proved in the following proposition.

\begin{proposition}\label{proposition1}
    Consider the competitive market with locational pricing in Section \ref{sec:preliminary_locational}. Distributing the budget surplus $-\sum_{i=1}^N \lambda_i^\ast(t)p_i^\ast(t)$ equally to  prosumers is equivalent to assigning prosumers the same DOE limits $\mathbf w_i^\ast(t)=\boldsymbol \nu (t) /N$ in  Section \ref{sec:main_limit}, which considers uniform pricing with limit trading in DOEs. 
\end{proposition}
\begin{proof}
    See Appendix \ref{Appendix_Proposition1}.
\end{proof}
