	\centering
	\includegraphics[width=3.35 in]{figure/Feeder.png}
	%	\centerline{\psfig{figure=fig_2.png,width=2.7in}}
	\caption{Modified IEEE 13-node test feeder. Left: A prosumer $i$ is zoomed in, connected to the electric grid at the point of common coupling (PCC).}
