\section{Proof of Theorem \ref{theorem2}}\label{Appendix_Theorem2}
Let $(\mathbf U^\ast, \mathbf P^\ast)$, along with ${\lambda}^\ast(t)$ for $t \in \mathcal{T}$, be a competitive equilibrium. Merging optimization problems in \eqref{eq_competitive_2} for $i \in \mathcal{N}$ implies that $(\mathbf U^\ast, \mathbf P^\ast)$ maximizes the social welfare in \eqref{eq_social_2}. 

    The proof of the reverse direction is based on strong duality, which follows from the satisfaction of Slater's condition. Considering the difference equation \eqref{eq_state}, the state $\mathbf x_i(t)$ evolves according to a linear combination of the initial state $\mathbf x_i(0)$ and the control input $\mathbf U_i$ such that
\begin{equation}\label{eq2_2}
	\mathbf x_i(t)=\mathbf A_i^t \mathbf x_i(0)+ \sum_{j=0}^{t-1}{\mathbf A_i^{t-j-1} \mathbf B_i \mathbf u_i(j)}, \quad t \in \{1, 2, ..., T\}.
\end{equation}
The substitution of \eqref{eq2_2} into  $f_i(\cdot)$ and $\phi_i(\cdot)$ results in
$
		f_i(\mathbf x_i(t), \mathbf u_i(t)) = \tilde{f}_{i,t}(\mathbf U_i)$ and
		$\phi_i(\mathbf x_i(T)) = \tilde{\phi}_i(\mathbf U_i),
$
where functions $\tilde{f}_{i,t}(\cdot)$ and $\tilde{\Phi}_i(\cdot)$ are concave as the composition of a concave function and an affine function. For $i \in \mathcal{N}$, denote $\mathbb{U}_i =\{ \mathbf U_i| \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i;  \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, \text{for } t \in \mathcal{T}\}$,  which is a polyhedral set. For any $(\mathbf U, \mathbf P)$ such that $\mathbf U_i \in \mathbb{U}_i$, the Lagrangian function of \eqref{eq_social_2} is defined as
\begin{equation}\label{eq15_0}
	\begin{aligned}
	&\mathcal L(\mathbf U, \mathbf P,\boldsymbol{\alpha}, \boldsymbol\Psi, \boldsymbol \Pi) = - \sum_{i=1}^{N}\Big(\sum_{t=0}^{T-1} \tilde{f}_{i,t}( \mathbf U_i)+\tilde{\phi}_i(\mathbf U_i) \Big) 
	\\&+ \sum_{t=0}^{T-1}\alpha(t) \Big(-\sum_{i=1}^N p_i(t) \Big) 
	+ \sum_{t=0}^{T-1}\sum_{i=1}^{N} \psi_{i}(t) \Big( p_i(t) +h_i(\mathbf u_i(t)) \\&-a_i(t)\Big)
 + \sum_{t=0}^{T-1}\sum_{i=1}^{N} \boldsymbol \pi_{i}(t) \cdot \Big(\mathbf g_i( p_i(t))-\mathbf w_i^\ast(t)\Big),
\end{aligned}
\end{equation}
where $\psi_{i}(t) \geq 0$, $\boldsymbol \pi_i(t) \geq 0$, $\boldsymbol \alpha =(\alpha(0), \dots, \alpha({T-1}))^\top$,   $\boldsymbol\Psi_i =(\psi_{i}(0), \dots, \psi_{i}(T-1))^\top$, and $ {\boldsymbol\Psi} = ( {\boldsymbol\Psi}_1^\top, \dots,  {\boldsymbol\Psi}_N^\top)^\top$. We define $\boldsymbol\Pi_i$ and  $\boldsymbol\Pi$  in a similar way. 
The Lagrangian  \eqref{eq15_0}  is separable such that
\begin{equation}\label{eq16_0}
	\mathcal L(\mathbf U, \mathbf P, \boldsymbol{\alpha},  \boldsymbol\Psi, \boldsymbol \Pi) = \sum_{i=1}^{N} \mathcal L_i(\mathbf U_i, \mathbf p_i, \boldsymbol{\alpha}, \boldsymbol\Psi_i, \boldsymbol \Pi_i),
\end{equation}
where
%\begin{equation}\label{eq9_0}
%	\begin{aligned}
$	\mathcal L_i (\mathbf U_i, \mathbf p_i,  \boldsymbol{\alpha},  \boldsymbol\Psi_i, \boldsymbol \Pi_i)
	=- \sum_{t=0}^{T-1} \Big(\tilde{f}_{i,t}(\mathbf U_i)+\alpha(t)  p_i(t) 
	 \Big) 
	+  \sum_{t=0}^{T-1} \psi_{i}(t) \Big( p_i(t)+h_i(\mathbf u_i(t))-a_i(t) \Big) + \sum_{t=0}^{T-1}\boldsymbol \pi_{i}(t) \cdot \Big( \mathbf g_i( p_i(t))-\mathbf w_i^\ast(t)\Big) - \tilde{\phi}_i(\mathbf U_i) $.
%\end{aligned}
%\end{equation}
Let $(\mathbf U^\star, \mathbf P^\star)$ be an optimal primal solution to  \eqref{eq_social_2}, and  $(-\boldsymbol{\alpha}^\ast,  \boldsymbol{\Psi}^\ast , \boldsymbol{\Pi}^\ast)$ be an optimal dual solution. Given that Slater's condition is satisfied, strong duality leads to %\cite{boyd2004convex}
\begin{equation}\label{eq_primal_4_0}
	(\mathbf U^\star, \mathbf P^\star) \in  \arg \min_{\mathbf U, \mathbf P} \mathcal L(\mathbf U, \mathbf P,  \boldsymbol{\alpha}^\ast,  \boldsymbol\Psi^\ast, \boldsymbol\Pi^\ast),
\end{equation}
for $ \mathbf U_i \in \mathbb{U}_i$. 
Considering \eqref{eq16_0} and \eqref{eq_primal_4_0}, there holds
\begin{equation}\label{eq13_0}
	(\mathbf U_i^\star,  \mathbf p_i^\star) \in \arg \min_{\mathbf U_i, \mathbf p_i} \mathcal L_i( \mathbf U_i,  \mathbf p_i,  \boldsymbol \alpha^\ast, \boldsymbol{\Psi}_i^\ast, \boldsymbol{\Pi}_i^\ast),
\end{equation}
for $ \mathbf U_i \in \mathbb{U}_i$. 
In addition, strong duality implies
 $(\boldsymbol{\alpha}^\ast, \boldsymbol{\Psi}^\ast, \boldsymbol{\Pi}^\ast) \in \arg \max_{\boldsymbol \alpha,  \boldsymbol{\Psi}, \boldsymbol{\Pi}} \min_{\mathbf U, \mathbf P} 	\mathcal L(\mathbf U, \mathbf P,  \boldsymbol{\alpha},  \boldsymbol\Psi, \boldsymbol\Pi) 
	= \arg \max_{\boldsymbol \alpha,\boldsymbol{\Psi}, \boldsymbol{\Pi}} \min_{\mathbf U, \mathbf P} 	\sum_{i=1}^{N} \mathcal L_i(\mathbf U_i, \mathbf p_i,  \boldsymbol{\alpha},  \boldsymbol\Psi_i, \boldsymbol\Pi_i)$ and 
\begin{equation}\label{eq12_0}
	(\boldsymbol{\Psi}_i^\ast, \boldsymbol{\Pi}_i^\ast)  \in  \arg \max_{\boldsymbol \Psi_i, \boldsymbol \Pi_i} \min_{\mathbf U_i, \mathbf p_i}  \mathcal L_i(\mathbf U_i, \mathbf p_i,  \boldsymbol{\alpha}^\ast,  \boldsymbol\Psi_i, \boldsymbol\Pi_i),
\end{equation}
where the primal and dual variables are in their respective domains. Considering  $\lambda^\ast(t)=\alpha^\ast(t)$  for $t \in \mathcal{T}$, the function $ \mathcal L_i(\mathbf U_i, \mathbf p_i,  \boldsymbol{\alpha}^\ast, \boldsymbol\Psi_i, \boldsymbol\Pi_i)$ is the Lagrangian  of \eqref{eq_competitive_2}. 
Therefore,   $(\mathbf \Psi_i^\ast, \mathbf \Pi_i^\ast)$ is an optimal dual solution of \eqref{eq_competitive_2} according to \eqref{eq12_0}.  Given that
Slater's condition is satisfied, strong duality implies that according to  \eqref{eq13_0}, $(\mathbf U^\star, \mathbf P^\star)$ is an optimal primal solution of \eqref{eq_competitive_2}  which satisfies $\sum_{i=1}^N p_i^\ast(t)=0$ for $t\in \mathcal{T}$. 
Consequently, $( \mathbf U^\star, \mathbf P^\star)$, along with $\lambda^\ast(t)=\alpha^\ast(t)$  for $t \in \mathcal{T}$, forms a competitive equilibrium.

