 \\&+ \sum_{t=0}^{T-1}\sum_{i=1}^{N} \boldsymbol \pi_{i}(t) \cdot \Big( \boldsymbol l_i(t) +\mathbf g_i( p_i(t))-\mathbf w_i^\ast(t)\Big),
