\section{Proof of Theorem \ref{theorem5}}\label{Appendix_Theorem5}
Recall that $\mathbb{U}_i =\{ \mathbf U_i| \underline{\mathbf u}_i\leq \mathbf u_i(t) \leq \overline{\mathbf u}_i;  \underline{\mathbf x}_i \leq \mathbf x_i(t) \leq \overline{\mathbf x}_i, \text{for } t \in \mathcal{T}\}$ for  $i \in \mathcal{N}$,  which is a polyhedral set. For any $(\mathbf U, \mathbf P)$ such that $\mathbf U_i \in \mathbb{U}_i$, 
the Lagrangian function of \eqref{eq_social_locational} is defined as 
\begin{equation}\label{eq5}
	\begin{aligned}
	&\mathcal L(\mathbf U, \mathbf P, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi) = - \sum_{i=1}^{N}\Big(\sum_{t=0}^{T-1} \tilde{f}_{i,t}( \mathbf U_i)+\tilde{\phi}_i(\mathbf U_i) \Big) 
	\\&+ \sum_{t=0}^{T-1}\alpha(t) \Big(-\sum_{i=1}^N p_i(t) \Big) 
	+\sum_{t=0}^{T-1}\sum_{i=1}^{N}\underline\xi_{i}(t) \Big( \underline v_i -v_0 \\&- \sum_{k =1}^N R_{ik}  p_k(t) \Big) 
	+ \sum_{t=0}^{T-1}\sum_{i=1}^{N}\overline\xi_{i}(t) \Big( v_0+ \sum_{k =1}^N R_{ik}  p_k(t)-\overline v_i \Big) 
	\\&+ \sum_{t=0}^{T-1}\sum_{i=1}^{N} \psi_{i}(t) \Big( p_i(t) +h_i(\mathbf u_i(t))-a_i(t)\Big),
\end{aligned}
\end{equation}
where $\underline\xi_{i}(t), \overline\xi_{i}(t), \psi_{i}(t) \geq 0$, $\boldsymbol \alpha =(\alpha(0), \dots, \alpha({T-1}))^\top$, $ \underline{\boldsymbol\Xi}_i =(\underline\xi_{i}(0), \dots, \underline\xi_{i}(T-1))^\top$, and $ \underline{\boldsymbol\Xi} = ( \underline{\boldsymbol\Xi}_1^\top, \dots,  \underline{\boldsymbol\Xi}_N^\top)^\top$. We define $\overline{\boldsymbol\Xi}_i, \overline{\boldsymbol\Xi}$, and $\boldsymbol\Psi_i, \boldsymbol\Psi$ in a similar manner. 
The Lagrangian  \eqref{eq5}  is separable such that 
\begin{equation}\label{eq6}
	\mathcal L(\mathbf U, \mathbf P, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi) = \sum_{i=1}^{N} \mathcal L_i(\mathbf U_i, \mathbf p_i, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi_i),
\end{equation}
where
\begin{equation}\label{eq9}
	\begin{aligned}
	\mathcal L_i &(\mathbf U_i, \mathbf p_i, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi_i)
	=- \sum_{t=0}^{T-1} \Big(\tilde{f}_{i,t}(\mathbf U_i)+\alpha(t)  p_i(t) 
	 \\ &+ \sum_{k=1}^{N} \underline\xi_{k}(t)  R_{ki}  p_i(t)  - \sum_{k=1}^{N} \overline\xi_{k}(t)  R_{ki}  p_i(t) \\&-\underline\xi_{i}(t) (\underline v_i -v_0)  +\overline\xi_{i}(t)  (\overline v_i -v_0) \Big) - \tilde{\phi}_i(\mathbf U_i) 
	\\&+  \sum_{t=0}^{T-1} \psi_{i}(t) \Big( p_i(t)+h_i(\mathbf u_i(t))-a_i(t)\Big).
\end{aligned}
\end{equation}

Let $(\mathbf U^\star, \mathbf P^\star)$ be an optimal primal solution to \eqref{eq_social_locational}, and  $(-\boldsymbol{\alpha}^\ast, \underline{\boldsymbol \Xi}^\ast, \overline{\boldsymbol\Xi}^\ast, \boldsymbol{\Psi}^\ast)$ be an optimal dual solution. Given that Slater's condition is satisfied, strong duality yields %\cite{boyd2004convex}
\begin{equation}\label{eq_primal}
	(\mathbf U^\star, \mathbf P^\star) \in \arg \min_{\mathbf U, \mathbf P} \mathcal L(\mathbf U, \mathbf P, \boldsymbol{\alpha}^\ast, \underline{\boldsymbol\Xi}^\ast, \overline{\boldsymbol\Xi}^\ast, \boldsymbol\Psi^\ast),
\end{equation}
for $ \mathbf U_i \in \mathbb{U}_i$. Denote
\begin{equation}\label{eq10}
	\begin{aligned}
		&\tilde {\mathcal L}_i (\mathbf U_i, \mathbf p_i, \mathbf S_i, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi_i) =  - \sum_{t=0}^{T-1} \Big(\tilde{f}_{i,t}(\mathbf U_i)+\alpha(t)  p_i(t)
		\\ &+ \sum_{k=1}^{N} \underline\xi_{k}(t)  R_{ki}  p_i(t)  - \sum_{k=1}^{N} \overline\xi_{k}(t)  R_{ki}  p_i(t) +\sum_{k=1}^N\underline{  \xi}_k(t)  \underline{ w}_{ki}^\ast(t) \\&+\sum_{k=1}^N \overline{  \xi}_k(t)  \overline{ w}_{ki}^\ast(t)
  -\sum_{k=1}^N\underline{  \xi}_k(t)  \underline{ s}_{ki}(t)-\sum_{k=1}^N \overline{  \xi}_k(t)  \overline{ s}_{ki}(t)\Big)
		\\&+  \sum_{t=0}^{T-1} \psi_{i}(t) \Big( p_i(t)+h_i(\mathbf u_i(t))-a_i(t)\Big)- \tilde{\phi}_i(\mathbf U_i) ,
	\end{aligned}
\end{equation}
where $\mathbf s_i(t)=(\overline{ s}_{1i}(t), \dots, \overline{ s}_{Ni}(t), \underline{ s}_{1i}(t), \dots, \underline{ s}_{Ni}(t))^\top$, $\mathbf S_i=(\mathbf s_i^\top(0), \dots, \mathbf s_i^\top(T-1))^\top$, and $\mathbf S_i \geq 0$.
Considering \eqref{eq6} and \eqref{eq_primal}, we obtain
$
	(\mathbf U_i^\star,  \mathbf p_i^\star) \in \arg \min_{\mathbf U_i, \mathbf p_i} \mathcal L_i( \mathbf U_i,  \mathbf p_i, \boldsymbol \alpha^\ast, \underline{\boldsymbol \Xi}^\ast, \overline{\boldsymbol \Xi}^\ast, \boldsymbol{\Psi}_i^\ast)$.
    Since $\underline\xi_{k}(t)\geq 0$ and $\overline\xi_{k}(t) \geq 0$, there holds 
\begin{equation}\label{eq18}
		(\mathbf U_i^\star,  \mathbf p_i^\star) \in \arg \min_{\mathbf U_i, \mathbf p_i, \mathbf S_i}  \tilde{\mathcal L}_i ( \mathbf U_i,  \mathbf p_i, \mathbf S_i, \boldsymbol \alpha^\ast, \underline{\boldsymbol \Xi}^\ast, \overline{\boldsymbol \Xi}^\ast, \boldsymbol{\Psi}_i^\ast),
\end{equation}
for $ \mathbf U_i \in \mathbb{U}_i$. In addition, strong duality implies
\begin{multline*}
%\begin{aligned}
	(\boldsymbol{\alpha}^\ast, \underline{\boldsymbol \Xi}^\ast, \overline{\boldsymbol\Xi}^\ast, \boldsymbol{\Psi}^\ast) \in \arg \max_{\boldsymbol \alpha, \underline{\boldsymbol \Xi}, \overline{\boldsymbol \Xi}, \boldsymbol{\Psi}} \min_{\mathbf U, \mathbf P} 	\mathcal L(\mathbf U, \mathbf P, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi) 
	\\= \arg \max_{\boldsymbol \alpha, \underline{\boldsymbol \Xi}, \overline{\boldsymbol \Xi}, \boldsymbol{\Psi}} \min_{\mathbf U, \mathbf P} 	\sum_{i=1}^{N} \mathcal L_i(\mathbf U_i, \mathbf p_i, \boldsymbol{\alpha}, \underline{\boldsymbol\Xi}, \overline{\boldsymbol\Xi}, \boldsymbol\Psi_i),
%\end{aligned}
\end{multline*}
and
$
	\boldsymbol{\Psi}_i^\ast \in \arg \max_{\boldsymbol \Psi_i} \min_{\mathbf U_i, \mathbf p_i} \mathcal L_i(\mathbf U_i, \mathbf p_i, \boldsymbol{\alpha}^\ast, \underline{\boldsymbol\Xi}^\ast, \overline{\boldsymbol\Xi}^\ast, \boldsymbol\Psi_i)
$.
Consequently, there holds 
\begin{equation}\label{eq7}
	\boldsymbol{\Psi}_i^\ast \in \arg \max_{\boldsymbol \Psi_i} \min_{\mathbf U_i, \mathbf p_i, \mathbf S_i} \tilde {\mathcal L}_i(\mathbf U_i, \mathbf p_i, \mathbf S_i, \boldsymbol{\alpha}^\ast, \underline{\boldsymbol\Xi}^\ast, \overline{\boldsymbol\Xi}^\ast, \boldsymbol\Psi_i),
\end{equation}
where the primal and dual variables are considered to be in their respective domains. The function $\tilde{\mathcal L}_i(\mathbf U_i, \mathbf p_i, \mathbf S_i, \boldsymbol{\alpha}^\ast, \underline{\boldsymbol\Xi}^\ast, \overline{\boldsymbol\Xi}^\ast, \boldsymbol\Psi_i)$ is the Lagrangian  of \eqref{eq17} if we define
\begin{equation}\label{eq11}
\begin{aligned}
 \mathbf g_{it}(p_i(t))&=(R_{1i}, \dots, R_{Ni}, -R_{1i},  \dots, -R_{Ni})^\top p_i(t), 
 \\
  \mathbf{w}^\ast_i(t) &= (\overline w^\ast_{1i}(t), \dots, \overline w^\ast_{Ni}(t), \underline w^\ast_{1i}(t), \dots, \underline w^\ast_{Ni}(t))^\top,\\
  \boldsymbol l_i(t)&= \mathbf{w}^\ast_i(t) - \mathbf g_{it}(p_i(t))- \mathbf s_i(t), \,\,\, \lambda^\ast(t)=\alpha^\ast(t), \\ \boldsymbol \beta^\ast(t)&=(\overline \xi^\ast_1(t), \dots, \overline{\xi}^\ast_N(t), \underline \xi_1^\ast(t), \dots, \underline \xi_N^\ast(t))^\top.
 \end{aligned}
\end{equation}
Consequently,  according to \eqref{eq7}, $\mathbf \Psi_i^\ast$ is an optimal dual solution of \eqref{eq17}.  Besides, since Slater's condition holds, strong duality implies that according to  \eqref{eq18}, $(\mathbf U^\star, \mathbf P^\star)$ is an optimal primal solution of \eqref{eq17}. % satisfying \eqref{constraint_balancing}--\eqref{constraint_voltage}. 
Select the elements of $\mathbf L^\ast$ as
$
       \boldsymbol l_i^\ast(t)= \mathbf w_i^\ast(t)-\mathbf g_i(p_i^\star(t))+ \frac{1}{N}\big(\sum_{i=1}^N \mathbf g_i(p_i^\star(t))-\sum_{i=1}^N \mathbf w_i^\ast (t)\big)$,
   which satisfies $\boldsymbol l_i^\ast(t) \leq \mathbf{w}_i^\ast(t)- \mathbf g_i(p_i^\star(t))$ and $\sum_{i=1}^N \boldsymbol l_i^\ast(t)=0$.
Then, the tuple $( \mathbf U^\star, \mathbf P^\star, \mathbf L^\ast)$, along with $ {\lambda}^\ast(t)$ and $ \boldsymbol \beta^\ast(t)$ for $t \in \mathcal{T}$, forms a competitive equilibrium for \eqref{eq17}. 

