  double sum(double* matrix, 
           int n, int m, int T) {
    double sum = 0;
    #pragma omp parallel for \ 
    reduce(+: sum) num_threads(T)
    for (int i = 0; i < n*m; i++)
      sum += matrix[I];
    return sum;
  }
        \end{lstlisting}
        \caption{\textbf{Illustrative kernel summing the elements of a matrix} with three input parameters (\texttt{matrix}, \texttt{n}, \texttt{m}), and one design parameter (\texttt{T}).}
        \label{lst:simple_kernel_example}
        \Description{We can define an illustrative kernel, a C++ function that sums every element of a matrix using OpenMP. This C++ function takes four arguments, n and m, the size of the matrix, a pointer to the data, and T, the number of threads}
    \end{minipage}\hspace{.25cm}
    \begin{minipage}{.45\textwidth}
