\subsection{Comparison with other auto-tuners}
\subsubsection{Comparison to Optuna}
\label{sec:mlkaps_vs_optuna}
\begin{figure}[tb]
    \centering
    \vspace{-5mm}
    \begin{subfigure}{\linewidth}
        \centering
